window.DATA = {"units": [{"unit": {"id": "u1", "number": 1, "title": "Acasă, în familie, printre cărți", "summary": "Textul narativ și descriptiv literar în proză, narațiunea la persoana I, legenda și contextul de comunicare; sinonime, antonime, sensuri, omonime, diftong/triftong/hiat și despărțirea în silabe; redactarea unei narațiuni la persoana I."}, "lessons": [{"id": "u1-l1", "number": 1, "title": "Textul narativ literar în proză", "section": "Lectură", "pages": "p. 10-12", "source": "Un păianjen care se crede Spiderman - Adina Popescu", "theory": [], "flashcards": [], "quiz": []}, {"id": "u1-l2", "number": 2, "title": "Narațiunea. Acțiunea. Timpul și spațiul", "section": "Lectură", "pages": "p. 13", "source": "Un păianjen care se crede Spiderman - Adina Popescu", "theory": [{"term": "Textul narativ", "kind": "definition", "text": "Textul narativ prezintă derularea unor întâmplări în ordine logică și temporală.", "examples": [], "important": true}, {"term": "Secvențele textului narativ", "kind": "rule", "text": "În funcție de timpul și spațiul în care se petrece acțiunea, de personajele cu rolul cel mai important, textul narativ poate fi delimitat în secvențe distincte, asemănătoare cu scenele dintr-un film.", "examples": [], "important": true}, {"term": "Indicii de timp", "kind": "rule", "text": "Indicii de timp trimit, de obicei, la acțiunea din prim-plan, care reprezintă firul principal al narațiunii. Uneori, aceștia se referă și la alte momente, petrecute înainte sau după acțiunea din prim-plan.", "examples": [], "important": true}], "flashcards": [{"front": "Ce prezintă textul narativ?", "back": "Derularea unor întâmplări în ordine logică și temporală.", "n": [0]}, {"front": "Cu ce sunt asemănătoare secvențele unui text narativ?", "back": "Cu scenele dintr-un film.", "n": [1]}, {"front": "După ce criterii se delimitează secvențele unui text narativ?", "back": "Timpul, spațiul și personajele cu rolul cel mai important.", "n": [1]}, {"front": "Ce este acțiunea din prim-plan?", "back": "Firul principal al narațiunii.", "n": [2]}, {"front": "La ce trimit, de obicei, indicii de timp?", "back": "La acțiunea din prim-plan; uneori și la momente de dinainte sau de după ea.", "n": [2]}], "quiz": [{"type": "mcq", "q": "Textul narativ prezintă:", "options": ["descrierea unui obiect, a unei ființe sau a unui loc", "derularea unor întâmplări în ordine logică și temporală", "o discuție între doi interlocutori", "o listă de cuvinte fără legătură între ele"], "answer": 1, "why": "Definiția textului narativ: derularea unor întâmplări în ordine logică și temporală.", "n": [0]}, {"type": "tf", "q": "Secvențele unui text narativ sunt asemănătoare cu scenele dintr-un film.", "answer": true, "why": "Așa spune cartea: secvențe distincte, asemănătoare cu scenele dintr-un film.", "n": [1]}, {"type": "fill", "q": "Indicii de timp trimit, de obicei, la acțiunea din ____, care reprezintă firul principal al narațiunii.", "answers": ["prim-plan", "prim plan"], "why": "Acțiunea din prim-plan este firul principal.", "n": [2]}, {"type": "mcq", "q": "Care dintre următoarele NU este criteriu pentru delimitarea secvențelor unui text narativ?", "options": ["timpul în care se petrece acțiunea", "spațiul în care se petrece acțiunea", "personajele cu rolul cel mai important", "numărul de pagini al cărții"], "answer": 3, "why": "Criteriile sunt timpul, spațiul și personajele principale.", "n": [1]}, {"type": "tf", "q": "Indicii de timp pot trimite și la momente petrecute înainte sau după acțiunea din prim-plan.", "answer": true, "why": "„Uneori, aceștia se referă și la alte momente, petrecute înainte sau după acțiunea din prim-plan.”", "n": [2]}, {"type": "match", "q": "Potrivește termenul cu explicația lui.", "pairs": [["Text narativ", "întâmplări în ordine logică și temporală"], ["Secvență", "parte a textului delimitată după timp, spațiu, personaje"], ["Acțiunea din prim-plan", "firul principal al narațiunii"]], "n": [0, 1, 2]}]}, {"id": "u1-l3", "number": 3, "title": "Narațiunea la persoana I. Autorul, naratorul, personajul", "section": "Lectură", "pages": "p. 14-15", "source": "Un păianjen care se crede Spiderman - Adina Popescu", "theory": [{"term": "Narator și personaje", "kind": "definition", "text": "Într-un text narativ literar, există narator și personaje, prin intermediul cărora cititorul află ce și cum se întâmplă într-o narațiune.", "examples": [], "important": true}, {"term": "Naratorul și persoana verbului", "kind": "rule", "text": "Naratorul poate relata o întâmplare folosind persoana a III-a sau persoana I. Când este folosită persoana I, naratorul este în același timp și personaj. Acesta relatează evenimentele din perspectiva sa.", "examples": ["Un păianjen care se crede Spiderman: păianjenul este narator-personaj"], "important": true}, {"term": "Personajele", "kind": "definition", "text": "Personajele îndeplinesc acțiunile, având contribuții diferite la evenimentele relatate. Într-un text narativ literar, personajele pot să fie ființe umane, dar și ființe necuvântătoare sau obiecte.", "examples": [], "important": true}, {"term": "Ficțiunea", "kind": "definition", "text": "Personajele și naratorul nu există în realitate, ci trăiesc doar în paginile cărții, în lumea inventată de autor, adică în ficțiune.", "examples": [], "important": true}, {"term": "Autorul", "kind": "definition", "text": "Autorul este o persoană cu identitate concretă în lumea reală, care construiește o lume imaginară, ficțională.", "examples": [], "important": true}, {"term": "Autor și narator", "kind": "rule", "text": "Autorul și naratorul nu pot fi confundați, pentru că ei aparțin unor planuri diferite: autorul face parte din lumea reală, în vreme ce naratorul aparține ficțiunii, lumii inventate de autor.", "examples": [], "important": true}, {"term": "Schema autor - narator - personaje (schemă ilustrată, exercițiu)", "kind": "tip", "text": "În schema din carte, AUTORUL aparține lumii reale, iar NARATORUL și PERSONAJELE aparțin lumii inventate (ficțiunii), reprezentate de textul narativ.", "examples": [], "important": false, "derived": true}], "flashcards": [{"front": "Prin cine află cititorul ce se întâmplă într-o narațiune?", "back": "Prin narator și personaje.", "n": [0]}, {"front": "Când este naratorul și personaj?", "back": "Când relatează la persoana I.", "n": [1]}, {"front": "Cine este autorul?", "back": "O persoană cu identitate concretă în lumea reală, care construiește o lume ficțională.", "n": [4]}, {"front": "Ce este ficțiunea?", "back": "Lumea inventată de autor, în care trăiesc naratorul și personajele.", "n": [3]}, {"front": "De ce nu pot fi confundați autorul și naratorul?", "back": "Autorul aparține lumii reale, naratorul aparține ficțiunii.", "n": [5]}, {"front": "Ce pot fi personajele într-un text narativ literar?", "back": "Ființe umane, ființe necuvântătoare sau obiecte.", "n": [2]}], "quiz": [{"type": "mcq", "q": "Când naratorul relatează la persoana I, el este:", "options": ["doar observator", "și personaj", "chiar autorul", "un cititor"], "answer": 1, "why": "La persoana I naratorul este în același timp și personaj.", "n": [1]}, {"type": "tf", "q": "Autorul și naratorul aparțin aceluiași plan, deci pot fi confundați.", "answer": false, "why": "Autorul aparține lumii reale, naratorul ficțiunii.", "n": [5]}, {"type": "fill", "q": "Personajele și naratorul trăiesc doar în lumea inventată de autor, adică în ____.", "answers": ["ficțiune", "fictiune"], "why": "Lumea inventată de autor se numește ficțiune.", "n": [3]}, {"type": "mcq", "q": "Care dintre următoarele poate fi personaj într-un text narativ literar?", "options": ["doar o ființă umană", "doar un animal", "ființe umane, ființe necuvântătoare sau obiecte", "doar autorul"], "answer": 2, "why": "Personajele pot fi ființe umane, necuvântătoare sau obiecte.", "n": [2]}, {"type": "classify", "q": "Încadrează în lumea căreia îi aparține.", "categories": ["Lumea reală", "Lumea inventată (ficțiunea)"], "items": [{"t": "autorul", "c": 0}, {"t": "naratorul", "c": 1}, {"t": "personajele", "c": 1}], "n": [3, 4, 5]}, {"type": "tf", "q": "Naratorul poate relata o întâmplare la persoana a III-a sau la persoana I.", "answer": true, "why": "Definiția din Repere.", "n": [1]}, {"type": "match", "q": "Potrivește termenul cu descrierea.", "pairs": [["Autor", "persoană cu identitate concretă din lumea reală"], ["Narator", "cel prin care cititorul află întâmplările"], ["Personaje", "îndeplinesc acțiunile"], ["Ficțiune", "lumea inventată de autor"]], "n": [0, 2, 3, 4]}]}, {"id": "u1-l4", "number": 4, "title": "Semnificațiile textului", "section": "Lectură", "pages": "p. 16", "source": "Un păianjen care se crede Spiderman - Adina Popescu", "theory": [], "flashcards": [], "quiz": []}, {"id": "u1-l5", "number": 5, "title": "Textul descriptiv literar în proză", "section": "Lectură", "pages": "p. 17-18", "source": "Indescriptibil - Simona Popescu", "theory": [], "flashcards": [], "quiz": []}, {"id": "u1-l6", "number": 6, "title": "Descrierea în proză", "section": "Lectură", "pages": "p. 19", "source": "Indescriptibil - Simona Popescu", "theory": [{"term": "Textul descriptiv literar", "kind": "definition", "text": "Textul descriptiv literar constă în prezentarea sugestivă a unui obiect, a unei ființe sau a unui loc.", "examples": [], "important": true}, {"term": "Rolul descrierii", "kind": "rule", "text": "Descrierea are rolul de a ajuta cititorul să-și imagineze obiectul, ființa sau locul prezentat/evocat.", "examples": [], "important": true}, {"term": "Simțurile în descriere", "kind": "rule", "text": "Într-o descriere, pot fi menționate percepții care țin de toate cele cinci simțuri (văz, auz, gust, miros, pipăit). De asemenea, pot fi exprimate sentimente și emoții, gânduri privitoare la obiectele, ființele sau locurile descrise.", "examples": ["Arată ca ...; Sună ca ...; Are gust de ...; Miroase ca ...; Se simte ca ..."], "important": true}], "flashcards": [{"front": "Ce este textul descriptiv literar?", "back": "Prezentarea sugestivă a unui obiect, a unei ființe sau a unui loc.", "n": [0]}, {"front": "Care este rolul descrierii?", "back": "Ajută cititorul să-și imagineze obiectul, ființa sau locul.", "n": [1]}, {"front": "Care sunt cele cinci simțuri care pot apărea într-o descriere?", "back": "Văzul, auzul, gustul, mirosul, pipăitul.", "n": [2]}, {"front": "Ce altceva poate fi exprimat într-o descriere, pe lângă percepții?", "back": "Sentimente, emoții, gânduri despre cele descrise.", "n": [2]}], "quiz": [{"type": "mcq", "q": "Textul descriptiv literar prezintă sugestiv:", "options": ["doar întâmplări", "un obiect, o ființă sau un loc", "doar sentimente", "un dialog"], "answer": 1, "why": "Definiția din Repere.", "n": [0]}, {"type": "tf", "q": "Într-o descriere pot fi menționate percepții legate de toate cele cinci simțuri.", "answer": true, "why": "Văz, auz, gust, miros, pipăit.", "n": [2]}, {"type": "fill", "q": "Descrierea are rolul de a ajuta cititorul să-și ____ obiectul, ființa sau locul prezentat.", "answers": ["imagineze"], "why": "Rolul descrierii este să stimuleze imaginația cititorului.", "n": [1]}, {"type": "classify", "q": "Încadrează după simțul la care se referă.", "categories": ["Văz", "Auz", "Miros"], "items": [{"t": "verde", "c": 0}, {"t": "zumzăit", "c": 1}, {"t": "parfumat", "c": 2}, {"t": "strălucitor", "c": 0}, {"t": "zgomotos", "c": 1}], "n": [2]}, {"type": "tf", "q": "Într-o descriere literară nu pot fi exprimate sentimente sau emoții.", "answer": false, "why": "Pot fi exprimate sentimente, emoții și gânduri despre cele descrise.", "n": [2]}]}, {"id": "u1-l7", "number": 7, "title": "Semnificațiile textului", "section": "Lectură", "pages": "p. 20", "source": "Indescriptibil - Simona Popescu", "theory": [], "flashcards": [], "quiz": []}, {"id": "u1-l8", "number": 8, "title": "Texte continue și discontinue", "section": "Lectură", "pages": "p. 21", "source": "", "theory": [{"term": "Textele continue", "kind": "definition", "text": "Textele continue sunt organizate în propoziții și paragrafe. Pot fi texte literare, în proză sau în versuri, sau texte nonliterare, precum articole, lucrări științifice sau reportaje.", "examples": ["articole", "lucrări științifice", "reportaje"], "important": true}, {"term": "Textele discontinue", "kind": "definition", "text": "Textele discontinue prezintă informații organizate sub forma unor secvențe de text fără legătură între ele sau sub forma unor liste, grafice, diagrame. Textele discontinue pot fi table de materii, liste, tabele, calendare, grafice, articole de dicționar, scheme.", "examples": ["tabla de materii", "lista", "tabelul", "calendarul", "graficul", "articolul de dicționar", "schema"], "important": true}], "flashcards": [{"front": "Cum sunt organizate textele continue?", "back": "În propoziții și paragrafe.", "n": [0]}, {"front": "Cum sunt organizate textele discontinue?", "back": "Secvențe de text fără legătură între ele sau liste, grafice, diagrame.", "n": [1]}, {"front": "Dă trei exemple de texte discontinue.", "back": "Tabel, listă, calendar (și grafic, schemă, tablă de materii, articol de dicționar).", "n": [1]}, {"front": "Dă exemple de texte continue nonliterare.", "back": "Articole, lucrări științifice, reportaje.", "n": [0]}], "quiz": [{"type": "classify", "q": "Încadrează textele.", "categories": ["Text continuu", "Text discontinuu"], "items": [{"t": "reportaj", "c": 0}, {"t": "calendar", "c": 1}, {"t": "poezie", "c": 0}, {"t": "articol de dicționar", "c": 1}, {"t": "tabel", "c": 1}, {"t": "lucrare științifică", "c": 0}], "n": [0, 1]}, {"type": "mcq", "q": "Textele continue sunt organizate în:", "options": ["liste și tabele", "propoziții și paragrafe", "grafice și diagrame", "secvențe fără legătură"], "answer": 1, "why": "Definiția din Repere.", "n": [0]}, {"type": "tf", "q": "Articolul de dicționar este un text discontinuu.", "answer": true, "why": "Este menționat printre textele discontinue.", "n": [1]}, {"type": "tf", "q": "Textele literare în versuri sunt texte discontinue.", "answer": false, "why": "Textele literare, în proză sau în versuri, sunt continue.", "n": [0]}, {"type": "fill", "q": "Un text care prezintă informații sub formă de liste, grafice sau diagrame este un text ____.", "answers": ["discontinuu"], "why": "Acestea sunt texte discontinue.", "n": [1]}]}, {"id": "u1-l9", "number": 9, "title": "Noi pagini – alte idei", "section": "Lectură", "pages": "p. 22-23", "source": "Lectura în trei, în doi, de unul singur - Rodica Zane (din Care-i faza cu cititul?)", "theory": [{"term": "Jurnalul cu dublă intrare", "kind": "definition", "text": "Jurnalul cu dublă intrare ajută cititorul să stabilească legături între text și propriile experiențe. O pagină se împarte în două coloane egale: în stânga, cititorul notează un pasaj din text care i-a atras atenția, în dreapta, explică de ce a notat pasajul, la ce l-a făcut să se gândească.", "examples": ["stânga: pasajul din text; dreapta: explicația și gândurile cititorului"], "important": false}], "flashcards": [{"front": "La ce ajută jurnalul cu dublă intrare?", "back": "Ajută cititorul să stabilească legături între text și propriile experiențe.", "n": [0]}, {"front": "Ce se notează în coloana din stânga a jurnalului cu dublă intrare?", "back": "Un pasaj din text care i-a atras atenția cititorului.", "n": [0]}, {"front": "Ce se notează în coloana din dreapta?", "back": "De ce a notat pasajul și la ce l-a făcut să se gândească.", "n": [0]}], "quiz": [{"type": "mcq", "q": "În coloana din dreapta a jurnalului cu dublă intrare se notează:", "options": ["pasajul din text", "titlul cărții", "explicația alegerii și gândurile cititorului", "numele autorului"], "answer": 2, "why": "În dreapta cititorul explică de ce a notat pasajul.", "n": [0]}, {"type": "tf", "q": "Jurnalul cu dublă intrare împarte pagina în două coloane egale.", "answer": true, "why": "Așa este definit.", "n": [0]}, {"type": "fill", "q": "În coloana din stânga a jurnalului cu dublă intrare se notează un ____ din text care ți-a atras atenția.", "answers": ["pasaj", "fragment"], "why": "În stânga se notează pasajul.", "n": [0]}, {"type": "tf", "q": "Jurnalul cu dublă intrare ajută cititorul să facă legături între text și experiențele proprii.", "answer": true, "why": "Acesta este rolul lui.", "n": [0]}]}, {"id": "u1-l10", "number": 10, "title": "Valori etice în legendele popoarelor", "section": "Interculturalitate", "pages": "p. 24-25", "source": "Legenda albinei și a păianjenului - după o legendă culeasă de George Coșbuc", "theory": [{"term": "Legenda", "kind": "definition", "text": "Legenda este un text narativ care prezintă întâmplări miraculoase despre originea unor ființe sau lucruri, despre faptele unor eroi sau despre evenimente istorice, evidențiind valori precum binele, adevărul, frumosul.", "examples": [], "important": true}, {"term": "Tipurile legendelor", "kind": "classification", "text": "Există două tipuri de legende:\n• legende mitologice, numite de B.P. Hasdeu deceuri, care explică originea, existența, caracteristicile unor fenomene, personaje, geneza astrelor, a pământului, a florei sau a faunei etc.;\n• legende istorice, care explică, prin fapte imaginare, evenimente și personaje reale din istorie.", "examples": [], "important": true}, {"term": "Legendele popoarelor", "kind": "rule", "text": "Legendele popoarelor propun explicații diferite privitoare la aceleași fenomene, ființe sau evenimente.", "examples": ["păianjenul în mitologia greacă (Arahne), în tradiția islamică și la tribul Hopi (Femeia Păianjen)"], "important": true}], "flashcards": [{"front": "Ce este legenda?", "back": "Text narativ cu întâmplări miraculoase despre originea unor ființe sau lucruri, faptele unor eroi sau evenimente istorice, evidențiind valori (binele, adevărul, frumosul).", "n": [0]}, {"front": "Care sunt cele două tipuri de legende?", "back": "Legende mitologice și legende istorice.", "n": [1]}, {"front": "Cum le numește B.P. Hasdeu pe legendele mitologice?", "back": "Deceuri.", "n": [1]}, {"front": "Ce explică legendele istorice?", "back": "Evenimente și personaje reale din istorie, prin fapte imaginare.", "n": [1]}, {"front": "Ce valori evidențiază legendele?", "back": "Binele, adevărul, frumosul.", "n": [0]}, {"front": "Ce propun legendele diferitelor popoare?", "back": "Explicații diferite pentru aceleași fenomene, ființe sau evenimente.", "n": [2]}], "quiz": [{"type": "mcq", "q": "Legendele mitologice sunt numite de B.P. Hasdeu:", "options": ["balade", "deceuri", "fabule", "basme"], "answer": 1, "why": "Hasdeu le numește deceuri.", "n": [1]}, {"type": "tf", "q": "Legendele istorice explică, prin fapte imaginare, evenimente și personaje reale din istorie.", "answer": true, "why": "Definiția legendelor istorice.", "n": [1]}, {"type": "fill", "q": "Legenda este un text ____ care prezintă întâmplări miraculoase.", "answers": ["narativ"], "why": "Legenda este un text narativ.", "n": [0]}, {"type": "classify", "q": "Încadrează tipul legendei.", "categories": ["Legendă mitologică", "Legendă istorică"], "items": [{"t": "explică geneza astrelor", "c": 0}, {"t": "explică originea florei și a faunei", "c": 0}, {"t": "explică prin fapte imaginare un eveniment real din istorie", "c": 1}, {"t": "explică originea pământului", "c": 0}], "n": [1]}, {"type": "mcq", "q": "Ce valori evidențiază, de regulă, legenda?", "options": ["binele, adevărul, frumosul", "bogăția și puterea", "viteza și forța", "umorul și ironia"], "answer": 0, "why": "Legenda evidențiază valori precum binele, adevărul, frumosul.", "n": [0]}, {"type": "tf", "q": "Toate popoarele explică același fenomen în același fel în legendele lor.", "answer": false, "why": "Legendele popoarelor propun explicații diferite.", "n": [2]}]}, {"id": "u1-l11", "number": 11, "title": "Contextul de comunicare", "section": "Comunicare orală", "pages": "p. 26-27", "source": "", "theory": [{"term": "Importanța contextului", "kind": "definition", "text": "În comunicare sunt importante atât cuvintele și enunțurile în sine, cât și contextul în care apar, pentru că acesta influențează ceea ce înțelegem într-o situație de comunicare dată.", "examples": [], "important": true}, {"term": "Componentele contextului de comunicare", "kind": "classification", "text": "Contextul de comunicare este alcătuit din următoarele componente:\n• datele privitoare la circumstanțele comunicării și la persoanele care participă la comunicare (identitatea participanților la comunicare, statutul lor social, locul și momentul comunicării);\n• informațiile deținute de interlocutori, opiniile și intențiile lor de comunicare;\n• locul în care apare enunțul în cadrul unei secvențe comunicative (la început, la mijloc, la final).", "examples": [], "important": true}, {"term": "Adaptarea la context", "kind": "rule", "text": "Pentru a comunica eficient, vorbitorii trebuie să adapteze limbajul, modul de adresare, tonalitatea și ritmul vorbirii, precum și informația vehiculată la contextul de comunicare.", "examples": [], "important": true}], "flashcards": [{"front": "De ce este important contextul în comunicare?", "back": "Influențează ceea ce înțelegem într-o situație de comunicare dată.", "n": [0]}, {"front": "Care sunt componentele contextului de comunicare?", "back": "Circumstanțele și participanții; informațiile, opiniile și intențiile interlocutorilor; locul enunțului în secvența comunicativă.", "n": [1]}, {"front": "Ce intră în datele despre circumstanțele comunicării?", "back": "Identitatea și statutul social al participanților, locul și momentul comunicării.", "n": [1]}, {"front": "Ce trebuie să adapteze vorbitorii pentru a comunica eficient?", "back": "Limbajul, modul de adresare, tonalitatea, ritmul vorbirii și informația transmisă.", "n": [2]}, {"front": "Unde poate apărea un enunț în secvența comunicativă?", "back": "La început, la mijloc sau la final.", "n": [1]}], "quiz": [{"type": "mcq", "q": "Care dintre acestea NU este o componentă a contextului de comunicare?", "options": ["identitatea participanților", "locul și momentul comunicării", "intențiile de comunicare ale interlocutorilor", "numărul de cuvinte din enunț"], "answer": 3, "why": "Numărul de cuvinte nu este component al contextului.", "n": [1]}, {"type": "tf", "q": "Contextul influențează ceea ce înțelegem într-o situație de comunicare.", "answer": true, "why": "Așa spune cartea.", "n": [0]}, {"type": "fill", "q": "Pentru a comunica eficient, vorbitorii trebuie să adapteze limbajul, modul de adresare, tonalitatea și ____ vorbirii la contextul de comunicare.", "answers": ["ritmul", "ritmul vorbirii"], "why": "Se adaptează limbajul, adresarea, tonalitatea și ritmul.", "n": [2]}, {"type": "classify", "q": "Încadrează elementele în componenta contextului din care fac parte.", "categories": ["Circumstanțe și participanți", "Informații, opinii, intenții"], "items": [{"t": "statutul social", "c": 0}, {"t": "locul comunicării", "c": 0}, {"t": "opiniile interlocutorilor", "c": 1}, {"t": "intențiile de comunicare", "c": 1}, {"t": "momentul comunicării", "c": 0}], "n": [1]}, {"type": "tf", "q": "Locul în care apare enunțul în secvența comunicativă nu face parte din contextul de comunicare.", "answer": false, "why": "Este a treia componentă a contextului.", "n": [1]}]}, {"id": "u1-l12", "number": 12, "title": "Cuvântul. Sinonimele și antonimele", "section": "Limbă română", "pages": "p. 28-29", "source": "", "theory": [{"term": "Cuvântul: sens și formă", "kind": "definition", "text": "Cuvântul reprezintă unitatea de bază a vocabularului. Cuvântul are:\n• sens sau înțeles, care constituie conținutul;\n• sunete sau înveliș sonor, care constituie forma.", "examples": [], "important": true}, {"term": "Cuvinte cu același sens și forme diferite", "kind": "rule", "text": "Există cuvinte cu același sens, dar diferite prin sunetele din care sunt alcătuite.", "examples": ["bucuros - vesel"], "important": true}, {"term": "Cuvinte cu aceeași formă și sensuri diferite", "kind": "rule", "text": "Există cuvinte cu sens diferit, dar care au aceeași formă.", "examples": ["ban - monedă", "ban - guvernator sau conducător al unui ținut în Evul Mediu"], "important": true}, {"term": "Sensul se stabilește în context", "kind": "rule", "text": "Sensul unui cuvânt se stabilește în context.", "examples": [], "important": true}, {"term": "Contextul", "kind": "definition", "text": "Contextul este o îmbinare de cuvinte, un enunț sau un text în care apare un cuvânt.", "examples": [], "important": true}, {"term": "Sinonimele", "kind": "definition", "text": "Sinonimele sunt cuvinte cu formă diferită și cu sens asemănător sau identic.", "examples": ["glas - voce", "a afla - a descoperi", "geam - fereastră"], "important": true}, {"term": "Antonimele", "kind": "definition", "text": "Antonimele sunt cuvinte cu formă diferită și cu sens diametral opus.", "examples": ["a grăbi - a încetini", "jilav - uscat", "certitudine - nesiguranță"], "important": true}, {"term": "Partea de vorbire a sinonimelor și antonimelor", "kind": "rule", "text": "Sinonimele și antonimele trebuie să fie aceeași parte de vorbire.", "examples": [], "important": true}, {"term": "Sinonime și antonime în context", "kind": "rule", "text": "Alegerea sinonimului sau antonimului unui cuvânt depinde de contextul în care apare cuvântul respectiv.", "examples": [], "important": true}, {"term": "Între ce se stabilesc sinonimia și antonimia", "kind": "rule", "text": "Sinonimia și antonimia se pot stabili între: două cuvinte; o expresie și un cuvânt; două expresii.", "examples": [], "important": true}], "flashcards": [{"front": "Ce reprezintă cuvântul?", "back": "Unitatea de bază a vocabularului.", "n": [0]}, {"front": "Ce constituie conținutul și ce constituie forma unui cuvânt?", "back": "Sensul (înțelesul) este conținutul; sunetele (învelișul sonor) sunt forma.", "n": [0]}, {"front": "Ce sunt sinonimele?", "back": "Cuvinte cu formă diferită și cu sens asemănător sau identic.", "n": [5]}, {"front": "Ce sunt antonimele?", "back": "Cuvinte cu formă diferită și cu sens diametral opus.", "n": [6]}, {"front": "Ce condiție de parte de vorbire trebuie să îndeplinească sinonimele și antonimele?", "back": "Să fie aceeași parte de vorbire.", "n": [7]}, {"front": "Ce este contextul?", "back": "O îmbinare de cuvinte, un enunț sau un text în care apare un cuvânt.", "n": [4]}, {"front": "Între ce se pot stabili sinonimia și antonimia?", "back": "Două cuvinte; o expresie și un cuvânt; două expresii.", "n": [9]}], "quiz": [{"type": "mcq", "q": "Sinonimele sunt cuvinte cu:", "options": ["aceeași formă și sensuri diferite", "formă diferită și sens asemănător sau identic", "formă diferită și sens opus", "aceeași formă și același sens"], "answer": 1, "why": "Definiția sinonimelor.", "n": [5]}, {"type": "mcq", "q": "Care dintre perechile următoare conține antonime?", "options": ["glas - voce", "jilav - uscat", "geam - fereastră", "a afla - a descoperi"], "answer": 1, "why": "Jilav și uscat au sensuri diametral opuse.", "n": [6]}, {"type": "tf", "q": "Sinonimele și antonimele trebuie să fie aceeași parte de vorbire.", "answer": true, "why": "Regulă din Repere.", "n": [7]}, {"type": "fill", "q": "Sensul unui cuvânt se stabilește în ____.", "answers": ["context"], "why": "Sensul se stabilește în context.", "n": [3]}, {"type": "fill", "q": "Forma unui cuvânt este constituită din sunete sau ____ sonor.", "answers": ["înveliș", "invelis", "înveliș sonor"], "why": "Sunetele alcătuiesc învelișul sonor (forma).", "n": [0]}, {"type": "classify", "q": "Încadrează perechile.", "categories": ["Sinonime", "Antonime"], "items": [{"t": "bucuros - vesel", "c": 0}, {"t": "a grăbi - a încetini", "c": 1}, {"t": "glorie - faimă", "c": 0}, {"t": "certitudine - nesiguranță", "c": 1}, {"t": "viclean - șiret", "c": 0}, {"t": "jilav - uscat", "c": 1}], "n": [5, 6]}, {"type": "tf", "q": "Sinonimia se poate stabili doar între două cuvinte, nu și între expresii.", "answer": false, "why": "Se poate stabili și între o expresie și un cuvânt sau între două expresii.", "n": [9]}, {"type": "match", "q": "Potrivește cuvântul cu sinonimul lui din carte.", "pairs": [["glas", "voce"], ["a afla", "a descoperi"], ["a dovedi", "a demonstra"], ["geam", "fereastră"], ["faimă", "glorie"]], "n": [5]}, {"type": "tf", "q": "Există cuvinte cu același sens, dar diferite prin sunetele din care sunt alcătuite.", "answer": true, "why": "Cuvintele cu același sens și forme diferite sunt posibile (de exemplu, sinonimele).", "n": [1]}, {"type": "tf", "q": "Există cuvinte cu sens diferit, dar care au aceeași formă.", "answer": true, "why": "Există cuvinte cu sens diferit și aceeași formă.", "n": [2]}, {"type": "tf", "q": "Alegerea sinonimului sau antonimului unui cuvânt depinde de contextul în care apare cuvântul.", "answer": true, "why": "Sinonimul sau antonimul potrivit se alege în funcție de context.", "n": [8]}]}, {"id": "u1-l13", "number": 13, "title": "Sensurile cuvintelor", "section": "Limbă română", "pages": "p. 30-31", "source": "", "theory": [{"term": "Sensul propriu", "kind": "definition", "text": "Sensul propriu reprezintă sensul comun, obișnuit al unui cuvânt, cunoscut și folosit de toți vorbitorii și legat de un aspect din realitate. Sensul propriu poate fi:\n• sens propriu de bază – sens pe care cuvântul și-l păstrează în orice context;\n• sens propriu secundar – sens pe care cuvântul îl capătă, într-un anumit context, pe baza unei asemănări cu obiectul denumit de cuvântul cu sens de bază.", "examples": ["Și-a scrântit piciorul. (sens propriu de bază)", "Piciorul paharului s-a spart. (sens propriu secundar)"], "important": true}, {"term": "Sensul figurat", "kind": "definition", "text": "Sensul figurat este sensul neobișnuit al unui cuvânt, folosit cu valoare expresivă, pe baza unei asemănări subînțelese.", "examples": ["Părinții sunt picioarele de sprijin ale copiilor."], "important": true}], "flashcards": [{"front": "Ce este sensul propriu?", "back": "Sensul comun, obișnuit al unui cuvânt, cunoscut de toți vorbitorii și legat de realitate.", "n": [0]}, {"front": "Ce este sensul propriu de bază?", "back": "Sensul pe care cuvântul și-l păstrează în orice context.", "n": [0]}, {"front": "Ce este sensul propriu secundar?", "back": "Sensul căpătat într-un context, pe baza unei asemănări cu obiectul denumit de sensul de bază.", "n": [0]}, {"front": "Ce este sensul figurat?", "back": "Sensul neobișnuit, folosit cu valoare expresivă, pe baza unei asemănări subînțelese.", "n": [1]}, {"front": "Dă exemple pentru cele trei sensuri ale cuvântului picior.", "back": "Și-a scrântit piciorul (bază); piciorul paharului (secundar); picioarele de sprijin ale copiilor (figurat).", "n": [0, 1]}], "quiz": [{"type": "classify", "q": "Cuvântul picior: încadrează sensul din fiecare enunț.", "categories": ["Sens propriu de bază", "Sens propriu secundar", "Sens figurat"], "items": [{"t": "Și-a scrântit piciorul.", "c": 0}, {"t": "Piciorul paharului s-a spart.", "c": 1}, {"t": "Părinții sunt picioarele de sprijin ale copiilor.", "c": 2}], "n": [0, 1]}, {"type": "mcq", "q": "Sensul figurat este:", "options": ["sensul comun al cuvântului", "sensul neobișnuit, cu valoare expresivă, bazat pe o asemănare subînțeleasă", "sensul din dicționar, primul dat", "sensul opus"], "answer": 1, "why": "Definiția sensului figurat.", "n": [1]}, {"type": "tf", "q": "Sensul propriu de bază este sensul pe care cuvântul și-l păstrează în orice context.", "answer": true, "why": "Așa este definit.", "n": [0]}, {"type": "fill", "q": "Sensul ____ propriu apare, într-un context, pe baza unei asemănări cu obiectul denumit de sensul de bază.", "answers": ["secundar"], "why": "Sensul propriu secundar.", "n": [0]}, {"type": "mcq", "q": "În enunțul „Piciorul paharului s-a spart”, cuvântul picior are:", "options": ["sens propriu de bază", "sens propriu secundar", "sens figurat", "sens opus"], "answer": 1, "why": "Exemplu dat în carte pentru sensul propriu secundar.", "n": [0]}, {"type": "tf", "q": "Sensul propriu și sensul figurat sunt același lucru.", "answer": false, "why": "Sensul propriu e cel comun; cel figurat e neobișnuit, expresiv.", "n": [0, 1]}]}, {"id": "u1-l14", "number": 14, "title": "Omonimele. Cuvintele polisemantice", "section": "Limbă română", "pages": "p. 32-33", "source": "", "theory": [{"term": "Omonimele", "kind": "definition", "text": "Omonimele sunt cuvinte care au aceeași formă și sensuri complet diferite. De exemplu: bancă1 („instituție financiară”) și bancă2 („scaun lung, cu sau fără spătar”).", "examples": ["bancă1 - instituție financiară", "bancă2 - scaun lung"], "important": true}, {"term": "Clasificarea omonimelor", "kind": "classification", "text": "Omonimele pot fi:\na) lexicale, când sunt aceeași parte de vorbire; acestea sunt:\n• totale, când sunt identice la toate formele pe care le au în vorbire (lac, lacuri);\n• parțiale, când nu sunt identice la toate formele (bandă – benzi, bande);\nb) lexico-gramaticale, când sunt părți de vorbire diferite (sare, substantiv și verb).", "examples": ["lac, lacuri (totale)", "bandă - benzi, bande (parțiale)", "sare (substantiv) și sare (verb) (lexico-gramaticale)"], "important": true}, {"term": "Omofone", "kind": "definition", "text": "Când se pronunță la fel, cuvintele se numesc omofone.", "examples": ["ea și ia"], "important": true}, {"term": "Omografe", "kind": "definition", "text": "Când se scriu la fel, cuvintele se numesc omografe. Pentru a fi omonime, două cuvinte trebuie să se pronunțe la fel, adică să fie omofone. Omografele care se deosebesc prin accent nu sunt omonime.", "examples": ["véselă / vesélă (nu sunt omonime)"], "important": true}, {"term": "Cuvântul polisemantic", "kind": "definition", "text": "Cuvântul polisemantic are două sau mai multe sensuri legate între ele. Sensurile unui cuvânt polisemantic sunt mai mult sau mai puțin apropiate, spre deosebire de omonime, ale căror sensuri nu au nicio legătură între ele.", "examples": ["masă (obiect de mobilier, ospăț, mâncare luată la o oră) - sensuri legate între ele"], "important": true}, {"term": "Etimologia cuvântului polisemantic", "kind": "tip", "text": "Cuvântul polisemantic provine din limba greacă, din poly (însemnând „mai multe”) și semantikos („care are semnificație”), ceea ce indică faptul că este vorba de un cuvânt cu mai multe sensuri.", "examples": [], "important": false}], "flashcards": [{"front": "Ce sunt omonimele?", "back": "Cuvinte cu aceeași formă și sensuri complet diferite.", "n": [0]}, {"front": "Ce sunt omonimele lexicale totale?", "back": "Aceeași parte de vorbire, identice la toate formele (lac, lacuri).", "n": [1]}, {"front": "Ce sunt omonimele lexicale parțiale?", "back": "Aceeași parte de vorbire, dar nu identice la toate formele (bandă - benzi, bande).", "n": [1]}, {"front": "Ce sunt omonimele lexico-gramaticale?", "back": "Cuvinte cu aceeași formă, dar părți de vorbire diferite (sare: substantiv și verb).", "n": [1]}, {"front": "Ce sunt omofonele? Dar omografele?", "back": "Omofone: se pronunță la fel. Omografe: se scriu la fel.", "n": [2, 3]}, {"front": "Prin ce diferă cuvântul polisemantic de omonime?", "back": "Sensurile polisemanticului sunt legate între ele; ale omonimelor nu au nicio legătură.", "n": [4, 0]}, {"front": "De unde provine termenul polisemantic?", "back": "Din greacă: poly („mai multe”) + semantikos („care are semnificație”).", "n": [5]}], "quiz": [{"type": "mcq", "q": "Omonimele sunt cuvinte care au:", "options": ["formă diferită și același sens", "aceeași formă și sensuri complet diferite", "aceeași formă și sensuri legate între ele", "formă diferită și sens opus"], "answer": 1, "why": "Definiția omonimelor.", "n": [0]}, {"type": "mcq", "q": "Perechea sare (substantiv) / sare (verb) este un exemplu de omonime:", "options": ["lexicale totale", "lexicale parțiale", "lexico-gramaticale", "omografe neomonime"], "answer": 2, "why": "Sunt părți de vorbire diferite, deci omonime lexico-gramaticale.", "n": [1]}, {"type": "tf", "q": "Omografele care se deosebesc prin accent (véselă / vesélă) sunt omonime.", "answer": false, "why": "Pentru a fi omonime, cuvintele trebuie să fie omofone; cele care diferă prin accent nu sunt omonime.", "n": [3]}, {"type": "fill", "q": "Cuvintele care se pronunță la fel se numesc ____.", "answers": ["omofone"], "why": "Omofone = se pronunță la fel.", "n": [2]}, {"type": "fill", "q": "Cuvintele care se scriu la fel se numesc ____.", "answers": ["omografe"], "why": "Omografe = se scriu la fel.", "n": [3]}, {"type": "classify", "q": "Încadrează exemplele.", "categories": ["Omonime lexicale totale", "Omonime lexicale parțiale", "Omonime lexico-gramaticale"], "items": [{"t": "lac (de munte) / lac (pentru unghii)", "c": 0}, {"t": "bandă (de hoți) / bandă (fâșie)", "c": 1}, {"t": "sare (substantiv) / sare (verb)", "c": 2}], "n": [1]}, {"type": "tf", "q": "Sensurile unui cuvânt polisemantic sunt legate între ele.", "answer": true, "why": "Spre deosebire de omonime, ale căror sensuri nu au legătură.", "n": [4]}, {"type": "match", "q": "Potrivește termenul cu definiția.", "pairs": [["Omofone", "se pronunță la fel"], ["Omografe", "se scriu la fel"], ["Omonime", "aceeași formă, sensuri complet diferite"], ["Cuvânt polisemantic", "mai multe sensuri legate între ele"]], "n": [2, 3, 0, 4]}]}, {"id": "u1-l15", "number": 15, "title": "Diftongul, triftongul, hiatul", "section": "Limbă română", "pages": "p. 34-35", "source": "", "theory": [{"term": "Diftongul", "kind": "definition", "text": "Diftongul este grupul de sunete alcătuit dintr-o vocală și o semivocală, pronunțate în aceeași silabă.", "examples": ["floa-re", "mâi-ne"], "important": true}, {"term": "Diftongul urcător (ascendent)", "kind": "classification", "text": "Diftongul este urcător sau ascendent când este alcătuit dintr-o semivocală și o vocală, aflate în această succesiune, ca în cuvântul floa-re.", "examples": ["floa-re"], "important": true}, {"term": "Diftongul coborâtor (descendent)", "kind": "classification", "text": "Diftongul este coborâtor sau descendent când este alcătuit dintr-o vocală și o semivocală, aflate în această succesiune, ca în cuvântul mâi-ne.", "examples": ["mâi-ne"], "important": true}, {"term": "Grupurile ce, ci, ge, gi, che, chi, ghe, ghi", "kind": "rule", "text": "Când grupurile de litere ce, ci, ge, gi, che, chi, ghe, ghi se află înaintea unei vocale, nu formează, de obicei, diftongi. De exemplu, în cuvântul ceas există consoana [č], vocala [a] și consoana [s], iar în cuvântul gheață, prima silabă este alcătuită din consoana [g'] și vocala [a].", "examples": ["ceas", "gheață"], "important": true}, {"term": "Verbul a fi și pronumele el, ele", "kind": "rule", "text": "În unele forme ale verbului a fi (este, e, eram etc.) și în pronumele personale el, ele, litera inițială e se pronunță cu diftongul [ĭe].", "examples": ["este", "e", "eram", "el", "ele"], "important": true}, {"term": "Triftongul", "kind": "definition", "text": "Triftongul este grupul de sunete alcătuit dintr-o vocală și două semivocale pronunțate în aceeași silabă.", "examples": ["cre-ioa-ne"], "important": true}, {"term": "Grupurile de litere înaintea unei vocale (triftong)", "kind": "rule", "text": "Grupurile de litere ce, ci, ge, gi, che, chi, ghe, ghi, atunci când se află înaintea unei vocale, nu formează, de obicei, triftongi. De exemplu, în a doua silabă a cuvântului strângeau (-geau) există consoana [ğ], vocala [a] și semivocala [ŭ], ceea ce înseamnă că grupul [aŭ] alcătuiește un diftong.", "examples": ["strân-geau"], "important": true}, {"term": "Pronumele eu și ei", "kind": "rule", "text": "Pronumele personale eu și ei se pronunță cu triftong, [ĭeŭ], respectiv [ĭeĭ].", "examples": ["eu", "ei"], "important": true}, {"term": "Despărțirea în silabe și cratima", "kind": "rule", "text": "Pentru identificarea diftongilor și triftongilor este necesară despărțirea în silabe a cuvintelor sau a grupurilor de cuvinte. Uneori, în aceeași silabă intră cuvinte diferite, legate prin cratimă. Astfel, cuvintele mi-a (mi-a adus) pronunțate împreună formează un diftong, iar cuvintele ne-au (ne-au adus) pronunțate împreună formează un triftong.", "examples": ["mi-a (diftong)", "ne-au (triftong)"], "important": true}, {"term": "Hiatul", "kind": "definition", "text": "Hiatul apare între două vocale alăturate ale aceluiași cuvânt, pronunțate în silabe diferite, ca în cuvântul caisă.", "examples": ["ca-i-să"], "important": true}], "flashcards": [{"front": "Ce este diftongul?", "back": "Grup de sunete alcătuit dintr-o vocală și o semivocală, pronunțate în aceeași silabă.", "n": [0]}, {"front": "Ce este diftongul urcător?", "back": "Semivocală + vocală (floa-re).", "n": [1]}, {"front": "Ce este diftongul coborâtor?", "back": "Vocală + semivocală (mâi-ne).", "n": [2]}, {"front": "Ce este triftongul?", "back": "Grup alcătuit dintr-o vocală și două semivocale în aceeași silabă (cre-ioa-ne).", "n": [5]}, {"front": "Ce este hiatul?", "back": "Două vocale alăturate ale aceluiași cuvânt, pronunțate în silabe diferite (ca-i-să).", "n": [9]}, {"front": "Cum se pronunță pronumele eu și ei?", "back": "Cu triftong: [ĭeŭ], respectiv [ĭeĭ].", "n": [7]}, {"front": "Cum se pronunță litera e inițială în formele verbului a fi și în el, ele?", "back": "Cu diftongul [ĭe].", "n": [4]}, {"front": "Formează ce, ci, ge, gi, che, chi, ghe, ghi înaintea unei vocale diftong?", "back": "De obicei nu (ceas: consoana [č] + vocala [a]).", "n": [3]}], "quiz": [{"type": "mcq", "q": "Diftongul este alcătuit din:", "options": ["o vocală și două semivocale", "două vocale", "o vocală și o semivocală în aceeași silabă", "o consoană și o vocală"], "answer": 2, "why": "Definiția diftongului.", "n": [0]}, {"type": "mcq", "q": "În cuvântul floa-re diftongul este:", "options": ["coborâtor", "urcător", "triftong", "hiat"], "answer": 1, "why": "Semivocală + vocală (oa) = diftong urcător.", "n": [1]}, {"type": "mcq", "q": "În cuvântul mâi-ne diftongul este:", "options": ["urcător", "coborâtor", "hiat", "triftong"], "answer": 1, "why": "Vocală + semivocală (âi) = diftong coborâtor.", "n": [2]}, {"type": "tf", "q": "În cuvântul ca-i-să vocalele a și i sunt în hiat.", "answer": true, "why": "Sunt două vocale alăturate în silabe diferite.", "n": [9]}, {"type": "tf", "q": "Grupul ce din cuvântul ceas formează diftong.", "answer": false, "why": "Grupurile ce, ci, ge, gi etc. nu formează, de obicei, diftongi.", "n": [3]}, {"type": "fill", "q": "Grupul de sunete format dintr-o vocală și două semivocale în aceeași silabă se numește ____.", "answers": ["triftong"], "why": "Definiția triftongului.", "n": [5]}, {"type": "fill", "q": "Pronumele personale eu și ei se pronunță cu ____.", "answers": ["triftong"], "why": "[ĭeŭ] și [ĭeĭ].", "n": [7]}, {"type": "classify", "q": "Încadrează cuvintele după grupul de sunete subliniat.", "categories": ["Diftong", "Triftong", "Hiat"], "items": [{"t": "floa-re", "c": 0}, {"t": "cre-ioa-ne", "c": 1}, {"t": "ca-i-să", "c": 2}, {"t": "mâi-ne", "c": 0}, {"t": "po-et", "c": 2}], "n": [0, 5, 9]}, {"type": "match", "q": "Potrivește cuvântul cu tipul de grup.", "pairs": [["floa-re", "diftong urcător"], ["mâi-ne", "diftong coborâtor"], ["cre-ioa-ne", "triftong"], ["ca-i-să", "hiat"]], "n": [1, 2, 5, 9]}, {"type": "tf", "q": "Grupurile ce, ci, ge, gi, che, chi, ghe, ghi, aflate înaintea unei vocale, nu formează, de obicei, triftongi.", "answer": true, "why": "Conform regulii, aceste grupuri nu formează de obicei nici diftongi, nici triftongi.", "n": [6]}, {"type": "tf", "q": "Cuvintele ne-au (ne-au adus), pronunțate împreună, formează un triftong.", "answer": true, "why": "Cuvintele legate prin cratimă pot intra în aceeași silabă: mi-a formează diftong, ne-au formează triftong.", "n": [8]}]}, {"id": "u1-l16", "number": 16, "title": "Despărțirea în silabe", "section": "Limbă română", "pages": "p. 36-37", "source": "", "theory": [{"term": "O consoană între două vocale", "kind": "rule", "text": "La despărțirea în silabe, o consoană între două vocale trece la silaba următoare.", "examples": ["le-gă-na"], "important": true}, {"term": "Consoană lângă diftong sau triftong", "kind": "rule", "text": "Dacă înaintea unei consoane sau după aceasta se află un diftong sau un triftong, la despărțirea în silabe consoana trece la silaba următoare.", "examples": ["ru-pea"], "important": true}, {"term": "Două consoane între două vocale", "kind": "rule", "text": "La despărțirea în silabe, două consoane între două vocale trec: prima la silaba dinainte și a doua la silaba următoare.", "examples": ["pân-ză"], "important": true}, {"term": "Excepție: grupuri cu l sau r", "kind": "rule", "text": "Există și o excepție: dacă în grupul de două consoane a doua consoană este l sau r și prima este b, c, d, f, g, h, p, t, v, despărțirea în silabe se face înaintea grupului de consoane.", "examples": ["ca-blu", "so-clu", "i-glu", "so-bru", "a-cru", "co-dru", "pa-tru", "co-vrig"], "important": true}, {"term": "Trei sau mai multe consoane între două vocale", "kind": "rule", "text": "La despărțirea în silabe, trei sau mai multe consoane între două vocale trec: prima la silaba dinainte și celelalte la silaba următoare.", "examples": ["in-stru-ment", "pen-tru"], "important": true}, {"term": "Excepție: lpt, mpt, mpț, ncs, ncș, nct, ncț, ndv, rct, rtf, stm", "kind": "rule", "text": "Există și o excepție: în cazul grupurilor de consoane lpt, mpt, mpț, ncs, ncș, nct, ncț, ndv, rct, rtf, stm, despărțirea se face după a doua consoană din grup.", "examples": ["sculp-tor", "somp-tu-os", "linc-șii", "punc-te", "func-ți-e", "arc-tic", "jert-fă", "ast-ma-tic", "send-viș"], "important": true}, {"term": "Două vocale alăturate", "kind": "rule", "text": "La despărțirea în silabe, două vocale alăturate trec: prima în silaba dinainte și a doua în silaba următoare. Regula este valabilă și dacă, în locul vocalelor, se află un diftong sau un triftong (ba-ie, ma-iou).", "examples": ["a-le-e", "re-ac-ți-e", "ba-ie", "ma-iou", "a-vi-on"], "important": true}, {"term": "Liniuța de despărțire și cratima", "kind": "rule", "text": "Liniuța de despărțire în silabe se scrie o singură dată, la sfârșitul rândului. Cratima nu trebuie confundată cu liniuța de despărțire în silabe.", "examples": [], "important": true}], "flashcards": [{"front": "O consoană între două vocale: unde trece la despărțirea în silabe?", "back": "La silaba următoare (le-gă-na).", "n": [0]}, {"front": "Două consoane între două vocale: cum se despart?", "back": "Prima la silaba dinainte, a doua la cea următoare (pân-ză).", "n": [2]}, {"front": "Care este excepția pentru două consoane?", "back": "Dacă a doua este l sau r și prima este b, c, d, f, g, h, p, t, v, grupul trece întreg la silaba următoare (ca-blu, so-bru).", "n": [3]}, {"front": "Trei sau mai multe consoane între vocale: cum se despart?", "back": "Prima rămâne în silaba dinainte, celelalte trec în silaba următoare (in-stru-ment).", "n": [4]}, {"front": "Care sunt grupurile de consoane care se despart după a doua consoană?", "back": "lpt, mpt, mpț, ncs, ncș, nct, ncț, ndv, rct, rtf, stm.", "n": [5]}, {"front": "Două vocale alăturate: cum se despart?", "back": "Prima în silaba dinainte, a doua în silaba următoare (a-le-e, ba-ie).", "n": [6]}, {"front": "De câte ori se scrie liniuța de despărțire în silabe la capăt de rând?", "back": "O singură dată, la sfârșitul rândului.", "n": [7]}], "quiz": [{"type": "mcq", "q": "Cum se desparte corect în silabe cuvântul legăna?", "options": ["leg-ă-na", "le-gă-na", "l-e-gă-na", "legă-na"], "answer": 1, "why": "O consoană între două vocale trece la silaba următoare.", "n": [0]}, {"type": "mcq", "q": "Cum se desparte cuvântul pânză?", "options": ["pâ-nză", "pân-ză", "pânz-ă", "p-ân-ză"], "answer": 1, "why": "Două consoane între vocale: prima la silaba dinainte, a doua la următoare.", "n": [2]}, {"type": "mcq", "q": "Care este despărțirea corectă a cuvântului cablu?", "options": ["cab-lu", "ca-blu", "c-ab-lu", "cabl-u"], "answer": 1, "why": "Excepție: b + l, grupul trece la silaba următoare.", "n": [3]}, {"type": "mcq", "q": "Care este despărțirea corectă a cuvântului instrument?", "options": ["i-nstru-ment", "ins-tru-ment", "in-stru-ment", "instr-u-ment"], "answer": 2, "why": "Trei consoane: prima rămâne în urmă, celelalte trec la silaba următoare.", "n": [4]}, {"type": "tf", "q": "Cuvântul punc-te se desparte după a doua consoană din grupul nct.", "answer": true, "why": "Pentru grupul nct despărțirea se face după a doua consoană (punc-te).", "n": [5]}, {"type": "fill", "q": "Două vocale alăturate se despart astfel: prima în silaba ____, a doua în silaba următoare.", "answers": ["dinainte", "anterioară", "precedentă"], "why": "Prima vocală rămâne în silaba dinainte.", "n": [6]}, {"type": "fill", "q": "Desparte în silabe cuvântul avion (scrie cu liniuțe):", "answers": ["a-vi-on"], "why": "Vocalele i și o se află în silabe diferite (hiat).", "n": [6]}, {"type": "tf", "q": "Cratima și liniuța de despărțire în silabe sunt același semn cu aceeași funcție.", "answer": false, "why": "Cratima nu trebuie confundată cu liniuța de despărțire în silabe.", "n": [7]}, {"type": "classify", "q": "Încadrează cuvântul după regula de despărțire aplicată.", "categories": ["Excepție (grup + l sau r)", "Două consoane obișnuite (prima în urmă)"], "items": [{"t": "so-bru", "c": 0}, {"t": "pân-ză", "c": 1}, {"t": "co-dru", "c": 0}, {"t": "cur-te", "c": 1}, {"t": "bar-bă", "c": 1}, {"t": "a-cru", "c": 0}], "n": [3, 2]}, {"type": "match", "q": "Potrivește cuvântul cu despărțirea lui corectă.", "pairs": [["alee", "a-le-e"], ["reacție", "re-ac-ți-e"], ["ploaie", "ploa-ie"], ["astmatic", "ast-ma-tic"], ["sendviș", "send-viș"]], "n": [6, 5, 1]}]}, {"id": "u1-l17", "number": 17, "title": "Redactarea unei narațiuni la persoana I. Stilul", "section": "Redactare", "pages": "p. 38-39", "source": "Jurnalul Annei Frank (fragment)", "theory": [{"term": "Stilul în narațiunea la persoana I", "kind": "definition", "text": "Într-o narațiune la persoana I, la fel ca în orice alt text redactat, cel care scrie își exprimă personalitatea prin stilul folosit, prin modul în care selectează și combină cuvintele în propoziții și fraze.", "examples": [], "important": true}, {"term": "Proprietatea termenilor", "kind": "definition", "text": "Proprietatea termenilor – folosirea corectă a cuvintelor, bazată pe cunoașterea formei și a sensului acestora.", "examples": [], "important": true}, {"term": "Puritatea", "kind": "definition", "text": "Puritatea – evitarea exprimărilor neliterare, a cuvintelor vulgare, a unor cuvinte prea vechi sau prea noi ori folosite doar în anumite regiuni.", "examples": [], "important": true}, {"term": "Originalitatea", "kind": "definition", "text": "Originalitatea – felul în care autorul unui text își pune în valoare personalitatea; un stil original se remarcă prin creativitate (noutatea ideilor și a modului în care este folosit limbajul, evitarea ideilor comune și a exprimărilor devenite clișee prin folosire pe scară largă), forță de evocare (capacitatea de a transmite emoții și de a impresiona cititorul) și personalizare (autorul valorifică experiențele personale, iar vocea sa este distinctă de alte voci).", "examples": [], "important": true}, {"term": "Adecvarea situațională", "kind": "definition", "text": "Adecvarea situațională constă în capacitatea celui care scrie de a-și adapta stilul la tema abordată, la cititori, la scopul comunicării și la tipul de text.", "examples": [], "important": true}], "flashcards": [{"front": "Prin ce își exprimă personalitatea cel care scrie?", "back": "Prin stil: modul în care selectează și combină cuvintele în propoziții și fraze.", "n": [0]}, {"front": "Ce este proprietatea termenilor?", "back": "Folosirea corectă a cuvintelor, pe baza cunoașterii formei și sensului lor.", "n": [1]}, {"front": "Ce este puritatea stilului?", "back": "Evitarea exprimărilor neliterare, a cuvintelor vulgare, prea vechi, prea noi sau regionale.", "n": [2]}, {"front": "Ce este originalitatea?", "back": "Felul în care autorul își pune în valoare personalitatea: creativitate, forță de evocare, personalizare.", "n": [3]}, {"front": "Care sunt cele trei componente ale stilului original?", "back": "Creativitatea, forța de evocare și personalizarea.", "n": [3]}, {"front": "Ce este adecvarea situațională?", "back": "Adaptarea stilului la temă, cititori, scopul comunicării și tipul de text.", "n": [4]}], "quiz": [{"type": "mcq", "q": "Evitarea cuvintelor vulgare și a celor folosite doar în anumite regiuni ține de:", "options": ["originalitate", "puritate", "adecvare situațională", "proprietatea termenilor"], "answer": 1, "why": "Puritatea = evitarea exprimărilor neliterare, vulgare, prea vechi/noi, regionale.", "n": [2]}, {"type": "mcq", "q": "Folosirea corectă a cuvintelor, pe baza cunoașterii formei și sensului lor, este:", "options": ["puritatea", "originalitatea", "proprietatea termenilor", "personalizarea"], "answer": 2, "why": "Definiția proprietății termenilor.", "n": [1]}, {"type": "fill", "q": "Un stil original se remarcă prin creativitate, forță de evocare și ____.", "answers": ["personalizare"], "why": "Cele trei componente ale originalității.", "n": [3]}, {"type": "tf", "q": "Adecvarea situațională înseamnă adaptarea stilului la temă, cititori, scop și tipul de text.", "answer": true, "why": "Definiția din Repere.", "n": [4]}, {"type": "tf", "q": "Evitarea exprimărilor devenite clișee prin folosire pe scară largă ține de creativitate.", "answer": true, "why": "Creativitatea include evitarea ideilor comune și a clișeelor.", "n": [3]}, {"type": "match", "q": "Potrivește trăsătura stilului cu explicația ei.", "pairs": [["Proprietatea termenilor", "folosirea corectă a cuvintelor"], ["Puritatea", "evitarea exprimărilor neliterare și vulgare"], ["Originalitatea", "autorul își pune în valoare personalitatea"], ["Forța de evocare", "capacitatea de a transmite emoții și a impresiona"], ["Adecvarea situațională", "adaptarea stilului la temă și cititori"]], "n": [1, 2, 3, 4]}]}]}, {"unit": {"id": "u2", "number": 2, "title": "Printre colegi și prieteni", "summary": "Unitatea urmărește relațiile dintre copii (colegi, prieteni, grupuri) prin textul narativ literar, apoi studiază timpul și spațiul, momentele subiectului, personajele, rezumatul, verbul și modurile lui, predicatul nominal, subiectul, complementul, circumstanțialul și prepoziția."}, "lessons": [{"id": "u2-l1", "number": 1, "title": "Textul narativ literar în proză", "section": "Lectură", "pages": "p. 44-46", "source": "Oracolul - Mircea Cărtărescu", "theory": [], "flashcards": [], "quiz": []}, {"id": "u2-l2", "number": 2, "title": "Timpul și spațiul", "section": "Lectură", "pages": "p. 47-48", "source": "Oracolul - Mircea Cărtărescu", "theory": [{"term": "Timpul desfășurării întâmplărilor", "kind": "definition", "text": "Textul narativ poate prezenta întâmplări situate în trecut, în prezent sau în viitor față de momentul narării. Timpul desfășurării întâmplărilor este cel în care se petrece acțiunea. El nu coincide întotdeauna cu timpul povestirii întâmplărilor. În funcție de situarea întâmplărilor față de timpul în care sunt relatate, timpul desfășurării acestora este marcat prin utilizarea verbelor la trecut, la prezent sau la viitor.", "examples": ["a doua zi", "într-o zi", "seara târziu", "sfârșitul trimestrului"], "important": true}, {"term": "Timpul povestirii întâmplărilor", "kind": "definition", "text": "Timpul povestirii întâmplărilor este cel care surprinde momentul în care naratorul relatează întâmplările. Timpul povestirii este marcat prin utilizarea verbelor la prezent.", "examples": ["azi"], "important": true}, {"term": "Episoade sărite sau comprimate", "kind": "rule", "text": "În relatarea întâmplărilor, unele episoade pot fi sărite sau pot fi comprimate, prin rezumare.", "examples": [], "important": true}, {"term": "Spațiul acțiunii", "kind": "rule", "text": "Acțiunea se poate petrece într-un singur loc sau în mai multe locuri.", "examples": [], "important": true}], "flashcards": [{"front": "Ce este timpul desfășurării întâmplărilor?", "back": "Timpul în care se petrece acțiunea; este marcat prin verbe la trecut, prezent sau viitor.", "n": [0]}, {"front": "Ce este timpul povestirii întâmplărilor?", "back": "Momentul în care naratorul relatează întâmplările; este marcat prin verbe la prezent.", "n": [1]}, {"front": "Coincid întotdeauna timpul desfășurării și timpul povestirii?", "back": "Nu, nu coincid întotdeauna.", "n": [0, 1]}, {"front": "Ce se poate întâmpla cu unele episoade în relatare?", "back": "Pot fi sărite sau comprimate, prin rezumare.", "n": [2]}, {"front": "În câte locuri se poate petrece acțiunea?", "back": "Într-un singur loc sau în mai multe locuri.", "n": [3]}], "quiz": [{"type": "mcq", "q": "Timpul povestirii întâmplărilor este marcat prin verbe la:", "options": ["trecut", "viitor", "prezent", "orice timp"], "answer": 2, "why": "Timpul povestirii este marcat prin utilizarea verbelor la prezent.", "n": [1]}, {"type": "tf", "q": "Timpul desfășurării întâmplărilor coincide întotdeauna cu timpul povestirii lor.", "answer": false, "why": "Cele două nu coincid întotdeauna.", "n": [0, 1]}, {"type": "fill", "q": "Momentul în care naratorul relatează întâmplările se numește timpul ____ întâmplărilor.", "answers": ["povestirii"], "why": "Timpul povestirii surprinde momentul relatării.", "n": [1]}, {"type": "mcq", "q": "Care dintre afirmații este adevărată despre episoadele unei narațiuni?", "options": ["Toate sunt povestite pe larg", "Unele pot fi sărite sau comprimate prin rezumare", "Nu pot fi comprimate niciodată", "Sunt mereu povestite la viitor"], "answer": 1, "why": "Unele episoade pot fi sărite sau comprimate, prin rezumare.", "n": [2]}, {"type": "match", "q": "Potrivește noțiunea cu descrierea ei.", "pairs": [["Timpul desfășurării întâmplărilor", "timpul în care se petrece acțiunea"], ["Timpul povestirii întâmplărilor", "momentul în care naratorul relatează"], ["Marca timpului povestirii", "verbe la prezent"], ["Spațiul acțiunii", "un singur loc sau mai multe locuri"]], "n": [0, 1]}, {"type": "tf", "q": "Timpul desfășurării întâmplărilor poate fi marcat prin verbe la trecut, la prezent sau la viitor.", "answer": true, "why": "Depinde de situarea întâmplărilor față de timpul relatării.", "n": [0]}]}, {"id": "u2-l3", "number": 3, "title": "Etapele acțiunii (momentele subiectului literar)", "section": "Lectură", "pages": "p. 49-51", "source": "Oracolul - Mircea Cărtărescu", "theory": [{"term": "Momentele subiectului literar", "kind": "definition", "text": "Într-o narațiune, cele trei părți ale acesteia (situația inițială, succesiunea de întâmplări și situația finală) pot fi delimitate în cinci momente ale subiectului literar, adică totalitatea întâmplărilor dintr-un text narativ.", "examples": ["expozițiunea, intriga, desfășurarea acțiunii, punctul culminant, deznodământul"], "important": false}, {"term": "Expozițiunea", "kind": "definition", "text": "Expozițiunea corespunde situației inițiale și surprinde o stare de echilibru, de dinaintea declanșării acțiunii. De obicei, în expozițiune sunt prezentate personajele, timpul și spațiul acțiunii. Verbele folosite, de obicei, în acest moment sunt la modul indicativ, timpul imperfect sau timpul prezent.", "examples": [], "important": true}, {"term": "Intriga", "kind": "definition", "text": "Intriga este întâmplarea sau motivul interior (o dorință, o problemă capitală etc.) care provoacă succesiunea de evenimente. Intriga modifică situația inițială și rupe echilibrul acesteia. De obicei, verbele folosite în intrigă sunt la modul indicativ, timpurile perfect compus sau prezent. În operele literare mai vechi, apare și perfectul simplu.", "examples": [], "important": true}, {"term": "Desfășurarea acțiunii", "kind": "definition", "text": "Desfășurarea acțiunii este cea mai întinsă parte a unei narațiuni și surprinde succesiunea de întâmplări provocate de intrigă. Timpurile verbale utilizate în desfășurarea acțiunii sunt perfectul compus și prezentul modului indicativ. În textele vechi, poate să apară și perfectul simplu. Pentru evenimente petrecute anterior momentului relatării, uneori se utilizează și mai-mult-ca-perfectul.", "examples": [], "important": true}, {"term": "Punctul culminant", "kind": "definition", "text": "Punctul culminant este momentul cel mai tensionat al acțiunii, care pune capăt întâmplărilor provocate de intrigă.", "examples": [], "important": true}, {"term": "Deznodământul și epilogul", "kind": "definition", "text": "Deznodământul surprinde încheierea acțiunii. El poate face legătura cu situația inițială și stabilește o nouă stare de echilibru. De obicei, verbele utilizate în deznodământ sunt la modul indicativ, timpul perfect compus sau timpul prezent, dar poate fi utilizat și imperfectul.\nUneori, finalul textului surprinde momente ulterioare încheierii acțiunii. Această parte se numește epilog.", "examples": [], "important": true}, {"term": "Delimitarea momentelor", "kind": "rule", "text": "Momentele subiectului nu sunt întotdeauna foarte clar delimitate. În unele texte, acestea își schimbă ordinea. Alteori, unele momente ale subiectului lipsesc.", "examples": [], "important": true}], "flashcards": [{"front": "Care sunt cele cinci momente ale subiectului?", "back": "Expozițiunea, intriga, desfășurarea acțiunii, punctul culminant, deznodământul.", "n": [0, 1, 2, 3, 4, 5]}, {"front": "Ce este expozițiunea?", "back": "Situația inițială: o stare de echilibru, în care sunt prezentate personajele, timpul și spațiul.", "n": [1]}, {"front": "Ce este intriga?", "back": "Întâmplarea sau motivul interior care provoacă succesiunea de evenimente și rupe echilibrul inițial.", "n": [2]}, {"front": "Care este cea mai întinsă parte a narațiunii?", "back": "Desfășurarea acțiunii.", "n": [3]}, {"front": "Ce este punctul culminant?", "back": "Momentul cel mai tensionat, care pune capăt întâmplărilor provocate de intrigă.", "n": [4]}, {"front": "Ce este epilogul?", "back": "Partea finală care surprinde momente ulterioare încheierii acțiunii.", "n": [5]}, {"front": "Ce este subiectul literar?", "back": "Totalitatea întâmplărilor dintr-un text narativ.", "n": [0]}], "quiz": [{"type": "mcq", "q": "Care moment al subiectului surprinde o stare de echilibru, de dinaintea declanșării acțiunii?", "options": ["intriga", "expozițiunea", "punctul culminant", "deznodământul"], "answer": 1, "why": "Expozițiunea corespunde situației inițiale.", "n": [1]}, {"type": "mcq", "q": "Momentul care rupe echilibrul situației inițiale este:", "options": ["deznodământul", "epilogul", "intriga", "expozițiunea"], "answer": 2, "why": "Intriga modifică situația inițială și rupe echilibrul acesteia.", "n": [2]}, {"type": "tf", "q": "Desfășurarea acțiunii este cea mai întinsă parte a unei narațiuni.", "answer": true, "why": "Așa o definește cartea.", "n": [3]}, {"type": "fill", "q": "Momentul cel mai tensionat al acțiunii se numește punctul ____.", "answers": ["culminant"], "why": "Punctul culminant pune capăt întâmplărilor provocate de intrigă.", "n": [4]}, {"type": "tf", "q": "Momentele subiectului sunt întotdeauna foarte clar delimitate și nu lipsesc niciodată.", "answer": false, "why": "Uneori își schimbă ordinea sau lipsesc.", "n": [6]}, {"type": "match", "q": "Potrivește momentul subiectului cu caracterizarea lui.", "pairs": [["Expozițiunea", "situația inițială, stare de echilibru"], ["Intriga", "ruperea echilibrului"], ["Desfășurarea acțiunii", "cea mai întinsă parte"], ["Punctul culminant", "momentul cel mai tensionat"], ["Deznodământul", "încheierea acțiunii"]], "n": [1, 2, 3, 4, 5]}, {"type": "classify", "q": "Încadrează timpul verbal în momentul subiectului în care apare de obicei: expozițiune (imperfect) sau intrigă (perfect compus).", "categories": ["Expozițiune", "Intrigă"], "items": [{"t": "imperfect", "c": 0}, {"t": "perfect compus", "c": 1}, {"t": "perfect simplu (în operele literare mai vechi)", "c": 1}], "n": [1, 2]}, {"type": "fill", "q": "Partea finală care surprinde momente ulterioare încheierii acțiunii se numește ____.", "answers": ["epilog"], "why": "Epilogul urmează după deznodământ.", "n": [5]}]}, {"id": "u2-l4", "number": 4, "title": "Personajele", "section": "Lectură", "pages": "p. 52-53", "source": "Oracolul - Mircea Cărtărescu", "theory": [{"term": "Personaje principale, secundare și episodice", "kind": "classification", "text": "În textul narativ, în funcție de rolul pe care îl ocupă în acțiune, un personaj poate fi principal, secundar sau episodic.", "examples": [], "important": true}, {"term": "Personaje colective", "kind": "definition", "text": "Uneori, câte un grup de personaje se comportă unitar, fără ca din acesta să se distingă personaje individuale. Aceste grupuri au rol de personaje colective.", "examples": ["grupul de copii din clasă"], "important": true}, {"term": "Trăsăturile personajelor", "kind": "rule", "text": "Trăsăturile personajelor pot fi numite în text (de către narator sau personaje) sau pot fi deduse din faptele lor, din felul în care vorbesc, se îmbracă etc.", "examples": [], "important": true}], "flashcards": [{"front": "După ce criteriu se clasifică personajele în principale, secundare, episodice?", "back": "După rolul pe care îl ocupă în acțiune.", "n": [0]}, {"front": "Ce este un personaj colectiv?", "back": "Un grup de personaje care se comportă unitar, fără personaje individuale distincte.", "n": [1]}, {"front": "Cum pot fi aflate trăsăturile unui personaj?", "back": "Sunt numite în text de narator sau de personaje, ori deduse din fapte, vorbe, vestimentație.", "n": [2]}, {"front": "Cine poate numi trăsăturile unui personaj în text?", "back": "Naratorul sau alte personaje.", "n": [2]}], "quiz": [{"type": "mcq", "q": "Personajele unui text narativ pot fi, după rolul în acțiune:", "options": ["pozitive, negative, neutre", "principale, secundare, episodice", "reale și imaginare", "individuale și colective"], "answer": 1, "why": "Clasificarea după rolul din acțiune este principal, secundar, episodic.", "n": [0]}, {"type": "tf", "q": "Un grup de personaje care se comportă unitar are rol de personaj colectiv.", "answer": true, "why": "Așa este definit personajul colectiv.", "n": [1]}, {"type": "fill", "q": "Un grup de personaje care se comportă unitar este un personaj ____.", "answers": ["colectiv"], "why": "Grupul nu are personaje individuale distincte.", "n": [1]}, {"type": "mcq", "q": "Trăsăturile unui personaj pot fi deduse din:", "options": ["doar din titlu", "faptele, vorbele, felul în care se îmbracă", "doar din numele personajului", "doar din ilustrații"], "answer": 1, "why": "Se deduc din fapte, vorbire, vestimentație etc.", "n": [2]}, {"type": "tf", "q": "Trăsăturile personajelor pot fi doar numite direct de narator, nu și deduse.", "answer": false, "why": "Pot fi și numite, și deduse.", "n": [2]}, {"type": "match", "q": "Potrivește noțiunea cu explicația din manual.", "pairs": [["Personaj colectiv", "grup de personaje care se comportă unitar"], ["Trăsături numite", "de către narator sau de personaje"], ["Trăsături deduse", "din fapte, vorbire, vestimentație"]], "n": [1, 2]}]}, {"id": "u2-l5", "number": 5, "title": "Semnificațiile textului", "section": "Lectură", "pages": "p. 54-55", "source": "Oracolul - Mircea Cărtărescu", "theory": [], "flashcards": [], "quiz": []}, {"id": "u2-l6", "number": 6, "title": "Noi pagini – alte idei", "section": "Lectură", "pages": "p. 56-57", "source": "Micuțul Nicolas (fragment) - Jean-Jacques Sempé, René Goscinny", "theory": [], "flashcards": [], "quiz": []}, {"id": "u2-l7", "number": 7, "title": "Valori ale culturii populare în spațiul românesc. Etnii și jocuri de copii", "section": "Interculturalitate", "pages": "p. 58-59", "source": "", "theory": [{"term": "Interferențe culturale", "kind": "definition", "text": "Interferențele culturale îmbogățesc cultura populară a popoarelor, fapt reflectat și în spațiul cultural românesc.", "examples": [], "important": true}, {"term": "Comunitatea etnică", "kind": "definition", "text": "Comunitatea etnică reprezintă un grup de persoane care trăiesc într-o țară sau într-o localitate, au aceeași etnie, împărtășesc o limbă comună, tradiții, obiceiuri și credințe religioase.", "examples": [], "important": true}, {"term": "Contacte între comunități și jocul", "kind": "rule", "text": "Între comunitățile etnice există contacte și influențe culturale, iar jocul reprezintă una dintre activitățile prin care copiii din comunitățile aflate în același spațiu intră în contact.", "examples": [], "important": true}, {"term": "Jocul – limbaj universal", "kind": "rule", "text": "Multe dintre jocurile copilăriei se regăsesc în toate comunitățile etnice de pe teritoriul României, jocul presupunând un limbaj universal.", "examples": ["Țuiul (comunitate de români)", "Bújj, bújj, zöld ág... (comunitate maghiară)", "O podo baruno (comunitate de romi)"], "important": true}], "flashcards": [{"front": "Ce este comunitatea etnică?", "back": "Grup de persoane dintr-o țară sau localitate, cu aceeași etnie, limbă comună, tradiții, obiceiuri și credințe religioase.", "n": [1]}, {"front": "Ce îmbogățesc interferențele culturale?", "back": "Cultura populară a popoarelor.", "n": [0]}, {"front": "Prin ce activitate intră în contact copiii din comunități diferite?", "back": "Prin joc.", "n": [2]}, {"front": "De ce se regăsesc jocurile în toate comunitățile?", "back": "Pentru că jocul presupune un limbaj universal.", "n": [3]}, {"front": "Ce comunitate etnică a cules jocul Țuiul?", "back": "Comunitatea de români.", "n": [2, 3]}, {"front": "Ce comunitate etnică a cules jocul O podo baruno?", "back": "Comunitatea de romi.", "n": [2, 3]}], "quiz": [{"type": "mcq", "q": "Care dintre următoarele NU face parte din definiția comunității etnice?", "options": ["aceeași etnie", "limbă comună", "tradiții și obiceiuri", "aceeași profesie"], "answer": 3, "why": "Definiția include etnie, limbă, tradiții, obiceiuri, credințe religioase.", "n": [1]}, {"type": "tf", "q": "Jocul este una dintre activitățile prin care copiii din comunități diferite intră în contact.", "answer": true, "why": "Așa spune Repere.", "n": [2]}, {"type": "fill", "q": "Jocul presupune un limbaj ____.", "answers": ["universal"], "why": "De aceea jocurile se regăsesc în toate comunitățile.", "n": [3]}, {"type": "match", "q": "Potrivește jocul cu comunitatea din care a fost cules.", "pairs": [["Țuiul", "comunitate de români"], ["Bújj, bújj, zöld ág...", "comunitate maghiară"], ["O podo baruno", "comunitate de romi"]], "n": [2, 3]}, {"type": "fill", "q": "Interferențele ____ îmbogățesc cultura populară a popoarelor.", "answers": ["culturale"], "why": "Interferențele culturale îmbogățesc cultura populară.", "n": [0]}, {"type": "tf", "q": "Jocurile copilăriei se regăsesc doar într-o singură comunitate etnică din România.", "answer": false, "why": "Multe se regăsesc în toate comunitățile etnice.", "n": [3]}]}, {"id": "u2-proiect", "number": 16, "title": "Proiect de grup: Prietenia în filme", "section": "Proiect", "pages": "p. 60-61", "source": "Mindenki (Cântecul) - Kristóf Deák, Anna Udvardy", "theory": [{"term": "Arborele lui Sapiro", "kind": "definition", "text": "Tehnica arborele lui Sapiro are șapte părți, în ordinea numerelor:\n1. rădăcinile – cauzele problemei/conflictului (De ce se naște conflictul?);\n2. solul – mediul în care apare problema: familie, școală etc. (Când? Unde?);\n3. tulpina – părțile implicate în conflict (Cine sunt cei implicați în conflict?);\n4. scorbura – problema clară a conflictului (În ce constă conflictul?);\n5. ramurile – efectele problemei asupra celor implicați (Ce simt cei implicați?);\n6. frunzele – acțiunile concrete ale celor implicați (Ce fac cei implicați?);\n7. fructele – soluțiile pentru problemă (Cum este soluționat conflictul?).", "examples": [], "important": false}, {"term": "Scurtmetrajul", "kind": "definition", "text": "Spre deosebire de lungmetraj, scurtmetrajul este un film care nu depășește un anumit număr de minute, maximum 40. În ceea ce privește regulile respectate în România, se consideră că un scurtmetraj are până în 20 de minute. Fiind un gen distinct, există categorii speciale pentru acesta în cadrul festivalurilor de film, precum și festivaluri dedicate special scurtmetrajelor.", "examples": [], "important": false}], "flashcards": [{"front": "Ce arată rădăcinile în arborele lui Sapiro?", "back": "Cauzele problemei/conflictului (De ce se naște conflictul?).", "n": [0]}, {"front": "Ce arată scorbura în arborele lui Sapiro?", "back": "Problema clară a conflictului (În ce constă conflictul?).", "n": [0]}, {"front": "Ce arată fructele în arborele lui Sapiro?", "back": "Soluțiile pentru problemă.", "n": [0]}, {"front": "Ce arată frunzele în arborele lui Sapiro?", "back": "Acțiunile concrete ale celor implicați.", "n": [0]}, {"front": "Cât durează maximum un scurtmetraj, în general?", "back": "Maximum 40 de minute (în România, până în 20 de minute).", "n": [1]}], "quiz": [{"type": "match", "q": "Potrivește partea arborelui lui Sapiro cu ce reprezintă.", "pairs": [["rădăcinile", "cauzele conflictului"], ["solul", "mediul în care apare conflictul"], ["tulpina", "părțile implicate în conflict"], ["ramurile", "efectele asupra celor implicați"], ["fructele", "soluțiile problemei"]], "n": [0]}, {"type": "mcq", "q": "La ce întrebare răspund frunzele din arborele lui Sapiro?", "options": ["Cine sunt cei implicați?", "Ce fac cei implicați?", "Cum este soluționat conflictul?", "De ce se naște conflictul?"], "answer": 1, "why": "Frunzele reprezintă acțiunile concrete ale celor implicați.", "n": [0]}, {"type": "tf", "q": "Conform regulilor respectate în România, un scurtmetraj are până în 20 de minute.", "answer": true, "why": "Așa precizează textul.", "n": [1]}, {"type": "fill", "q": "Scurtmetrajul nu depășește, în general, maximum ____ de minute.", "answers": ["40", "patruzeci"], "why": "Maximum 40 de minute.", "n": [1]}, {"type": "mcq", "q": "Partea arborelui care arată mediul (familie, școală) este:", "options": ["tulpina", "solul", "scorbura", "ramurile"], "answer": 1, "why": "Solul = mediul în care apare problema; întrebările Când? Unde?", "n": [0]}]}, {"id": "u2-l8", "number": 8, "title": "Rezumatul oral", "section": "Comunicare orală", "pages": "p. 62-63", "source": "", "theory": [{"term": "Rezumatul", "kind": "definition", "text": "Rezumatul este relatarea unei înșiruiri de întâmplări într-o formă concisă, eliminând detaliile nesemnificative. Rezumatul poate fi oral sau scris și se poate referi la întâmplări reale sau imaginare, scrise, trăite, auzite, văzute etc.", "examples": [], "important": true}, {"term": "Regulile rezumatului oral", "kind": "rule", "text": "Regulile de alcătuire a unui rezumat oral:\n- se pornește de la ideile principale, care se dezvoltă prin adăugarea unor informații semnificative;\n- succesiunea ideilor trebuie să respecte ordinea desfășurării întâmplărilor;\n- timpurile verbale ale indicativului care pot fi utilizate sunt prezentul sau perfectul compus;\n- nu se fac comentarii personale, nu se utilizează descrieri și dialog, nu se dau citate; când se rezumă un text, nu se preiau formulări sau propoziții din acesta, ci se reformulează cu propriile cuvinte;\n- pentru asigurarea legăturii ideilor între ele, se utilizează cuvinte sau grupuri de cuvinte ce redau cursivitatea: mai întâi, apoi, după aceea, mai târziu, în același timp, în cele din urmă etc.", "examples": ["mai întâi", "apoi", "după aceea", "mai târziu", "în același timp", "în cele din urmă"], "important": true}, {"term": "Ce este și ce nu este rezumatul (exercițiu)", "kind": "tip", "text": "Rezumatul este un text în care ideile sunt reformulate cu propriile cuvinte, un text care surprinde ideile principale într-o exprimare ce demonstrează înțelegerea lor, un text ce nu reține detaliile nesemnificative.\nRezumatul nu este un text în care ideile sunt reproduse, un text în care sunt redate pe larg explicații, un text la fel de lung sau chiar mai lung decât ceea ce rezumă.", "examples": [], "important": false, "derived": true}], "flashcards": [{"front": "Ce este rezumatul?", "back": "Relatarea unei înșiruiri de întâmplări într-o formă concisă, fără detalii nesemnificative.", "n": [0]}, {"front": "De la ce se pornește un rezumat oral?", "back": "De la ideile principale, dezvoltate cu informații semnificative.", "n": [1]}, {"front": "Ce timpuri ale indicativului se folosesc în rezumat?", "back": "Prezentul sau perfectul compus.", "n": [1]}, {"front": "Ce NU se face într-un rezumat?", "back": "Comentarii personale, descrieri, dialog, citate.", "n": [1]}, {"front": "Dă exemple de cuvinte de legătură într-un rezumat.", "back": "Mai întâi, apoi, după aceea, mai târziu, în același timp, în cele din urmă.", "n": [1]}, {"front": "Cum se reformulează ideile în rezumat?", "back": "Cu propriile cuvinte, nu prin preluarea formulărilor din text.", "n": [1, 2]}], "quiz": [{"type": "mcq", "q": "Care dintre următoarele timpuri verbale se pot folosi în rezumat?", "options": ["imperfectul și perfectul simplu", "prezentul sau perfectul compus", "viitorul și mai-mult-ca-perfectul", "orice timp"], "answer": 1, "why": "Regula: prezentul sau perfectul compus.", "n": [1]}, {"type": "tf", "q": "Într-un rezumat se pot da citate din text.", "answer": false, "why": "Nu se dau citate și nu se preiau formulări din text.", "n": [1]}, {"type": "tf", "q": "Succesiunea ideilor în rezumat trebuie să respecte ordinea desfășurării întâmplărilor.", "answer": true, "why": "Este una dintre reguli.", "n": [1]}, {"type": "fill", "q": "Rezumatul elimină detaliile ____.", "answers": ["nesemnificative", "neimportante"], "why": "Este o formă concisă, fără detalii nesemnificative.", "n": [0]}, {"type": "classify", "q": "Încadrează în categoria potrivită: se face sau nu se face într-un rezumat.", "categories": ["Se face în rezumat", "Nu se face în rezumat"], "items": [{"t": "reformularea cu propriile cuvinte", "c": 0}, {"t": "comentarii personale", "c": 1}, {"t": "dialog", "c": 1}, {"t": "cuvinte de legătură (apoi, mai târziu)", "c": 0}, {"t": "pornirea de la ideile principale", "c": 0}, {"t": "citate", "c": 1}], "n": [1, 2]}, {"type": "mcq", "q": "Care este un cuvânt de legătură potrivit pentru un rezumat?", "options": ["din păcate", "în cele din urmă", "după părerea mea", "mi se pare că"], "answer": 1, "why": "Legăturile redau cursivitatea; comentariile personale sunt interzise.", "n": [1]}]}, {"id": "u2-l9", "number": 9, "title": "Verbul", "section": "Limbă română", "pages": "p. 64-67", "source": "", "theory": [{"term": "Verbul", "kind": "definition", "text": "Verbul este partea de vorbire care arată acțiunea, starea sau existența.", "examples": [], "important": true}, {"term": "Verbe predicative și nepredicative", "kind": "classification", "text": "Verbele sunt, după capacitatea de predicație:\n- predicative, când pot alcătui singure predicat (de exemplu: Am o carte veche.);\n- nepredicative, când nu pot alcătui singure predicat (de exemplu: Am inventat o rețetă.).", "examples": ["Am o carte veche.", "Am inventat o rețetă."], "important": true}, {"term": "Verbele auxiliare", "kind": "classification", "text": "Verbele nepredicative care ajută la formarea unor moduri și timpuri se numesc verbe auxiliare. În limba română, verbele auxiliare sunt:\n- a avea, care ajută la formarea perfectului compus, modul indicativ: Am cules cimbrișor.;\n- a vrea, care ajută la formarea viitorului standard și a viitorului anterior, modul indicativ: După ce vei fi văzut efectul poțiunii, vei învăța.;\n- a fi, care ajută la formarea viitorului anterior: Voi fi găsit cartea pierdută, când voi veni la tine.", "examples": ["Am cules cimbrișor.", "vei învăța", "Voi fi găsit cartea pierdută"], "important": true}, {"term": "Funcția sintactică", "kind": "definition", "text": "Funcția sintactică reprezintă rolul unei părți de propoziție în enunț. Verbele predicative au funcția sintactică de predicat verbal.", "examples": [], "important": true}, {"term": "Modul", "kind": "definition", "text": "Modul este forma pe care o ia verbul pentru a arăta cum consideră vorbitorul acțiunea. Acțiunile pot fi:\n- sigure – la modul indicativ;\n- posibile – la modul imperativ.\nVerbele care au categoria gramaticală a modului își modifică forma după persoană și în propoziție au funcția sintactică de predicat.", "examples": [], "important": true}, {"term": "Modul indicativ", "kind": "definition", "text": "Modul indicativ arată o acțiune sigură, reală. Este singurul mod care are toate timpurile (prezent, trecut, viitor).", "examples": [], "important": true}, {"term": "Prezentul", "kind": "definition", "text": "Prezentul arată desfășurarea acțiunii în momentul vorbirii. Prezentul se construiește cu:\n- desinențe, sunetele sau grupurile de sunete care indică persoana și numărul verbului; de exemplu: cântăm, ziceți;\n- sunete sau grupuri de sunete care indică timpul; de exemplu: cântați, lucrează, vorbim.", "examples": ["cântăm", "ziceți", "lucrează", "vorbim"], "important": true}, {"term": "Trecutul – cele patru forme", "kind": "definition", "text": "Trecutul arată desfășurarea acțiunii înainte de momentul vorbirii. Trecutul are patru forme: imperfectul, perfectul compus, perfectul simplu și mai-mult-ca-perfectul.", "examples": [], "important": true}, {"term": "Imperfectul", "kind": "definition", "text": "Imperfectul exprimă o acțiune trecută care se desfășoară în același timp cu o altă acțiune trecută, având valoare durativă. Sunetul și grupul de sunete care indică timpul imperfect sunt: -a- și -ea-.", "examples": ["schimbau", "zbura", "vorbeai", "râdeau"], "important": true}, {"term": "Perfectul compus", "kind": "definition", "text": "Perfectul compus exprimă o acțiune trecută și terminată în momentul vorbirii. Este alcătuit din forme specifice ale verbului auxiliar a avea + participiul verbului de conjugat (am cântat).", "examples": ["am cântat", "au alergat", "a fermecat"], "important": true}, {"term": "Perfectul simplu", "kind": "definition", "text": "Perfectul simplu exprimă, în limba literară, o acțiune trecută și terminată în momentul vorbirii. Are același sens cu perfectul compus, fiind, în limba literară, timpul povestirii la persoana a III-a. Astăzi, acest timp a dispărut din limba literară vorbită, luându-i locul perfectul compus. Este folosit doar cu intenție ironică: Vorbi și el!\nSunetele și grupul de sunete care indică perfectul simplu sunt: -a-, -u-, -se-, -i-, -â-.\nDesinența de perfect simplu este alcătuită din două părți: un segment -ră- (cu realizare zero la singular) și un segment final, comun cu alte timpuri (ascultarăți, ziseră).", "examples": ["Vorbi și el!", "ascultarăți", "ziseră", "dormiră", "fugiră"], "important": true}, {"term": "Mai-mult-ca-perfectul", "kind": "definition", "text": "Mai-mult-ca-perfectul exprimă o acțiune trecută și terminată înaintea altei acțiuni trecute. Grupul de sunete care indică mai-mult-ca-perfectul este -se-, aflat după sunetul care indică perfectul simplu (căutasem, apăruseși, ziseserăm, dormiserăți, hotărâseră).", "examples": ["căutasem", "apăruseși", "ziseserăm", "dormiserăți", "hotărâseră", "preparase", "băuseră"], "important": true}, {"term": "Greșeli la mai-mult-ca-perfect", "kind": "norm", "text": "O greșeală frecventă apare la persoana a II-a, singular, prin folosirea desinenței -i în loc de -și: alergasei (corect alergaseși), vorbisei (corect vorbiseși). La persoana I și a II-a plural, formele fără -ră- sunt învechite și populare, nefiind acceptate: vorbiseți (corect vorbiserăți).", "examples": ["alergaseși (nu alergasei)", "vorbiserăți (nu vorbiseți)"], "important": true}, {"term": "Viitorul – forme", "kind": "definition", "text": "Viitorul arată o acțiune care se va desfășura după momentul vorbirii. Viitorul are trei forme: viitorul standard, viitorul anterior și viitorul în trecut.", "examples": [], "important": true}, {"term": "Viitorul standard", "kind": "definition", "text": "Viitorul standard este:\n- folosit mai ales în limba scrisă, alcătuit din forme specifice ale verbului auxiliar a vrea + infinitivul verbului de conjugat (voi asculta);\n- folosit în limba vorbită cu două structuri, alcătuite din: verbul a avea la indicativ, prezent + o formă cu să a verbului de conjugat (am să ascult) și o invariabil + o formă cu să a verbului de conjugat (o să ascult).", "examples": ["voi asculta", "am să ascult", "o să ascult"], "important": true}, {"term": "Viitorul anterior", "kind": "definition", "text": "Viitorul anterior exprimă o acțiune viitoare, terminată înaintea altei acțiuni viitoare. Este alcătuit din verbul auxiliar a vrea + verbul auxiliar a fi + participiul verbului de conjugat. Astăzi, acest timp aproape a dispărut din limbă, fiind folosit rar și atunci obligatoriu în relație cu un viitor standard. De exemplu: Când voi ieși afară, băieții vor fi format echipa.", "examples": ["Când voi ieși afară, băieții vor fi format echipa.", "voi fi terminat"], "important": true}, {"term": "Viitorul în trecut", "kind": "definition", "text": "Viitorul în trecut exprimă o acțiune desfășurată în trecut, dar care în acel moment reprezenta o faptă viitoare, încă nerealizată. Este alcătuit din imperfectul verbului a avea și o formă cu să a verbului de conjugat. De exemplu: După ce mi-am pus căștile, aveam să ascult melodia mea preferată.", "examples": ["aveam să ascult", "aveam să plecăm"], "important": true}, {"term": "Modul imperativ", "kind": "definition", "text": "Modul imperativ arată o acțiune posibilă, realizabilă, exprimând un ordin, un îndemn, un sfat, o rugăminte. Are forme doar pentru persoana a II-a, singular și plural. Nu are forme specifice de timp. Imperativul are:\n- formă afirmativă; de exemplu: Ascultă! Ascultați!;\n- formă negativă, alcătuită la persoana a II-a, singular din cuvântul nu + verbul de conjugat la infinitiv (Nu asculta!) și la persoana a II-a, plural din cuvântul nu + imperativul afirmativ (Nu ascultați!).", "examples": ["Ascultă!", "Ascultați!", "Nu asculta!", "Nu ascultați!"], "important": true}, {"term": "Formele verbale nepersonale", "kind": "definition", "text": "Există și forme verbale nepersonale, care nu indică atitudinea vorbitorului în legătură cu acțiunea. Aceste forme nu își modifică forma în raport cu persoana și nu pot fi predicate. Formele verbale nepersonale învățate sunt:\n- infinitivul – forma din dicționar a verbului; poate apărea precedat sau nu de prepoziția a (a asculta);\n- participiul – arată o acțiune suferită de o ființă sau de un lucru (ascultat, ales); participiul ajută la formarea unor moduri și timpuri când are valoare verbală și devine adjectiv când este folosit singur (Cântecul ascultat este frumos.).", "examples": ["a asculta", "ascultat", "ales", "Cântecul ascultat este frumos."], "important": true}, {"term": "Forme corecte și incorecte (exercițiu)", "kind": "norm", "text": "Din exercițiul „Normă și abatere” (ex. 4): la indicativ, prezent, formele corecte sunt aranjează, creează, scrii, copiez; formele incorecte sunt aranjază, crează, scri, copii (în locul lui copiez).", "examples": ["aranjează", "creează", "scrii", "copiez"], "important": false, "derived": true}], "flashcards": [{"front": "Ce este verbul?", "back": "Partea de vorbire care arată acțiunea, starea sau existența.", "n": [0]}, {"front": "Ce sunt verbele predicative?", "back": "Verbele care pot alcătui singure predicat (Am o carte veche).", "n": [1]}, {"front": "Care sunt verbele auxiliare din limba română?", "back": "A avea, a vrea, a fi.", "n": [2]}, {"front": "Ce timp formează auxiliarul a avea la indicativ?", "back": "Perfectul compus (am cântat).", "n": [2, 9]}, {"front": "Ce arată modul indicativ?", "back": "O acțiune sigură, reală; este singurul mod cu toate timpurile.", "n": [5]}, {"front": "Care sunt cele patru forme ale trecutului?", "back": "Imperfectul, perfectul compus, perfectul simplu, mai-mult-ca-perfectul.", "n": [7]}, {"front": "Ce indică imperfectul?", "back": "Sunetele -a- și -ea-; acțiune trecută cu valoare durativă.", "n": [8]}, {"front": "Cum se formează viitorul anterior?", "back": "A vrea + a fi + participiul verbului de conjugat (voi fi terminat).", "n": [15]}, {"front": "Cum se formează viitorul în trecut?", "back": "Imperfectul lui a avea + o formă cu să (aveam să ascult).", "n": [16]}, {"front": "Cum se formează imperativul negativ la persoana a II-a, singular?", "back": "Nu + infinitivul verbului (Nu asculta!).", "n": [17]}], "quiz": [{"type": "mcq", "q": "Care dintre verbele următoare este auxiliar?", "options": ["a cânta", "a fi (în Voi fi găsit)", "a merge", "a dormi"], "answer": 1, "why": "Auxiliarele sunt a avea, a vrea, a fi.", "n": [2]}, {"type": "mcq", "q": "Perfectul compus se formează cu:", "options": ["a vrea + infinitiv", "a avea + participiu", "a fi + infinitiv", "imperfectul lui a avea + să"], "answer": 1, "why": "Perfectul compus: a avea + participiul verbului de conjugat.", "n": [2, 9]}, {"type": "tf", "q": "Modul indicativ este singurul mod care are toate timpurile.", "answer": true, "why": "Așa spune cartea.", "n": [5]}, {"type": "tf", "q": "Modul imperativ are forme pentru toate persoanele.", "answer": false, "why": "Are forme doar pentru persoana a II-a, singular și plural.", "n": [17]}, {"type": "fill", "q": "Grupul de sunete care indică mai-mult-ca-perfectul este -____-.", "answers": ["se"], "why": "Ex.: căutasem, apăruseși.", "n": [11]}, {"type": "fill", "q": "Forma corectă la persoana a II-a singular, mai-mult-ca-perfect, a verbului a vorbi este vorbi____.", "answers": ["seși"], "why": "Corect vorbiseși, nu vorbisei.", "n": [11, 12]}, {"type": "mcq", "q": "Care este formă corectă?", "options": ["aranjază", "crează", "scrii", "copii (de la a copia, persoana I)"], "answer": 2, "why": "Corecte: aranjează, creează, scrii, copiez.", "n": [19]}, {"type": "classify", "q": "Încadrează verbele în timpul trecut potrivit.", "categories": ["Imperfect", "Perfect compus", "Perfect simplu", "Mai-mult-ca-perfect"], "items": [{"t": "schimbau", "c": 0}, {"t": "au alergat", "c": 1}, {"t": "dormiră", "c": 2}, {"t": "preparase", "c": 3}, {"t": "zbura", "c": 0}, {"t": "a fermecat", "c": 1}, {"t": "fugiră", "c": 2}, {"t": "băuseră", "c": 3}], "n": [7, 8, 9, 10, 11]}, {"type": "match", "q": "Potrivește timpul viitor cu exemplul.", "pairs": [["viitor standard (limba scrisă)", "voi asculta"], ["viitor standard (limba vorbită)", "o să ascult"], ["viitor anterior", "voi fi terminat"], ["viitor în trecut", "aveam să ascult"]], "n": [13, 14, 15, 16]}, {"type": "match", "q": "Potrivește timpul cu valoarea lui.", "pairs": [["Imperfect", "acțiune trecută durativă, simultană cu alta"], ["Perfect compus", "acțiune trecută și terminată"], ["Mai-mult-ca-perfect", "acțiune terminată înaintea altei acțiuni trecute"], ["Imperativ", "ordin, îndemn, sfat, rugăminte"]], "n": [8, 9, 11, 17]}, {"type": "mcq", "q": "Verbul este partea de vorbire care arată:", "options": ["însușirea unui obiect", "acțiunea, starea sau existența", "locul acțiunii", "numărul obiectelor"], "answer": 1, "why": "Verbul este partea de vorbire care arată acțiunea, starea sau existența.", "n": [0]}, {"type": "tf", "q": "Verbele predicative sunt cele care pot alcătui singure predicat.", "answer": true, "why": "Predicative = pot alcătui singure predicat; nepredicative = nu pot.", "n": [1]}, {"type": "tf", "q": "Verbele predicative au funcția sintactică de predicat verbal.", "answer": true, "why": "Funcția sintactică este rolul unei părți de propoziție în enunț; verbele predicative sunt predicat verbal.", "n": [3]}, {"type": "mcq", "q": "Modul indicativ arată acțiuni:", "options": ["posibile", "sigure", "dorite", "imposibile"], "answer": 1, "why": "Acțiunile sigure sunt la modul indicativ, cele posibile la imperativ.", "n": [4]}, {"type": "fill", "q": "Prezentul arată desfășurarea acțiunii în momentul ____.", "answers": ["vorbirii"], "why": "Prezentul arată desfășurarea acțiunii în momentul vorbirii.", "n": [6]}, {"type": "tf", "q": "Formele verbale nepersonale își modifică forma în raport cu persoana.", "answer": false, "why": "Formele nepersonale (infinitiv, participiu) nu își modifică forma după persoană și nu pot fi predicate.", "n": [18]}]}, {"id": "u2-l10", "number": 10, "title": "Modul conjunctiv", "section": "Limbă română", "pages": "p. 68-69", "source": "", "theory": [{"term": "Modul conjunctiv", "kind": "definition", "text": "Modul conjunctiv arată o acțiune posibilă, realizabilă. Marca gramaticală a modului conjunctiv este cuvântul să. La începutul enunțurilor orale, conjunctivul la persoana a III-a poate să apară fără cuvântul să: Facă ce-o dori! Verbele predicative la modul conjunctiv au funcția sintactică de predicat verbal.", "examples": ["Facă ce-o dori!", "să cânt", "să cânți"], "important": true}, {"term": "Timpurile conjunctivului", "kind": "classification", "text": "Modul conjunctiv are două timpuri:\n- prezent, care arată o acțiune ce se poate desfășura în momentul vorbirii sau după momentul vorbirii (să cânt);\n- perfect, care arată o acțiune ce se poate desfășura înainte de momentul vorbirii (să fi cântat).", "examples": ["să cânt", "să fi cântat"], "important": true}, {"term": "Formarea conjunctivului prezent", "kind": "rule", "text": "Timpul prezent al modului conjunctiv este alcătuit din cuvântul să + formele de indicativ, prezent ale verbului de conjugat, cu excepția persoanei a III-a.", "examples": ["să cânt", "să cânți", "să cânte", "să mergem"], "important": true}, {"term": "Formarea conjunctivului perfect", "kind": "rule", "text": "Timpul perfect al modului conjunctiv este alcătuit din cuvântul să + verbul auxiliar a fi + participiul verbului de conjugat. Timpul perfect are aceeași formă la toate persoanele, la ambele numere.", "examples": ["să fi cântat", "să fi apărut", "să fi dormit"], "important": true}, {"term": "Forma negativă și intercalarea cuvintelor", "kind": "rule", "text": "Forma negativă se construiește cu ajutorul cuvântului nu: să nu cânt, să nu fi cântat.\nCuvintele cam, mai, tot se pot intercala la conjunctiv, prezent între cuvântul să și verb, iar la conjunctiv, perfect între cuvântul să și verbul auxiliar a fi.", "examples": ["să nu cânt", "să nu fi cântat", "să mai cânt", "să tot fi jucat"], "important": true}, {"term": "Corectarea enunțurilor cu cam, mai, tot (exercițiu)", "kind": "norm", "text": "Corecturi din exercițiul „Normă și abatere”: Obișnuiește să cam bombăne. (nu: cam să bombăne); Să ne mai ajutați și altă dată! (nu: să mai ne ajutați); Să tot fi jucat fotbal pe vreme însorită! (nu: tot să fi jucat). Regula din manual: cam, mai, tot se intercalează între să și verb (prezent) sau între să și fi (perfect).", "examples": ["Obișnuiește să cam bombăne.", "Să ne mai ajutați și altă dată!", "Să tot fi jucat fotbal!"], "important": false, "derived": true}], "flashcards": [{"front": "Ce arată modul conjunctiv?", "back": "O acțiune posibilă, realizabilă.", "n": [0]}, {"front": "Care este marca gramaticală a conjunctivului?", "back": "Cuvântul să.", "n": [0]}, {"front": "Care sunt timpurile conjunctivului?", "back": "Prezent și perfect.", "n": [1]}, {"front": "Cum se formează conjunctivul perfect?", "back": "Să + a fi + participiul verbului de conjugat (să fi cântat).", "n": [3]}, {"front": "Cum se formează conjunctivul prezent?", "back": "Să + formele de indicativ prezent, cu excepția persoanei a III-a.", "n": [2]}, {"front": "Cum se formează forma negativă a conjunctivului?", "back": "Cu cuvântul nu: să nu cânt, să nu fi cântat.", "n": [4]}, {"front": "Ce cuvinte se pot intercala la conjunctiv?", "back": "Cam, mai, tot.", "n": [4]}], "quiz": [{"type": "mcq", "q": "Marca gramaticală a modului conjunctiv este:", "options": ["ar", "să", "va", "nu"], "answer": 1, "why": "Cuvântul să.", "n": [0]}, {"type": "mcq", "q": "Care formă este la conjunctiv, timpul perfect?", "options": ["să cânt", "să cânte", "să fi cântat", "aș cânta"], "answer": 2, "why": "Perfect: să + a fi + participiu.", "n": [1, 3]}, {"type": "tf", "q": "Conjunctivul perfect are aceeași formă la toate persoanele și numerele.", "answer": true, "why": "Să fi cântat este invariabil.", "n": [3]}, {"type": "tf", "q": "Conjunctivul prezent arată o acțiune desfășurată înainte de momentul vorbirii.", "answer": false, "why": "Prezentul arată acțiunea în momentul sau după momentul vorbirii; perfectul arată acțiunea dinainte.", "n": [1]}, {"type": "fill", "q": "Forma negativă a conjunctivului se construiește cu cuvântul ____.", "answers": ["nu"], "why": "Ex.: să nu cânt.", "n": [4]}, {"type": "mcq", "q": "Care enunț este corect?", "options": ["Tot să fi jucat fotbal!", "Să tot fi jucat fotbal!", "Să fi tot jucat fotbal!", "Tot fi să jucat fotbal!"], "answer": 1, "why": "Tot se intercalează între să și fi.", "n": [4, 5]}, {"type": "classify", "q": "Încadrează formele conjunctivului după timp.", "categories": ["Prezent", "Perfect"], "items": [{"t": "să merg", "c": 0}, {"t": "să fi mers", "c": 1}, {"t": "să nu fi răspuns", "c": 1}, {"t": "să nu calci", "c": 0}, {"t": "să citească", "c": 0}], "n": [1, 2, 3]}]}, {"id": "u2-l11", "number": 11, "title": "Modul condițional-optativ", "section": "Limbă română", "pages": "p. 70-71", "source": "", "theory": [{"term": "Modul condițional-optativ", "kind": "definition", "text": "Modul condițional-optativ arată acțiuni posibile a căror realizare depinde de o condiție sau arată acțiuni dorite.", "examples": ["Aș vrea să fiu o frunză.", "Dacă ai fi uitat acasă jocul Dixit, l-am fi împrumutat de la colegii noștri."], "important": true}, {"term": "Timpurile condițional-optativului", "kind": "classification", "text": "Modul condițional-optativ are două timpuri:\n- prezent, care arată o acțiune desfășurată în momentul vorbirii ori după momentul vorbirii;\n- perfect, care arată o acțiune desfășurată înainte de momentul vorbirii.", "examples": [], "important": true}, {"term": "Formarea timpurilor", "kind": "rule", "text": "Timpul prezent al modului condițional-optativ se formează cu verbul auxiliar a avea + infinitivul verbului de conjugat (aș cânta).\nTimpul perfect al modului condițional-optativ se formează cu verbul auxiliar a avea + verbul auxiliar a fi + participiul verbului de conjugat.", "examples": ["aș cânta", "ar fi cântat", "ați fi lucrat"], "important": true}, {"term": "Forma negativă și funcția sintactică", "kind": "rule", "text": "Forma negativă se construiește cu ajutorul cuvântului nu (nu aș cânta/n-aș cânta, nu ar fi cântat/n-ar fi cântat). Verbele predicative la condițional-optativ au funcția sintactică de predicat verbal.", "examples": ["n-aș cânta", "n-ar fi cântat"], "important": true}, {"term": "Forme inverse", "kind": "rule", "text": "La timpul prezent există și forme inverse în limba vorbită, în construcții afective din limbajul familiar. Când între infinitiv și auxiliar nu este un pronume personal, infinitivului i se adaugă grupul de sunete -re (Cântare-aș, dar n-am glas!).", "examples": ["Cântare-aș, dar n-am glas!", "Mânca-l-ar mama de drăgălaș!"], "important": true}, {"term": "Intercalarea cuvintelor cam, mai, tot", "kind": "rule", "text": "La condițional-optativ, prezent, cuvintele cam, mai, tot se intercalează între verbul auxiliar și infinitivul verbului de conjugat (aș mai cânta), iar la perfect, între cele două verbe auxiliare (aș mai fi cântat).", "examples": ["aș mai cânta", "aș mai fi cântat"], "important": true}, {"term": "Ortograme pentru condițional-optativ (exercițiu)", "kind": "tip", "text": "Ortograme pentru condițional-optativ: c-ai/cai, c-aș/caș, m-ai/mai, n-ai/nai, n-aș/naș, ne-am/neam, s-ar/sar, v-ar/var.", "examples": ["n-aș", "s-ar", "v-ar"], "important": false, "derived": true}], "flashcards": [{"front": "Ce arată condițional-optativul?", "back": "Acțiuni posibile a căror realizare depinde de o condiție sau acțiuni dorite.", "n": [0]}, {"front": "Cum se formează condițional-optativul prezent?", "back": "A avea + infinitivul verbului de conjugat (aș cânta).", "n": [2]}, {"front": "Cum se formează condițional-optativul perfect?", "back": "A avea + a fi + participiul verbului de conjugat (aș fi cântat).", "n": [2]}, {"front": "Unde se intercalează cam, mai, tot la condițional-optativ prezent?", "back": "Între auxiliar și infinitiv (aș mai cânta).", "n": [5]}, {"front": "Unde se intercalează cam, mai, tot la perfect?", "back": "Între cele două verbe auxiliare (aș mai fi cântat).", "n": [5]}, {"front": "Ce este forma inversă a condițional-optativului?", "back": "Cântare-aș: infinitiv + -re + auxiliar, în limba vorbită, în construcții afective.", "n": [4]}], "quiz": [{"type": "mcq", "q": "Care formă este condițional-optativ, timpul perfect?", "options": ["aș cânta", "ar fi cântat", "să fi cântat", "am cântat"], "answer": 1, "why": "Perfect: a avea + a fi + participiu.", "n": [1, 2]}, {"type": "mcq", "q": "Care este ordinea corectă?", "options": ["Dan mai ar sta în pauză", "Dan ar mai sta în pauză", "Dan ar sta mai în pauză", "Dan ar sta în mai pauză"], "answer": 1, "why": "Mai se intercalează între auxiliar și infinitiv.", "n": [5]}, {"type": "tf", "q": "Condițional-optativul are două timpuri: prezent și perfect.", "answer": true, "why": "Așa spune cartea.", "n": [1]}, {"type": "tf", "q": "Condițional-optativul prezent se formează cu a avea + participiul verbului.", "answer": false, "why": "Prezentul se formează cu a avea + infinitiv.", "n": [2]}, {"type": "fill", "q": "Forma negativă a lui 'aș cânta' este ____ cânta.", "answers": ["n-aș", "n-as", "nu aș", "nu as"], "why": "Negația nu: nu aș cânta / n-aș cânta.", "n": [3]}, {"type": "match", "q": "Potrivește forma verbală cu timpul ei.", "pairs": [["aș cânta", "condițional-optativ prezent"], ["ar fi cântat", "condițional-optativ perfect"], ["să fi cântat", "conjunctiv perfect"], ["să cânte", "conjunctiv prezent"]], "n": [1, 2]}, {"type": "classify", "q": "Clasifică verbele la condițional-optativ după timp.", "categories": ["Prezent", "Perfect"], "items": [{"t": "n-ar ieși", "c": 0}, {"t": "n-ai fi putut", "c": 1}, {"t": "ați fi reușit", "c": 1}, {"t": "am putea merge", "c": 0}], "n": [1, 2, 3]}]}, {"id": "u2-l12", "number": 12, "title": "Posibilități combinatorii ale verbului. Predicatul nominal", "section": "Limbă română", "pages": "p. 72-73", "source": "", "theory": [{"term": "Verbul copulativ a fi", "kind": "definition", "text": "Verbul a fi poate avea valoare nepredicativă când se combină obligatoriu cu un alt cuvânt, substantiv sau adjectiv, pentru ca enunțul să aibă înțeles. În acest caz, verbul a fi se numește verb copulativ.", "examples": ["Dan este elev.", "El este inteligent."], "important": true}, {"term": "Predicatul nominal", "kind": "definition", "text": "Verbul a fi și cuvintele cu care acesta se grupează obligatoriu alcătuiesc un predicat nominal. Cuvintele care se adaugă verbului copulativ într-un predicat nominal constituie un nume predicativ. Predicatul nominal este alcătuit din verbul copulativ a fi + nume predicativ.", "examples": ["este elev", "este inteligent"], "important": true}, {"term": "Rolul verbului copulativ", "kind": "rule", "text": "Verbul copulativ:\n- face legătura dintre subiect și numele predicativ;\n- nu are înțeles de sine stătător, fiind verb nepredicativ;\n- alcătuiește un predicat nominal când are categoria gramaticală a modului.", "examples": [], "important": true}, {"term": "Numele predicativ", "kind": "definition", "text": "Numele predicativ se poate exprima prin:\n- adjectiv (Fetele sunt înalte.);\n- substantiv (Ioana este elevă.).\nNumele predicativ precizează caracteristica subiectului. Numele predicativ este:\n- simplu, când este exprimat printr-un singur termen (Ina este mică.);\n- multiplu, când este exprimat prin doi sau mai mulți termeni (Ina este mică și cuminte.).", "examples": ["Fetele sunt înalte.", "Ioana este elevă.", "Ina este mică.", "Ina este mică și cuminte."], "important": true}, {"term": "Acordul numelui predicativ cu subiectul", "kind": "rule", "text": "Numele predicativ intră într-o relație ternară, fiind cerut obligatoriu de verbul copulativ, dar depinzând și de subiect. Subiectul impune genul și numărul substantivului sau adjectivului cu funcție sintactică de nume predicativ (Fetele sunt eleve. Băiatul este inteligent.).", "examples": ["Fetele sunt eleve.", "Băiatul este inteligent."], "important": true}, {"term": "Felurile verbului a fi", "kind": "classification", "text": "Verbul a fi poate fi:\n- copulativ (Ileana este frumoasă.);\n- predicativ (Vlad este în laborator.);\n- auxiliar (Aș fi mâncat un măr.).", "examples": ["Ileana este frumoasă.", "Vlad este în laborator.", "Aș fi mâncat un măr."], "important": true}], "flashcards": [{"front": "Când se numește verbul a fi copulativ?", "back": "Când se combină obligatoriu cu un substantiv sau adjectiv pentru ca enunțul să aibă înțeles.", "n": [0]}, {"front": "Din ce este alcătuit predicatul nominal?", "back": "Verb copulativ a fi + nume predicativ.", "n": [1]}, {"front": "Prin ce se poate exprima numele predicativ?", "back": "Prin adjectiv sau substantiv.", "n": [3]}, {"front": "Ce este numele predicativ multiplu?", "back": "Cel exprimat prin doi sau mai mulți termeni (Ina este mică și cuminte).", "n": [3]}, {"front": "Ce impune subiectul numelui predicativ?", "back": "Genul și numărul.", "n": [4]}, {"front": "Care sunt felurile verbului a fi?", "back": "Copulativ, predicativ, auxiliar.", "n": [5]}, {"front": "Ce relație are numele predicativ?", "back": "Relație ternară: cerut de verbul copulativ, dar depinde și de subiect.", "n": [4]}], "quiz": [{"type": "mcq", "q": "În propoziția Vlad este în laborator, verbul a fi este:", "options": ["copulativ", "predicativ", "auxiliar", "nepredicativ"], "answer": 1, "why": "Are sens de sine stătător (se află), deci este predicativ.", "n": [5]}, {"type": "mcq", "q": "În Aș fi mâncat un măr, verbul a fi este:", "options": ["copulativ", "predicativ", "auxiliar", "nominal"], "answer": 2, "why": "Ajută la formarea condițional-optativului perfect.", "n": [5]}, {"type": "tf", "q": "Verbul copulativ este verb predicativ.", "answer": false, "why": "Este nepredicativ, fără înțeles de sine stătător.", "n": [2, 0]}, {"type": "fill", "q": "Predicatul nominal este alcătuit din verbul copulativ a fi + nume ____.", "answers": ["predicativ"], "why": "Definiție.", "n": [1]}, {"type": "classify", "q": "Precizează felul numelui predicativ.", "categories": ["Simplu", "Multiplu"], "items": [{"t": "Ina este mică.", "c": 0}, {"t": "Ina este mică și cuminte.", "c": 1}, {"t": "Colegii sunt veseli, zburdalnici și prietenoși.", "c": 1}, {"t": "Fetița este foarte simpatică.", "c": 0}], "n": [3]}, {"type": "match", "q": "Potrivește exemplul cu felul verbului a fi.", "pairs": [["Ileana este frumoasă.", "copulativ"], ["Vlad este în laborator.", "predicativ"], ["Aș fi mâncat un măr.", "auxiliar"]], "n": [5]}, {"type": "tf", "q": "Numele predicativ poate fi exprimat prin adjectiv sau substantiv.", "answer": true, "why": "Fetele sunt înalte (adjectiv); Ioana este elevă (substantiv).", "n": [3]}]}, {"id": "u2-l13", "number": 13, "title": "Subiectul", "section": "Limbă română", "pages": "p. 74-75", "source": "", "theory": [{"term": "Subiectul", "kind": "definition", "text": "Subiectul este partea principală de propoziție care arată cine face acțiunea exprimată de un predicat verbal sau cui i se atribuie o însușire ori o caracteristică exprimată de numele predicativ al unui predicat nominal. Subiectul are o poziție favorizată în raport cu verbul predicat, pentru că nu numai verbul îi impune unele însușiri, dar și subiectul îi impune verbului anumite caracteristici, relația dintre subiect și predicat fiind o relație de interdependență.", "examples": ["Copilul aleargă.", "Pisoiul este blând."], "important": true}, {"term": "Subiect simplu și multiplu", "kind": "classification", "text": "Subiectul este:\n- simplu, când este alcătuit dintr-un singur termen (Ana citește.);\n- multiplu, când este alcătuit din doi sau mai mulți termeni (Dan și Ina scriu.).\nTermenii subiectului multiplu sunt legați prin virgulă sau prin cuvinte de legătură precum și. Termenii subiectului multiplu pot urma unul după altul sau pot fi despărțiți de alte părți de propoziție.", "examples": ["Ana citește.", "Dan și Ina scriu."], "important": true}, {"term": "Subiect exprimat și neexprimat", "kind": "classification", "text": "Subiectul poate fi exprimat sau neexprimat. Subiectul neexprimat poate fi:\n- subiect subînțeles, când a fost exprimat într-o propoziție anterioară și apare la persoana a III-a, singular și plural;\n- subiect inclus, când poate fi dedus (înțeles) din desinența verbului la persoana I și a II-a, singular și plural.", "examples": ["Vântul bate și mișcă ramurile. (subiect subînțeles)", "Alergăm în curte. (subiect inclus)"], "important": true}, {"term": "Propoziții fără subiect", "kind": "rule", "text": "Enunțurile cu verbe referitoare la fenomene meteorologice (Plouă. Geruiește.) nu au subiect.", "examples": ["Plouă.", "Geruiește.", "Burnițează de ieri.", "Azi, a nins puțin."], "important": true}, {"term": "Exprimarea subiectului pronominal", "kind": "norm", "text": "Neexprimarea subiectului pronominal la persoana I și a II-a este o caracteristică a limbii române și este o greșeală ca în aceste cazuri să apară subiecte exprimate prin pronume personale (Eu învăț.), fiindcă se repetă informația din desinență. Exprimarea subiectului pronominal este obligatorie doar atunci când:\n- are valoare de insistență: Tu ai murdărit tabla, tu s-o ștergi.\n- are valoare de opoziție: Eu lucrez și tu doar privești.", "examples": ["Tu ai murdărit tabla, tu s-o ștergi.", "Eu lucrez și tu doar privești."], "important": true}, {"term": "Acordul predicatului cu subiectul", "kind": "rule", "text": "Verbul predicativ prin care se exprimă predicatul verbal și verbul copulativ din alcătuirea unui predicat nominal se acordă în persoană și număr cu partea de vorbire prin care se exprimă subiectul. Dacă subiectul este multiplu, verbul cu funcție sintactică de predicat se acordă la plural. Când subiectul multiplu se exprimă prin pronume diferite, persoana I are preponderență față de persoana a II-a și a III-a, iar persoana a II-a are preponderență față de persoana a III-a.", "examples": ["Noi și voi vom participa la cercul de lectură.", "Voi și ei veți lucra împreună."], "important": true}], "flashcards": [{"front": "Ce este subiectul?", "back": "Partea principală de propoziție care arată cine face acțiunea sau cui i se atribuie o însușire.", "n": [0]}, {"front": "Ce relație este între subiect și predicat?", "back": "Interdependență.", "n": [5]}, {"front": "Ce este subiectul multiplu?", "back": "Cel alcătuit din doi sau mai mulți termeni (Dan și Ina scriu).", "n": [1]}, {"front": "Ce este subiectul subînțeles?", "back": "Subiect neexprimat, exprimat într-o propoziție anterioară, la persoana a III-a.", "n": [2]}, {"front": "Ce este subiectul inclus?", "back": "Subiect neexprimat dedus din desinența verbului la persoana I și a II-a.", "n": [2]}, {"front": "Au subiect verbele care arată fenomene meteorologice?", "back": "Nu (Plouă. Geruiește.).", "n": [3]}, {"front": "Când e obligatoriu subiectul pronominal la pers. I și a II-a?", "back": "Când are valoare de insistență sau de opoziție.", "n": [4]}, {"front": "Care persoană are preponderență la subiecte multiple?", "back": "Persoana I înaintea celei de-a II-a și a III-a; a II-a înaintea a III-a.", "n": [5]}], "quiz": [{"type": "mcq", "q": "Care propoziție NU are subiect?", "options": ["Copiii au ieșit.", "Plouă.", "Alergăm în curte.", "Ana citește."], "answer": 1, "why": "Verbele despre fenomene meteorologice nu au subiect.", "n": [3]}, {"type": "mcq", "q": "În Dan și Ina scriu, subiectul este:", "options": ["simplu", "multiplu", "inclus", "subînțeles"], "answer": 1, "why": "Are doi termeni legați prin și.", "n": [1]}, {"type": "tf", "q": "În Eu învăț, subiectul exprimat prin pronume este corect, deoarece subiectul nu poate lipsi.", "answer": false, "why": "La persoana I și a II-a subiectul pronominal nu se exprimă, decât pentru insistență sau opoziție.", "n": [4]}, {"type": "fill", "q": "Subiectul dedus din desinența verbului la persoana I sau a II-a se numește subiect ____.", "answers": ["inclus"], "why": "Ex.: Alergăm în curte.", "n": [2]}, {"type": "fill", "q": "Subiectul exprimat într-o propoziție anterioară, la persoana a III-a, se numește subiect ____.", "answers": ["subînțeles", "subinteles"], "why": "Este subiect neexprimat subînțeles.", "n": [2]}, {"type": "classify", "q": "Încadrează subiectele neexprimate.", "categories": ["Subiect subînțeles", "Subiect inclus"], "items": [{"t": "Vântul bate și mișcă ramurile. (mișcă)", "c": 0}, {"t": "Plecați la munte? (plecați)", "c": 1}, {"t": "Norii au acoperit cerul și anunță ploi. (anunță)", "c": 0}, {"t": "Treci pe la mine. (treci)", "c": 1}], "n": [2]}, {"type": "mcq", "q": "Ce persoană are prioritate la acordul în Noi și voi vom participa?", "options": ["a III-a", "a II-a", "I", "niciuna"], "answer": 2, "why": "Persoana I are preponderență; verbul este la persoana I, plural.", "n": [5]}, {"type": "tf", "q": "Dacă subiectul este multiplu, predicatul se acordă la plural.", "answer": true, "why": "Regula de acord.", "n": [5]}]}, {"id": "u2-l14", "number": 14, "title": "Complementul și circumstanțialul. Prepoziția", "section": "Limbă română", "pages": "p. 76-77", "source": "", "theory": [{"term": "Complementul și circumstanțialul", "kind": "definition", "text": "Complementul și circumstanțialul (care arată împrejurări) sunt părți secundare de propoziție care determină un verb. Întrebările acestor părți secundare de propoziție sunt:\n- pentru complement: pe cine? ce?; la cine? la ce? după cine? pentru ce? etc.; cui?\n- pentru circumstanțial: unde? pe unde? încotro? etc.; când? de când? până când? etc.; cum? în ce fel?", "examples": ["Maria face un desen. (ce face?)", "Anca îl strigă pe Matei. (pe cine strigă?)", "Dinu îi dă Adinei un sendviș. (cui dă?)", "În pauză, stăm în clasă. (când? unde?)", "Alex aleargă cu viteză. (cum?)"], "important": true}, {"term": "Exprimarea complementului și circumstanțialului", "kind": "rule", "text": "Complementele și circumstanțialele se pot exprima prin:\n- substantiv; Scrie un e-mail. Plec la munte.;\n- pronume; Mă gândesc la el. Merg la ei.", "examples": ["Scrie un e-mail.", "Plec la munte.", "Mă gândesc la el.", "Merg la ei."], "important": true}, {"term": "Prepoziția", "kind": "definition", "text": "Prepoziția este partea de vorbire care leagă un atribut, un complement sau un circumstanțial de cuvintele determinate.", "examples": [], "important": true}, {"term": "Felurile prepozițiilor", "kind": "classification", "text": "Prepozițiile sunt:\n- simple, când sunt alcătuite dintr-un singur termen (cu, de, în, între, la, lângă etc.);\n- compuse, când sunt alcătuite din doi sau mai mulți termeni (de la, de pe lângă, despre, înspre etc.).\nUnele prepoziții sunt purtătoare de sens (sub, lângă, spre, în etc.), altele sunt lipsite de sens (de, la etc.). Prepoziția se analizează împreună cu partea de vorbire înaintea căreia se află.", "examples": ["cu, de, în, între, la, lângă", "de la, de pe lângă, despre, înspre"], "important": true}, {"term": "Poziția verbului în enunț", "kind": "rule", "text": "Când are categoria modului, verbul ocupă doar poziția de centru al unui grup de cuvinte, îndeplinind funcție sintactică de:\n- predicat verbal, când este exprimat prin verb predicativ;\n- predicat nominal, când este verb copulativ însoțit obligatoriu de un nume predicativ.\nÎn calitate de centru, verbul la mod personal se poate combina cu:\n- numele predicativ, care constituie o poziție sintactică distinctă în predicatul nominal și intră într-o relație ternară cu verbul copulativ și subiectul, cărora li se subordonează;\n- subiectul, care ocupă o poziție favorizată, fiind într-o relație de interdependență cu predicatul;\n- complementul și circumstanțialul, care se subordonează unui verb predicativ.", "examples": [], "important": true}, {"term": "Unicitatea predicatului", "kind": "rule", "text": "Predicatul este singura parte de propoziție care nu admite repetarea în limitele unei propoziții, fiindcă două predicate impun existența a două propoziții.", "examples": [], "important": true}], "flashcards": [{"front": "Ce determină complementul și circumstanțialul?", "back": "Un verb; sunt părți secundare de propoziție.", "n": [0]}, {"front": "Care sunt întrebările circumstanțialului?", "back": "Unde? pe unde? încotro? când? de când? până când? cum? în ce fel?", "n": [0]}, {"front": "Care sunt întrebările complementului?", "back": "Pe cine? ce? la cine? la ce? după cine? pentru ce? cui?", "n": [0]}, {"front": "Prin ce se exprimă complementul și circumstanțialul?", "back": "Prin substantiv sau pronume.", "n": [1]}, {"front": "Ce este prepoziția?", "back": "Partea de vorbire care leagă un atribut, un complement sau un circumstanțial de cuvintele determinate.", "n": [2]}, {"front": "Ce sunt prepozițiile compuse?", "back": "Cele alcătuite din doi sau mai mulți termeni (de la, de pe lângă, despre, înspre).", "n": [3]}, {"front": "Câte predicate admite o propoziție?", "back": "Unul singur; două predicate impun două propoziții.", "n": [5]}], "quiz": [{"type": "mcq", "q": "Care este o prepoziție compusă?", "options": ["cu", "la", "de la", "între"], "answer": 2, "why": "De la este alcătuită din doi termeni.", "n": [3]}, {"type": "mcq", "q": "La ce întrebare răspunde circumstanțialul?", "options": ["cui?", "pe cine?", "unde?", "ce?"], "answer": 2, "why": "Unde? este întrebare pentru circumstanțial.", "n": [0]}, {"type": "tf", "q": "Complementul și circumstanțialul determină un verb.", "answer": true, "why": "Sunt părți secundare de propoziție care determină un verb.", "n": [0]}, {"type": "tf", "q": "O propoziție poate avea două predicate.", "answer": false, "why": "Două predicate impun existența a două propoziții.", "n": [5]}, {"type": "fill", "q": "Prepoziția este partea de vorbire care leagă un atribut, un complement sau un ____ de cuvintele determinate.", "answers": ["circumstanțial", "circumstantial"], "why": "Definiție.", "n": [2]}, {"type": "classify", "q": "Clasifică prepozițiile.", "categories": ["Simple", "Compuse"], "items": [{"t": "cu", "c": 0}, {"t": "de la", "c": 1}, {"t": "lângă", "c": 0}, {"t": "de pe lângă", "c": 1}, {"t": "înspre", "c": 1}, {"t": "între", "c": 0}], "n": [3]}, {"type": "classify", "q": "Clasifică întrebările.", "categories": ["Complement", "Circumstanțial"], "items": [{"t": "pe cine?", "c": 0}, {"t": "unde?", "c": 1}, {"t": "cui?", "c": 0}, {"t": "când?", "c": 1}, {"t": "cum?", "c": 1}, {"t": "după cine?", "c": 0}], "n": [0]}]}, {"id": "u2-l15", "number": 15, "title": "Rezumatul scris", "section": "Redactare", "pages": "p. 78-79", "source": "Băiatul cu pijamale în dungi (fragment) - John Boyne", "theory": [{"term": "Rezumatul scris", "kind": "definition", "text": "Rezumatul scris este prezentarea succintă, fără detalii nesemnificative, a unei înșiruiri de întâmplări reale sau imaginare. Rezumatul scris respectă toate regulile rezumatului oral (vezi rubrica Repere de la pagina 62).", "examples": [], "important": true}, {"term": "Pașii rezumatului scris", "kind": "rule", "text": "1 selectezi ce este important;\n2 respecți ordinea desfășurării întâmplărilor;\n3 folosești verbele la modul indicativ, timpul prezent sau perfect compus;\n4 formulezi ideile cu propriile cuvinte, fără comentarii personale, fără să dai citate;\n5 utilizezi cuvinte/grupuri de cuvinte de legătură care indică respectarea ordinii întâmplărilor.", "examples": [], "important": true}, {"term": "Gerunziul în rezumat", "kind": "tip", "text": "Pentru a concentra într-un singur cuvânt mai multe informații, în rezumat se utilizează gerunziul.", "examples": [], "important": true}, {"term": "Verbele în rezumatul scris (criterii din exercițiu)", "kind": "rule", "text": "Verbele sunt folosite la persoana a III-a, indiferent de persoana lor în textul dat. Verbele din rezumat sunt în majoritatea lor la indicativ, prezent sau perfect compus. Verbele care surprind acțiuni trecute sunt, majoritatea, la indicativ, perfect compus.", "examples": [], "important": false, "derived": true}, {"term": "Conținutul textului narativ de rezumat (fișă din exercițiu)", "kind": "tip", "text": "Conținutul textului: cadru – timpul și spațiul; personaje – cine participă la acțiune; conflictul – problema cu care se confruntă personajele; acțiunea – ce se întâmplă la început, în cuprins, la sfârșit; rezolvarea – cum este soluționată problema.", "examples": [], "important": false, "derived": true}], "flashcards": [{"front": "Ce este rezumatul scris?", "back": "Prezentarea succintă, fără detalii nesemnificative, a unei înșiruiri de întâmplări reale sau imaginare.", "n": [0]}, {"front": "La ce persoană sunt verbele în rezumat?", "back": "La persoana a III-a, indiferent de persoana din text.", "n": [3]}, {"front": "Ce timpuri se folosesc în rezumatul scris?", "back": "Indicativ, prezent sau perfect compus.", "n": [1, 3]}, {"front": "Ce se folosește pentru a concentra mai multe informații într-un cuvânt?", "back": "Gerunziul.", "n": [2]}, {"front": "Care este lungimea rezumatului față de textul de bază?", "back": "Mai scurt decât textul de bază.", "n": [0]}], "quiz": [{"type": "tf", "q": "Rezumatul scris respectă regulile rezumatului oral.", "answer": true, "why": "Așa spune Repere.", "n": [1]}, {"type": "fill", "q": "Pentru a concentra mai multe informații într-un singur cuvânt, în rezumat se folosește ____.", "answers": ["gerunziul"], "why": "Gerunziul.", "n": [2]}, {"type": "mcq", "q": "Verbele într-un rezumat sunt folosite la persoana:", "options": ["I singular", "a II-a plural", "a III-a", "oricare"], "answer": 2, "why": "Persoana a III-a, indiferent de persoana din text.", "n": [3]}, {"type": "mcq", "q": "Ce NU ar trebui să apară într-un rezumat?", "options": ["cuvinte de legătură", "comentarii personale", "ideile principale", "reformulări cu propriile cuvinte"], "answer": 1, "why": "Nu se fac comentarii personale.", "n": [1, 3]}, {"type": "classify", "q": "Poate apărea într-un rezumat scris?", "categories": ["Da", "Nu"], "items": [{"t": "apoi", "c": 0}, {"t": "citat din text", "c": 1}, {"t": "perfect compus", "c": 0}, {"t": "părerea personală", "c": 1}, {"t": "în cele din urmă", "c": 0}], "n": [1, 3]}, {"type": "tf", "q": "Rezumatul trebuie să fie la fel de lung sau mai lung decât textul de bază.", "answer": false, "why": "Rezumatul este mai scurt ca textul de bază.", "n": [0]}]}]}, {"unit": {"id": "u3", "number": 3, "title": "Dincolo de ferestre", "summary": "Descrierea literară în versuri (pastelul), epitetul și versificația, textul nonliterar (buletinul meteo, știrea), bradul în cultura populară, ascultarea activă, substantivul și cazurile lui (nominativ, acuzativ, dativ, genitiv, vocativ) și redactarea descrierii unui peisaj."}, "lessons": [{"id": "u3-l1", "number": 1, "title": "Textul descriptiv literar în versuri", "section": "Lectură", "pages": "p. 84-85", "source": "Iarna - Vasile Alecsandri", "theory": [{"term": "Vasile Alecsandri", "kind": "tip", "text": "Este scriitorul cel mai de seamă din generația care a participat la Revoluția de la 1848, fiind supranumit „bardul de la Mircești”, după numele moșiei sale. A valorificat folclorul în volume ca Doine, Lăcrămioare, Legende. A fost un deschizător de drumuri și în teatru (Chirița, Despot-Vodă). Partea cea mai rezistentă a operei sale poetice este volumul Pasteluri, scris între 1867 și 1869, în care natura este prezentată în toate anotimpurile.", "examples": ["Pasteluri", "Despot-Vodă"], "important": false}, {"term": "Textul descriptiv în versuri", "kind": "definition", "text": "Textul descriptiv literar poate fi scris în versuri sau în proză. Textul descriptiv în versuri se organizează în funcție de:\n- formă, care valorifică sonorități și ritmuri, ca în muzică, pentru a determina cititorul să-și imagineze obiectul descris;\n- conținut, care transmite idei, sentimente și emoții referitoare la obiectul descris prin intermediul imaginilor vizuale, sonore, olfactive, tactile.", "examples": [], "important": true}], "flashcards": [{"front": "Cum este supranumit Vasile Alecsandri?", "back": "„Bardul de la Mircești”, după numele moșiei sale.", "n": [0]}, {"front": "Cum poate fi scris textul descriptiv literar?", "back": "În versuri sau în proză.", "n": [1]}, {"front": "După ce se organizează textul descriptiv în versuri?", "back": "După formă (sonorități, ritmuri) și după conținut (idei, sentimente, emoții).", "n": [1]}, {"front": "Ce tipuri de imagini transmit conținutul unei descrieri în versuri?", "back": "Imagini vizuale, sonore, olfactive, tactile.", "n": [1]}, {"front": "Care este cea mai rezistentă parte a operei poetice a lui Alecsandri?", "back": "Volumul Pasteluri (1867-1869).", "n": [0]}], "quiz": [{"type": "mcq", "q": "Care este volumul de poezii al lui Vasile Alecsandri în care natura apare în toate anotimpurile?", "options": ["Doine", "Pasteluri", "Legende", "Lăcrămioare"], "answer": 1, "why": "Pasteluri a fost scris între 1867 și 1869.", "n": [0]}, {"type": "tf", "q": "Textul descriptiv literar poate fi scris doar în versuri.", "answer": false, "why": "Poate fi scris în versuri sau în proză.", "n": [1]}, {"type": "fill", "q": "Textul descriptiv în versuri se organizează în funcție de formă și de ____.", "answers": ["conținut", "continut"], "why": "Forma valorifică sonorități și ritmuri, conținutul transmite idei și sentimente.", "n": [1]}, {"type": "mcq", "q": "Ce valorifică forma unui text descriptiv în versuri?", "options": ["Doar cuvinte rare", "Sonorități și ritmuri, ca în muzică", "Doar rima", "Fapte reale verificabile"], "answer": 1, "why": "Forma valorifică sonorități și ritmuri pentru a-l face pe cititor să-și imagineze obiectul descris.", "n": [1]}, {"type": "match", "q": "Potrivește opera cu categoria ei.", "pairs": [["Pasteluri", "poezii despre natură"], ["Despot-Vodă", "piesă cu subiect istoric"], ["Doine", "volum cu folclor valorificat"]], "n": [0]}, {"type": "classify", "q": "Încadrează elementele după cum țin de formă sau de conținut.", "categories": ["Formă", "Conținut"], "items": [{"t": "ritmul", "c": 0}, {"t": "sonoritățile", "c": 0}, {"t": "sentimentele transmise", "c": 1}, {"t": "imaginile vizuale", "c": 1}], "n": [1]}]}, {"id": "u3-l2", "number": 2, "title": "Descrierea în versuri", "section": "Lectură", "pages": "p. 86-87", "source": "Iarna - Vasile Alecsandri", "theory": [{"term": "Textul descriptiv literar", "kind": "definition", "text": "Textul descriptiv literar constă în prezentarea sugestivă a elementelor componente și a proprietăților particulare ale unui obiect, ale unei ființe, ale spațiului fizic.", "examples": [], "important": true}, {"term": "Elemente componente și relațiile obiectului descris", "kind": "rule", "text": "Părțile componente pot avea, la rândul lor, alte elemente componente, cu alte proprietăți.\nObiectul descris poate fi pus în relație cu:\n- alte obiecte din spațiul în care este situat;\n- timpul, momentul în care este observat.", "examples": ["obiectul descris: peisaj de iarnă; element component: câmp; proprietate: alb"], "important": true}, {"term": "Tabloul", "kind": "definition", "text": "Tabloul este o formă a descrierii ce înfățișează un aspect din natură, un interior sau scene din viața de zi cu zi, folosindu-se o imagine în care ansamblul este cuprins dintr-o privire.", "examples": [], "important": true}, {"term": "Pastelul", "kind": "definition", "text": "Există texte literare în versuri care descriu aspecte din natură sau interioare și în care sunt transmise, în același timp, sentimentele sau stările privitorului. Aceste texte descriptive literare seamănă cu tablourile realizate în artele plastice cu niște creioane colorate moi, care produc efecte de culoare inedite și care se numesc pasteluri. Plecând de la această asemănare, Vasile Alecsandri a denumit aceste poezii pasteluri.", "examples": [], "important": false}, {"term": "Tabloul literar", "kind": "definition", "text": "Tabloul literar seamănă cu o fotografie sau cu o pictură, alcătuind o imagine cu semnificație unitară, așa cum sunt cele două părți ale textului Iarna de Vasile Alecsandri: iarna înfricoșătoare (primele trei strofe) și iarna veselă (ultima strofă).", "examples": ["iarna înfricoșătoare (strofele 1-3)", "iarna veselă (ultima strofă)"], "important": true}], "flashcards": [{"front": "Ce este textul descriptiv literar?", "back": "Prezentarea sugestivă a elementelor componente și a proprietăților particulare ale unui obiect, ale unei ființe, ale spațiului fizic.", "n": [0]}, {"front": "Ce este tabloul (ca formă a descrierii)?", "back": "O formă a descrierii ce înfățișează un aspect din natură, un interior sau scene din viața de zi cu zi, într-o imagine cuprinsă dintr-o privire.", "n": [2]}, {"front": "Cu ce poate fi pus în relație obiectul descris?", "back": "Cu alte obiecte din spațiul în care este situat și cu timpul, momentul în care este observat.", "n": [1]}, {"front": "De ce a numit Alecsandri poeziile sale pasteluri?", "back": "Fiindcă seamănă cu tablourile din artele plastice făcute cu creioane colorate moi (pastel).", "n": [3]}, {"front": "Care sunt cele două tablouri din poezia Iarna?", "back": "Iarna înfricoșătoare (strofele 1-3) și iarna veselă (ultima strofă).", "n": [4]}, {"front": "Pot elementele componente să aibă la rândul lor alte elemente?", "back": "Da, cu alte proprietăți.", "n": [1]}], "quiz": [{"type": "mcq", "q": "Ce este tabloul?", "options": ["O poezie fără rimă", "O formă a descrierii în care ansamblul este cuprins dintr-o privire", "O formă a narațiunii", "Un text informativ"], "answer": 1, "why": "Tabloul înfățișează un aspect din natură, un interior sau scene din viața de zi cu zi.", "n": [2]}, {"type": "tf", "q": "Obiectul descris poate fi pus în relație cu timpul în care este observat.", "answer": true, "why": "Obiectul se poate raporta la alte obiecte din spațiu și la momentul observării.", "n": [1]}, {"type": "fill", "q": "Poeziile descriptive ale lui Alecsandri se numesc ____.", "answers": ["pasteluri", "pastel"], "why": "Numele vine de la asemănarea cu tablourile în creioane colorate moi.", "n": [3]}, {"type": "mcq", "q": "Cum sunt cele două părți ale poeziei Iarna, conform Reperelor?", "options": ["Iarna veselă și vara fierbinte", "Iarna înfricoșătoare (strofele 1-3) și iarna veselă (ultima strofă)", "Ziua și noaptea", "Satul și orașul"], "answer": 1, "why": "Tabloul literar are semnificație unitară, în două părți.", "n": [4]}, {"type": "tf", "q": "În pasteluri se transmit, în același timp cu descrierea, sentimentele sau stările privitorului.", "answer": true, "why": "Aceasta este caracteristica textelor numite pasteluri.", "n": [3]}, {"type": "match", "q": "Potrivește termenul cu explicația.", "pairs": [["Element component", "parte a obiectului descris"], ["Proprietate", "însușire a elementului (ex. alb)"], ["Obiectul descris", "ex. peisaj de iarnă"], ["Tablou", "imagine cuprinsă dintr-o privire"]], "n": [1, 2]}]}, {"id": "u3-l3", "number": 3, "title": "Epitetul. Versificația", "section": "Lectură", "pages": "p. 88-90", "source": "Iarna - Vasile Alecsandri", "theory": [{"term": "Figurile de stil", "kind": "definition", "text": "Figurile de stil sunt procedee utilizate cu rolul de a da expresivitate textului literar. Acestea exprimă un complex de semnificații ce trebuie descoperit prin lectură de către cititor, care le raportează la context și la propria experiență culturală și de viață. Pentru descifrarea textului, nu este suficientă identificarea figurilor de stil, fiind necesar să li se dea un sens în relație cu ansamblul textului în care apar.\nÎntr-un text descriptiv, figurile de stil conturează în mod original elementul descris.", "examples": [], "important": true}, {"term": "Epitetul", "kind": "definition", "text": "Epitetul este figura de stil care constă în determinarea unui substantiv sau a unui verb prin cuvinte ce evidențiază însușiri deosebite ale obiectului sau ale acțiunii.", "examples": ["sanie ușoară", "voios răsună"], "important": true}, {"term": "Ce poate determina epitetul", "kind": "classification", "text": "Epitetul poate determina:\n- un substantiv; de exemplu: „sanie ușoară” (epitet exprimat prin adjectiv), „fiori de gheață” (epitet exprimat prin substantiv ce indică nume de metale prețioase, pietre prețioase, materii etc.);\n- un verb; de exemplu: „voios răsună”.", "examples": ["sanie ușoară", "fiori de gheață", "voios răsună"], "important": true}, {"term": "Epitetul cromatic și epitetul personificator", "kind": "definition", "text": "Când se referă la culoare, epitetul se numește epitet cromatic („umeri dalbi”).\nEpitetul se poate combina cu alte figuri de stil, existând epitet personificator („mândra țară”).", "examples": ["umeri dalbi", "mândra țară"], "important": true}, {"term": "Epitetul după numărul de termeni", "kind": "classification", "text": "După numărul de termeni, epitetul poate fi:\n- simplu: „clăbuci albii”;\n- dublu: „soarele rotund și palid”;\n- triplu: „pe câmpia înălbită, netedă, strălucitoare” (Vasile Alecsandri, Sania);\n- în cumul: „Rece, fragilă, nouă, virginală, / Lumina duce omenirea-n poală.” (Tudor Arghezi, Vânt de toamnă).", "examples": ["clăbuci albii", "soarele rotund și palid", "câmpia înălbită, netedă, strălucitoare"], "important": true}, {"term": "Versificația (prozodia)", "kind": "definition", "text": "Versificația sau prozodia se ocupă cu regulile de construcție a poeziei, care este o formă specială de exprimare, caracterizată prin folosirea armonioasă a sunetelor.", "examples": [], "important": true}, {"term": "Versul și măsura", "kind": "definition", "text": "Versul este un rând dintr-o poezie. Măsura reprezintă numărul de silabe dintr-un vers.\nMăsura poate fi variabilă, existând versuri scurte (de 5-6 sau 7-8 silabe) și versuri lungi (de 12-18 silabe). Măsura poate fi constantă în toată poezia sau poate varia.", "examples": [], "important": true}, {"term": "Strofa", "kind": "definition", "text": "Strofa este o grupare de versuri, în număr variabil, despărțită de alte asemenea unități printr-un rând alb.", "examples": [], "important": true}, {"term": "Rima", "kind": "definition", "text": "Rima constă în potrivirea sunetelor de la sfârșit de vers, începând cu ultima vocală accentuată.", "examples": [], "important": true}, {"term": "Tipuri de rimă în catren", "kind": "classification", "text": "Într-un catren (strofă alcătuită din patru versuri), poate exista:\n- rimă împerecheată, când primul vers rimează cu al doilea și al treilea cu al patrulea (a a b b);\n- rimă încrucișată, când primul vers rimează cu al treilea și al doilea cu al patrulea (a b a b);\n- rimă îmbrățișată, când primul vers rimează cu al patrulea și al doilea cu al treilea (a b b a);\n- monorimă, când toate versurile rimează (a a a a).", "examples": ["a a b b", "a b a b", "a b b a", "a a a a"], "important": true}, {"term": "Ritmul", "kind": "definition", "text": "Ritmul constă în succesiunea regulată și armonioasă a silabelor accentuate și neaccentuate dintr-un vers. Prin repetiția ordonată a accentelor, versurile se aseamănă cu muzica.", "examples": [], "important": true}, {"term": "Versuri albe", "kind": "definition", "text": "Când versurile nu rimează, dar au ritm și măsură, se spune despre acestea că sunt albe.", "examples": [], "important": true}], "flashcards": [{"front": "Ce sunt figurile de stil?", "back": "Procedee utilizate cu rolul de a da expresivitate textului literar.", "n": [0]}, {"front": "Ce este epitetul?", "back": "Figura de stil care determină un substantiv sau un verb prin cuvinte ce evidențiază însușiri deosebite ale obiectului sau ale acțiunii.", "n": [1]}, {"front": "Ce este epitetul cromatic?", "back": "Epitetul care se referă la culoare (umeri dalbi).", "n": [3]}, {"front": "Ce este epitetul personificator?", "back": "Epitetul combinat cu personificarea (mândra țară).", "n": [3]}, {"front": "Tipurile de epitet după numărul de termeni", "back": "Simplu, dublu, triplu, în cumul.", "n": [4]}, {"front": "Ce este măsura unui vers?", "back": "Numărul de silabe din vers.", "n": [6]}, {"front": "Ce este rima?", "back": "Potrivirea sunetelor de la sfârșit de vers, începând cu ultima vocală accentuată.", "n": [8]}, {"front": "Rimă încrucișată", "back": "Primul vers cu al treilea, al doilea cu al patrulea (a b a b).", "n": [9]}, {"front": "Rimă îmbrățișată", "back": "Primul vers cu al patrulea, al doilea cu al treilea (a b b a).", "n": [9]}, {"front": "Ce sunt versurile albe?", "back": "Versurile care nu rimează, dar au ritm și măsură.", "n": [11]}], "quiz": [{"type": "mcq", "q": "Ce tip de epitet este „soarele rotund și palid”?", "options": ["simplu", "dublu", "triplu", "în cumul"], "answer": 1, "why": "Soarele este determinat de doi termeni: rotund și palid.", "n": [4]}, {"type": "mcq", "q": "Ce tip de rimă are un catren cu schema a b b a?", "options": ["împerecheată", "încrucișată", "îmbrățișată", "monorimă"], "answer": 2, "why": "Primul vers rimează cu al patrulea și al doilea cu al treilea.", "n": [9]}, {"type": "tf", "q": "„Umeri dalbi” este un epitet cromatic.", "answer": true, "why": "Epitetul se referă la culoare (alb).", "n": [3]}, {"type": "tf", "q": "Epitetul poate determina doar substantive, nu și verbe.", "answer": false, "why": "Poate determina și un verb: „voios răsună”.", "n": [2]}, {"type": "fill", "q": "Numărul de silabe dintr-un vers se numește ____.", "answers": ["măsură", "masura"], "why": "Măsura poate fi constantă sau variabilă.", "n": [6]}, {"type": "fill", "q": "Strofa alcătuită din patru versuri se numește ____.", "answers": ["catren"], "why": "Catrenul este strofa de patru versuri.", "n": [9]}, {"type": "match", "q": "Potrivește schema rimei cu denumirea.", "pairs": [["a a b b", "rimă împerecheată"], ["a b a b", "rimă încrucișată"], ["a b b a", "rimă îmbrățișată"], ["a a a a", "monorimă"]], "n": [9]}, {"type": "classify", "q": "Încadrează epitetele după felul lor.", "categories": ["Epitet exprimat prin adjectiv", "Epitet exprimat prin substantiv"], "items": [{"t": "sanie ușoară", "c": 0}, {"t": "fiori de gheață", "c": 1}, {"t": "umeri dalbi", "c": 0}, {"t": "mândra țară", "c": 0}], "n": [2]}, {"type": "mcq", "q": "Cum se numesc versurile fără rimă, dar cu ritm și măsură?", "options": ["libere", "albe", "lungi", "monorime"], "answer": 1, "why": "Versurile care nu rimează, dar au ritm și măsură, sunt albe.", "n": [11]}, {"type": "mcq", "q": "Cu ce se ocupă versificația (prozodia)?", "options": ["Cu regulile de construcție a poeziei", "Cu regulile de scriere a prozei", "Cu analiza părților de vorbire", "Cu povestirea întâmplărilor"], "answer": 0, "why": "Versificația sau prozodia se ocupă cu regulile de construcție a poeziei.", "n": [5]}, {"type": "fill", "q": "O grupare de versuri, despărțită de alte asemenea unități printr-un rând alb, se numește ____.", "answers": ["strofă", "strofa"], "why": "Strofa este o grupare de versuri, în număr variabil, despărțită prin rând alb.", "n": [7]}, {"type": "tf", "q": "Ritmul constă în succesiunea regulată și armonioasă a silabelor accentuate și neaccentuate dintr-un vers.", "answer": true, "why": "Aceasta este definiția ritmului; prin repetiția ordonată a accentelor, versurile se aseamănă cu muzica.", "n": [10]}]}, {"id": "u3-l4", "number": 4, "title": "Semnificațiile textului", "section": "Lectură", "pages": "p. 91", "source": "Iarna - Vasile Alecsandri", "theory": [], "flashcards": [], "quiz": []}, {"id": "u3-l5", "number": 5, "title": "Textul nonliterar", "section": "Lectură", "pages": "p. 92-94", "source": "Buletin meteorologic (ANM); Mormane de zăpadă toxică pe străzile orașului (știre)", "theory": [{"term": "Textul nonliterar", "kind": "definition", "text": "Textul nonliterar se referă la aspecte din realitate, utilizând mai ales cuvinte cu sens propriu, uneori chiar termeni de specialitate.", "examples": [], "important": true}, {"term": "Buletinul meteorologic", "kind": "definition", "text": "Buletinul meteorologic este un text nonliterar prin care se transmit informații despre starea vremii, fiind, adeseori, însoțit de hărți. Vinietele și cuvintele care le însoțesc alcătuiesc legenda hărții meteorologice.", "examples": [], "important": true}, {"term": "Modalitatea de comunicare a buletinului meteo", "kind": "classification", "text": "În funcție de modalitatea de comunicare, buletinul meteorologic poate fi:\n- text monomodal, dacă este folosit doar codul lingvistic;\n- text multimodal simplu, dacă este însoțit de hartă, fiindcă se combină cuvintele cu imaginile;\n- text multimodal complex, în cazul buletinului meteo de la emisiunile de televiziune sau din site-urile web, pentru că se folosesc și animații pentru a observa circulația curenților de aer, în această situație apărând, pe lângă codul lingvistic și vizual, codul spațial.", "examples": [], "important": true}, {"term": "Lectura unei previziuni meteorologice", "kind": "rule", "text": "Lectura unei previziuni meteorologice trebuie să aibă în vedere găsirea pe hartă a localității vizate, descifrarea vinietei din dreptul localității și identificarea temperaturii minime și maxime.", "examples": [], "important": true}, {"term": "Știrea", "kind": "definition", "text": "Știrea este un articol scurt care informează cititorii despre un aspect din realitate, răspunzând la întrebările cine?, ce?, unde?, când?, de ce?. Știrea din presa scrisă poate deveni din text monomodal unul multimodal, când este însoțită de fotografii sau grafice. Știrile televizate însoțite de secvențe filmate intră în rândul textelor multimodale.", "examples": [], "important": true}, {"term": "Titlul", "kind": "classification", "text": "Titlul urmărește să atragă atenția cititorilor, putând fi:\n- verbal, când conține un predicat (de exemplu: Poluarea atentează la sănătatea oamenilor);\n- nominal, când nu conține un predicat (de exemplu: Atentat la sănătatea oamenilor).", "examples": ["Poluarea atentează la sănătatea oamenilor (verbal)", "Atentat la sănătatea oamenilor (nominal)"], "important": true}, {"term": "Supratitlul", "kind": "definition", "text": "Supratitlul are rolul de a rezuma conținutul știrii. Atât titlul, cât și supratitlul atrag atenția prin mărimea corpului de literă, prin culoare și tip (îngroșat, de regulă).", "examples": [], "important": true}, {"term": "Timpurile verbale într-o știre", "kind": "rule", "text": "Într-o știre, timpurile verbale folosite sunt prezentul, perfectul compus și, uneori, imperfectul.", "examples": [], "important": true}, {"term": "Structura știrii (piramida inversată)", "kind": "classification", "text": "O știre are trei părți, care alcătuiesc o piramidă inversată:\n- începutul (numit lead, atac sau prim paragraf) este scurt, sintetizează informația și stârnește interesul cititorului;\n- cuprinsul (corpul știrii) conține date care explică și aprofundează informațiile, aducând o serie de detalii ce întregesc imaginea evenimentului prezentat;\n- încheierea (finalul) fixează evenimentul în mintea cititorului.\nPrimul paragraf răspunde la întrebările: Cine?, Ce?, Unde?, Când?, De ce?", "examples": [], "important": true}, {"term": "Instrumente meteorologice (exercițiu)", "kind": "tip", "text": "Vremea depinde zilnic de presiunea atmosferică, de temperatura aerului, de viteza și direcția vântului și de cantitatea precipitațiilor. Instrumentele asociate: termometru, giruetă, pluviometru, barometru.", "examples": ["termometru", "giruetă", "pluviometru", "barometru"], "important": false, "derived": true}], "flashcards": [{"front": "Ce este textul nonliterar?", "back": "Text care se referă la aspecte din realitate, cu cuvinte cu sens propriu și uneori termeni de specialitate.", "n": [0]}, {"front": "Ce este buletinul meteorologic?", "back": "Text nonliterar prin care se transmit informații despre starea vremii, adesea însoțit de hărți.", "n": [1]}, {"front": "Ce alcătuiește legenda hărții meteorologice?", "back": "Vinietele și cuvintele care le însoțesc.", "n": [1]}, {"front": "Text monomodal / multimodal simplu / multimodal complex", "back": "Doar cod lingvistic / cuvinte + imagini (hartă) / cod lingvistic + vizual + spațial (animații la TV, site-uri).", "n": [2]}, {"front": "La ce întrebări răspunde o știre?", "back": "Cine?, ce?, unde?, când?, de ce?", "n": [4]}, {"front": "Titlu verbal vs. nominal", "back": "Verbal conține un predicat; nominal nu conține predicat.", "n": [5]}, {"front": "Rolul supratitlului", "back": "Rezumă conținutul știrii.", "n": [6]}, {"front": "Timpurile verbale dintr-o știre", "back": "Prezent, perfect compus și uneori imperfect.", "n": [7]}, {"front": "Cele trei părți ale știrii", "back": "Începutul (lead), cuprinsul, încheierea - piramida inversată.", "n": [8]}, {"front": "Cu ce măsori: temperatura, ploaia, presiunea, direcția vântului?", "back": "Termometru, pluviometru, barometru, giruetă.", "n": [9]}], "quiz": [{"type": "mcq", "q": "Un buletin meteo însoțit de o hartă este un text:", "options": ["monomodal", "multimodal simplu", "multimodal complex", "literar"], "answer": 1, "why": "Se combină cuvintele cu imaginile.", "n": [2]}, {"type": "mcq", "q": "Buletinul meteo de la televizor, cu animații ale curenților de aer, este un text:", "options": ["multimodal complex", "monomodal", "multimodal simplu", "narativ"], "answer": 0, "why": "Apare și codul spațial, pe lângă cel lingvistic și vizual.", "n": [2]}, {"type": "tf", "q": "Titlul „Atentat la sănătatea oamenilor” este un titlu verbal.", "answer": false, "why": "Nu conține predicat, deci este nominal.", "n": [5]}, {"type": "tf", "q": "Începutul știrii răspunde la întrebările Cine?, Ce?, Unde?, Când?, De ce?.", "answer": true, "why": "Primul paragraf (lead) sintetizează informația esențială.", "n": [8]}, {"type": "fill", "q": "Într-o știre se folosesc timpurile prezent, perfect compus și, uneori, ____.", "answers": ["imperfect", "imperfectul"], "why": "Acestea sunt timpurile verbale ale știrii.", "n": [7]}, {"type": "fill", "q": "Titlul care conține un predicat se numește titlu ____.", "answers": ["verbal"], "why": "Titlul fără predicat este nominal.", "n": [5]}, {"type": "match", "q": "Potrivește instrumentul cu ce măsoară.", "pairs": [["termometru", "temperatura aerului"], ["pluviometru", "cantitatea precipitațiilor"], ["barometru", "presiunea atmosferică"], ["giruetă", "direcția vântului"]], "n": [9]}, {"type": "classify", "q": "Încadrează după felul titlului.", "categories": ["Titlu verbal", "Titlu nominal"], "items": [{"t": "Poluarea atentează la sănătatea oamenilor", "c": 0}, {"t": "Atentat la sănătatea oamenilor", "c": 1}, {"t": "Încălzirea planetei din cauza poluării", "c": 1}, {"t": "Poluarea produce încălzirea planetei", "c": 0}], "n": [5]}, {"type": "mcq", "q": "Care este rolul supratitlului?", "options": ["Să încheie știrea", "Să rezume conținutul știrii", "Să arate autorul", "Să indice ora"], "answer": 1, "why": "Supratitlul rezumă conținutul, la fel ca titlul atrage atenția prin literă mai mare, culoare, îngroșare.", "n": [6]}, {"type": "tf", "q": "La lectura unei previziuni meteorologice trebuie să găsești pe hartă localitatea vizată, să descifrezi vinieta din dreptul ei și să identifici temperatura minimă și maximă.", "answer": true, "why": "Aceasta este regula de lectură a unei previziuni meteorologice.", "n": [3]}]}, {"id": "u3-l6", "number": 6, "title": "Noi pagini - alte idei", "section": "Lectură", "pages": "p. 95", "source": "Greutatea omătului - Ana Blandiana", "theory": [{"term": "Relația om-natură în poezia românească", "kind": "tip", "text": "Abordarea relației om-natură în poezia românească de la 1848 și-a avut rădăcinile în folclor și a continuat să se manifeste până în literatura contemporană. În secolul al XX-lea, poeți ca Ion Pillat, George Bacovia, Lucian Blaga au renunțat la înfățișarea picturală a naturii, preferând să-și prezinte trăirile proiectate asupra ei. Astfel, a dispărut poezia descriptivă în care tabloul exterior influența starea sufletească a omului, ca la Vasile Alecsandri, George Coșbuc, Șt. O. Iosif sau Octavian Goga. Scriitorii contemporani construiesc natura exterioară după propria individualitate.", "examples": ["Ana Blandiana, Greutatea omătului (volumul Stea de pradă, 1985)"], "important": false}], "flashcards": [{"front": "Cine a renunțat în sec. XX la înfățișarea picturală a naturii?", "back": "Poeți ca Ion Pillat, George Bacovia, Lucian Blaga.", "n": [0]}, {"front": "Care poeți au scris poezie descriptivă în care tabloul exterior influența starea sufletească?", "back": "Vasile Alecsandri, George Coșbuc, Șt. O. Iosif, Octavian Goga.", "n": [0]}, {"front": "În ce volum apare Greutatea omătului?", "back": "Stea de pradă (1985), de Ana Blandiana.", "n": [0]}], "quiz": [{"type": "tf", "q": "Poeții din secolul al XX-lea ca Pillat, Bacovia și Blaga și-au proiectat trăirile asupra naturii.", "answer": true, "why": "Au renunțat la înfățișarea picturală a naturii.", "n": [0]}, {"type": "mcq", "q": "Cine a scris poezia Greutatea omătului?", "options": ["Vasile Alecsandri", "Ana Blandiana", "George Coșbuc", "Octavian Goga"], "answer": 1, "why": "Poezia este din volumul Stea de pradă (1985).", "n": [0]}, {"type": "fill", "q": "Abordarea relației om-natură în poezia românească de la 1848 și-a avut rădăcinile în ____.", "answers": ["folclor"], "why": "Tradiția a continuat până în literatura contemporană.", "n": [0]}, {"type": "match", "q": "Potrivește poetul cu tipul de abordare.", "pairs": [["Vasile Alecsandri", "tablou exterior care influențează starea sufletească"], ["Lucian Blaga", "trăiri proiectate asupra naturii"], ["Ana Blandiana", "natură construită după propria individualitate"]], "n": [0]}, {"type": "tf", "q": "Scriitorii contemporani construiesc natura exterioară după propria individualitate.", "answer": true, "why": "Așa cum se vede în poezia Anei Blandiana.", "n": [0]}]}, {"id": "u3-l7", "number": 7, "title": "Bradul în cultura populară românească", "section": "Interculturalitate", "pages": "p. 96-97", "source": "Texte informative despre simbolul bradului", "theory": [{"term": "Riturile de trecere", "kind": "definition", "text": "Momentele capitale din viața omului, numite rituri de trecere, fiindcă surprind tranziția de la o stare la alta (nașterea, nunta, moartea).", "examples": ["naștere", "nuntă", "moarte"], "important": false}, {"term": "Bradul în riturile de trecere", "kind": "tip", "text": "La naștere, bradul se dăruiește simbolic copilului pentru a-l păzi de duhurile rele (pe scoarța lui se scrie numele copilului). La nuntă, bradul este împodobit și dus de un flăcău la casa miresei, cu un mesaj în versuri numit orația bradului; după cununie este pus în poarta casei tinerilor pentru a-i ocroti. La moartea unui tânăr necăsătorit, se taie un brad pus la căpătâiul celui mort (dublu vegetal al sufletului); cântecul bradului prezintă povestea doborârii copacului.", "examples": ["orația bradului", "cântecul bradului"], "important": false}, {"term": "Simbolistica bradului", "kind": "definition", "text": "Bradul, prin calitatea sa de a rămâne verde în orice anotimp, este un simbol al vieții eterne, al prosperității și al fertilității. În spațiul românesc are o simbolistică aparte, probabil venită de la geto-daci, pentru care era un arbore magic, cu puterea de a lega toate nivelurile universului:\n- subteranul, ce reprezintă lumea nevăzută, fiindcă rădăcinile sale sunt înfipte în pământ;\n- suprafața terestră, zona vieții umane obișnuite;\n- cerul, considerat lumea soarelui, la care urcau sufletele străbunilor ca să reînvie, crengile bradului fiind un fel de scară.", "examples": [], "important": true}, {"term": "Bradul - drum ascensional", "kind": "tip", "text": "Prin verticalitatea lui, bradul reprezintă un drum ascensional spre veșnicie, ajutând la comunicarea dintre lumea subterană, cea terestră și cea celestă. Ocrotește viața omului și îi îndepărtează teama de moarte. Prin forma sa, bradul a intrat în mentalitatea creștină ca un simbol al Sfintei Treimi. Tămâia, care este o rășină, reprezintă un element purificator și ocrotitor.", "examples": [], "important": false}, {"term": "Apariția bradului în riturile românești", "kind": "tip", "text": "Apariția bradului în toate riturile de trecere românești le individualizează în spațiul european, fiindcă este un sprijin al tânărului în inițierea sa, ajutându-l să-și dovedească puterea, inteligența și curajul. Atribuirea de puteri ocrotitoare crenguțelor de brad este preluată de la romani (ramuri de brad la coama unei case în construcție, la hățurile cailor, la căruțele ce transportă lemne). Imaginea bradului apare stilizată pe covoare, ștergare, ii, cojoace, lăzi etc.", "examples": ["ia românească", "covoare", "ștergare"], "important": false}, {"term": "Bradul de Crăciun", "kind": "tip", "text": "Împodobirea bradului de Crăciun este un obicei de origine germană, răspândit în Europa în a doua parte a secolului al XIX-lea, mai ales în mediile urbane. Primul brad românesc celebru a fost împodobit la curtea regelui Carol I, datina existând însă dinainte în satele de sași din Transilvania.", "examples": [], "important": false}], "flashcards": [{"front": "Ce sunt riturile de trecere?", "back": "Momentele capitale din viața omului (naștere, nuntă, moarte), care surprind tranziția de la o stare la alta.", "n": [0]}, {"front": "Ce simbolizează bradul prin faptul că rămâne verde tot anul?", "back": "Viața eternă, prosperitatea, fertilitatea.", "n": [2]}, {"front": "Ce trei niveluri ale universului leagă bradul?", "back": "Subteranul, suprafața terestră, cerul.", "n": [2]}, {"front": "Ce este orația bradului?", "back": "Poezia prin care un flăcău transmite miresei mesajul mirelui, la nuntă.", "n": [1]}, {"front": "Ce simbol creștin reprezintă forma bradului?", "back": "Sfânta Treime.", "n": [3]}, {"front": "De unde vine obiceiul bradului de Crăciun?", "back": "Este de origine germană, răspândit în Europa în a doua parte a sec. al XIX-lea.", "n": [5]}, {"front": "De la cine e preluată atribuirea de puteri ocrotitoare crenguțelor de brad?", "back": "De la romani.", "n": [4]}], "quiz": [{"type": "mcq", "q": "Ce reprezintă rădăcinile bradului în simbolistica geto-dacă?", "options": ["Cerul", "Lumea nevăzută, subteranul", "Viața umană obișnuită", "Soarele"], "answer": 1, "why": "Subteranul reprezintă lumea nevăzută, fiindcă rădăcinile sunt înfipte în pământ.", "n": [2]}, {"type": "tf", "q": "Bradul de Crăciun este un obicei de origine germană.", "answer": true, "why": "S-a răspândit în Europa în a doua parte a secolului al XIX-lea.", "n": [5]}, {"type": "tf", "q": "Orația bradului se rostește la naștere.", "answer": false, "why": "Apare la nuntă, când bradul e dus la casa miresei.", "n": [1]}, {"type": "fill", "q": "Momentele capitale din viața omului se numesc rituri de ____.", "answers": ["trecere"], "why": "Ele surprind tranziția de la o stare la alta.", "n": [0]}, {"type": "mcq", "q": "Ce simbolizează bradul, prin calitatea de a rămâne verde în orice anotimp?", "options": ["moartea și tăcerea", "viața eternă, prosperitatea, fertilitatea", "războiul", "sărăcia"], "answer": 1, "why": "Este definiția simbolului din text.", "n": [2]}, {"type": "match", "q": "Potrivește nivelul universului cu semnificația.", "pairs": [["subteran", "lumea nevăzută"], ["suprafața terestră", "zona vieții umane obișnuite"], ["cer", "lumea soarelui"]], "n": [2]}, {"type": "classify", "q": "Încadrează riturile de trecere după rolul bradului.", "categories": ["Brad pus în poarta casei tinerilor", "Brad dăruit simbolic copilului"], "items": [{"t": "nuntă", "c": 0}, {"t": "naștere", "c": 1}], "n": [1]}]}, {"id": "u3-l8", "number": 8, "title": "Strategii de ascultare activă. Atitudini comunicative", "section": "Comunicare orală", "pages": "p. 100-101", "source": "", "theory": [{"term": "Ascultarea activă", "kind": "definition", "text": "Ascultarea activă este practica de a asculta un vorbitor și de a oferi feedback, așa încât ascultătorul să dovedească vorbitorului că a auzit și a înțeles mesajul acestuia prin următoarele comportamente:\n- este atent la ceea ce spune vorbitorul, fără a se lăsa distras de mediu sau de propriile gânduri și probleme, îl încurajează să vorbească (Te ascult …; Spune … etc.);\n- emite semnale nonverbale de interes (contact vizual, încuviințare din cap, zâmbet, postură asemănătoare interlocutorului etc.);\n- adresează întrebări de clarificare (Ce înțelegi prin …?; Vrei să spui că …? etc.);\n- reformulează (Dacă înțeleg bine, …; Ceea ce dorești, de fapt, este … etc.);\n- reflectă sentimentele vorbitorului și-l ajută să le exprime (Îmi imaginez că asta te-a supărat/întristat/neliniștit/bucurat.; Înțeleg că te simți … etc.).", "examples": ["Te ascult …", "Ce înțelegi prin …?", "Dacă înțeleg bine, …", "Înțeleg că te simți …"], "important": true}, {"term": "Atitudini comunicative", "kind": "definition", "text": "O bună comunicare cu ceilalți presupune nu doar respectarea unor reguli referitoare la claritatea și corectitudinea exprimării, ci și anumite atitudini comunicative: interesul pentru alte opinii, atenția manifestată în raport cu ceilalți, implicarea în conversație și cooperarea în activitățile de grup.", "examples": [], "important": true}, {"term": "Ce nu faci și ce faci când asculți activ", "kind": "tip", "text": "Schema din manual: ascultă cu atenție, arată-ți interesul, pune întrebări, dovedește empatie, ascultă cu răbdare, fii calm/calmă; nu judeca, nu întrerupe.", "examples": ["nu întrerupe", "nu judeca", "dovedește empatie"], "important": false}], "flashcards": [{"front": "Ce este ascultarea activă?", "back": "Practica de a asculta un vorbitor și de a oferi feedback, dovedind că ai auzit și ai înțeles mesajul.", "n": [0]}, {"front": "Semnale nonverbale de interes ale ascultătorului", "back": "Contact vizual, încuviințare din cap, zâmbet, postură asemănătoare interlocutorului.", "n": [0]}, {"front": "Ce sunt întrebările de clarificare?", "back": "Ex.: Ce înțelegi prin …?; Vrei să spui că …?", "n": [0]}, {"front": "Ce înseamnă a reformula?", "back": "Ex.: Dacă înțeleg bine, …; Ceea ce dorești, de fapt, este …", "n": [0]}, {"front": "Cum reflecți sentimentele vorbitorului?", "back": "Ex.: Îmi imaginez că asta te-a supărat; Înțeleg că te simți …", "n": [0]}, {"front": "Care sunt atitudinile comunicative?", "back": "Interesul pentru alte opinii, atenția, implicarea în conversație, cooperarea în activitățile de grup.", "n": [1]}], "quiz": [{"type": "mcq", "q": "Care dintre acestea este o întrebare de clarificare?", "options": ["Te ascult.", "Ce înțelegi prin asta?", "Înțeleg că te simți trist.", "Dacă înțeleg bine, vrei să pleci."], "answer": 1, "why": "Întrebările de clarificare cer precizări: Ce înțelegi prin …?", "n": [0]}, {"type": "mcq", "q": "„Dacă înțeleg bine, vrei să spui că…” este un exemplu de:", "options": ["reformulare", "reflectare a sentimentelor", "semnal nonverbal", "întrerupere"], "answer": 0, "why": "Reformularea redă pe scurt ce a spus vorbitorul.", "n": [0]}, {"type": "tf", "q": "Contactul vizual este un semnal nonverbal de interes.", "answer": true, "why": "Alături de încuviințarea din cap, zâmbet, postură asemănătoare.", "n": [0]}, {"type": "tf", "q": "Un ascultător activ trebuie să-l întrerupă pe vorbitor ca să arate că înțelege.", "answer": false, "why": "Ascultarea activă presupune răbdare; ascultătorul nu întrerupe.", "n": [0]}, {"type": "fill", "q": "Interesul, atenția, implicarea și cooperarea sunt atitudini ____.", "answers": ["comunicative"], "why": "Ele fac comunicarea bună.", "n": [1]}, {"type": "match", "q": "Potrivește tehnica cu exemplul.", "pairs": [["încurajarea vorbitorului", "Spune …"], ["întrebare de clarificare", "Vrei să spui că …?"], ["reformulare", "Ceea ce dorești, de fapt, este …"], ["reflectarea sentimentelor", "Înțeleg că te simți …"]], "n": [0]}, {"type": "classify", "q": "Încadrează comportamentele.", "categories": ["Ascultare activă", "Nu este ascultare activă"], "items": [{"t": "contact vizual", "c": 0}, {"t": "întrerupi vorbitorul", "c": 1}, {"t": "pui întrebări", "c": 0}, {"t": "judeci", "c": 1}], "n": [0, 2]}]}, {"id": "u3-l9", "number": 9, "title": "Substantivul", "section": "Limbă română", "pages": "p. 102-104", "source": "", "theory": [{"term": "Substantivul", "kind": "definition", "text": "Substantivul este partea de vorbire care denumește ființe, lucruri, fenomene ale naturii, însușiri, acțiuni, stări sufletești, denumite în sens larg obiecte.", "examples": [], "important": true}, {"term": "Substantive comune și proprii", "kind": "classification", "text": "Substantivele sunt:\n- comune, când denumesc clase de obiecte de același fel;\n- proprii, când denumesc individualități (nume de persoane, țări, regiuni, localități, ape, sărbători etc.), scriindu-se cu literă mare.", "examples": ["brad (comun)", "Predeal (propriu)"], "important": true}, {"term": "Genul substantivului", "kind": "classification", "text": "Substantivele sunt de trei genuri:\n- masculin (un brad, doi brazi);\n- feminin (o sanie, două sănii);\n- neutru (un dar, două daruri).", "examples": ["un brad, doi brazi", "o sanie, două sănii", "un dar, două daruri"], "important": true}, {"term": "Numărul substantivului", "kind": "classification", "text": "Substantivele au două numere:\n- singular, când indică un obiect (cizmă);\n- plural, când indică două sau mai multe obiecte (cizme).\nExistă substantive care nu au forme diferențiate după număr (pui) și există substantive care au două forme de plural, diferențiate ca sens (elemente chimice și elemenți de calorifer).", "examples": ["cizmă - cizme", "pui", "elemente / elemenți"], "important": true}, {"term": "Articolul", "kind": "definition", "text": "Articolul reprezintă categoria gramaticală a determinării, însoțind substantivul și arătând în ce măsură obiectul denumit le este cunoscut vorbitorilor.\nSubstantivele pot fi:\n- nearticulate, când nu se oferă nicio informație cu privire la cunoașterea obiectului (brad);\n- articulate, când obiectul este cunoscut vorbitorilor (bradul, un brad).", "examples": ["brad", "bradul", "un brad"], "important": true}, {"term": "Articolul hotărât și nehotărât", "kind": "classification", "text": "Articolul este:\n- hotărât, când arată că obiectul denumit de substantiv este bine cunoscut vorbitorilor; articolul hotărât se adaugă la sfârșitul substantivului, formând împreună cu acesta o singură unitate sonoră și grafică (bradul, fata);\n- nehotărât, când arată că obiectul denumit de substantiv este mai puțin cunoscut vorbitorilor; articolul nehotărât se așază înaintea substantivului, fiind un cuvânt separat (un brad, o fată).\nSubstantivele pot fi precedate de prepoziții, iar, în acest caz, se analizează împreună.", "examples": ["bradul, fata", "un brad, o fată"], "important": true}, {"term": "Substantivele colective", "kind": "definition", "text": "Substantivele colective au la singular înțeles de plural.", "examples": ["familie", "echipă", "juriu", "grup", "mulțime", "clasă"], "important": true}, {"term": "Acordul cu substantivul colectiv subiect", "kind": "rule", "text": "Când un substantiv colectiv cu funcție sintactică de subiect se află la singular, acordul se face cu verbul predicat la singular (Clasa noastră a mers la schi.).\nCând un substantiv colectiv cu funcție sintactică de subiect este determinat de un alt substantiv la plural care indică elementele componente ale grupului, acordul cu verbul predicat se poate face fie la plural, fie la singular (O mulțime de copii a/au mers la schi.).", "examples": ["Clasa noastră a mers la schi.", "O mulțime de copii a/au mers la schi."], "important": true}, {"term": "Substantive numărabile și nonnumărabile", "kind": "classification", "text": "Substantivele sunt:\n- numărabile (elev, elevi);\n- nonnumărabile (sare).\nSubstantivele nonnumărabile sunt:\n- defective de plural (singularia tantum), adică au numai singular (oțet);\n- defective de singular (pluralia tantum), adică au numai plural (ochelari).", "examples": ["elev, elevi", "sare", "oțet", "ochelari"], "important": true}, {"term": "Substantive nume de materii", "kind": "rule", "text": "O categorie separată a substantivelor nonnumărabile sunt acelea care denumesc materii ce își păstrează caracteristicile, chiar dacă sunt fragmentate. Există diferențe de sens între Cumpăr făină. (materia) și Patiserul s-a aprovizionat cu diverse făinuri. (sortimente de făină).\nUnele substantive nonnumărabile au contexte specifice de gen, altele nu, așa încât acestea figurează în dicționare la genul neutru.", "examples": ["Cumpăr făină.", "diverse făinuri", "Cumpăr ulei.", "uleiuri rafinate"], "important": true}], "flashcards": [{"front": "Ce este substantivul?", "back": "Partea de vorbire care denumește ființe, lucruri, fenomene ale naturii, însușiri, acțiuni, stări sufletești (obiecte).", "n": [0]}, {"front": "Substantiv comun vs. propriu", "back": "Comun: denumește clase de obiecte de același fel; propriu: denumește individualități și se scrie cu literă mare.", "n": [1]}, {"front": "Cele trei genuri ale substantivului", "back": "Masculin, feminin, neutru.", "n": [2]}, {"front": "Ce este articolul?", "back": "Categoria gramaticală a determinării, care arată în ce măsură obiectul denumit este cunoscut vorbitorilor.", "n": [4]}, {"front": "Unde se așază articolul hotărât? Dar cel nehotărât?", "back": "Hotărât: la sfârșitul substantivului (bradul). Nehotărât: înaintea lui, cuvânt separat (un brad).", "n": [5]}, {"front": "Ce sunt substantivele colective?", "back": "Cele care au la singular înțeles de plural (echipă, juriu).", "n": [6]}, {"front": "Ce sunt substantivele nonnumărabile?", "back": "Cele care nu se pot număra: defective de plural (oțet) sau de singular (ochelari).", "n": [8]}, {"front": "Singularia tantum / pluralia tantum", "back": "Au numai singular (oțet) / au numai plural (ochelari).", "n": [8]}, {"front": "Ce arată pluralul unui substantiv nume de materie?", "back": "Sortimente (ex. făinuri = sortimente de făină).", "n": [9]}], "quiz": [{"type": "mcq", "q": "Care substantiv este propriu?", "options": ["munte", "Predeal", "sanie", "fular"], "answer": 1, "why": "Predeal denumește o localitate - individualitate, scrisă cu literă mare.", "n": [1]}, {"type": "mcq", "q": "Care substantiv este defectiv de singular (are numai plural)?", "options": ["oțet", "sare", "ochelari", "brad"], "answer": 2, "why": "Ochelari are numai formă de plural (pluralia tantum).", "n": [8]}, {"type": "tf", "q": "Articolul hotărât se așază înaintea substantivului.", "answer": false, "why": "Articolul hotărât se adaugă la sfârșitul substantivului (bradul); cel nehotărât se așază înaintea lui.", "n": [5]}, {"type": "tf", "q": "Substantivul colectiv are la singular înțeles de plural.", "answer": true, "why": "Ex.: echipă, juriu, grup.", "n": [6]}, {"type": "fill", "q": "Substantivul care are numai singular (ex. oțet) este defectiv de ____.", "answers": ["plural"], "why": "Se numește și singularia tantum.", "n": [8]}, {"type": "fill", "q": "Un brad este substantiv articulat cu articol ____.", "answers": ["nehotărât", "nehotarat"], "why": "Articolul nehotărât (un) se așază înaintea substantivului.", "n": [5]}, {"type": "mcq", "q": "Care este acordul corect, cu colectiv singular fără determinant la plural: „Clasa noastră ... la schi.”", "options": ["au mers", "a mers", "merg", "mergeau"], "answer": 1, "why": "Colectivul subiect la singular cere predicat la singular.", "n": [7]}, {"type": "match", "q": "Potrivește substantivul cu categoria.", "pairs": [["brad", "masculin"], ["sanie", "feminin"], ["dar", "neutru"], ["oțet", "defectiv de plural"], ["ochelari", "defectiv de singular"]], "n": [2, 8]}, {"type": "classify", "q": "Încadrează substantivele nonnumărabile.", "categories": ["Defective de plural (numai singular)", "Defective de singular (numai plural)"], "items": [{"t": "aur", "c": 0}, {"t": "tăieței", "c": 1}, {"t": "lapte", "c": 0}, {"t": "cuișoare", "c": 1}, {"t": "curaj", "c": 0}, {"t": "tărâțe", "c": 1}], "n": [8]}, {"type": "mcq", "q": "Ce arată forma de plural „făinuri”?", "options": ["materia, în general", "sortimente de făină", "o cantitate mică", "un obiect"], "answer": 1, "why": "La substantivele nume de materii, pluralul arată sortimente.", "n": [9]}, {"type": "mcq", "q": "Câte numere are substantivul?", "options": ["unul", "două", "trei", "patru"], "answer": 1, "why": "Substantivele au două numere: singular și plural.", "n": [3]}]}, {"id": "u3-l10", "number": 10, "title": "Cazul nominativ", "section": "Limbă română", "pages": "p. 105", "source": "", "theory": [{"term": "Cazul", "kind": "definition", "text": "Cazul este forma pe care o ia substantivul pentru a exprima funcția sintactică într-o propoziție.", "examples": [], "important": true}, {"term": "Cazul nominativ", "kind": "rule", "text": "Substantivul cu funcția sintactică de subiect sau de nume predicativ este în cazul nominativ.", "examples": ["Fetele au ieșit la joacă. (subiect)", "Vecina mea este patinatoare. (nume predicativ)"], "important": true}, {"term": "Articularea substantivului în nominativ", "kind": "rule", "text": "Substantivul în cazul nominativ poate fi articulat hotărât (Copiii se joacă.), articulat nehotărât (Niște fetițe râd.) sau nearticulat (Vine ger mare.). Când substantivul în nominativ este nume predicativ, cel mai frecvent este nearticulat (Tata este avocat).", "examples": ["Copiii se joacă.", "Niște fetițe râd.", "Vine ger mare.", "Tata este avocat."], "important": true}, {"term": "Model de analiză a substantivului (exercițiu)", "kind": "example", "text": "„iarna” - substantiv comun, genul feminin, numărul singular, cazul nominativ, articulat cu articolul hotărât „-a”, funcția sintactică de subiect", "examples": ["iarna"], "important": false, "derived": true}], "flashcards": [{"front": "Ce este cazul?", "back": "Forma pe care o ia substantivul pentru a exprima funcția sintactică într-o propoziție.", "n": [0]}, {"front": "Ce funcții sintactice are substantivul în nominativ?", "back": "Subiect sau nume predicativ.", "n": [1]}, {"front": "Cum este de obicei numele predicativ în nominativ?", "back": "Nearticulat (Tata este avocat).", "n": [1, 2]}, {"front": "Exemple de nominativ articulat hotărât, nehotărât, nearticulat", "back": "Copiii se joacă. / Niște fetițe râd. / Vine ger mare.", "n": [2]}], "quiz": [{"type": "mcq", "q": "În propoziția „Vântul bate tare.”, substantivul „vântul” este în cazul:", "options": ["acuzativ", "nominativ", "dativ", "genitiv"], "answer": 1, "why": "Este subiect, deci nominativ.", "n": [1]}, {"type": "tf", "q": "Numele predicativ este exprimat la cazul nominativ.", "answer": true, "why": "Subiectul și numele predicativ sunt în nominativ.", "n": [1]}, {"type": "fill", "q": "Substantivul cu funcția de subiect este în cazul ____.", "answers": ["nominativ"], "why": "Nominativ: subiect sau nume predicativ.", "n": [1]}, {"type": "mcq", "q": "În „Zăpada este o pătură strălucitoare.”, „pătură” are funcția de:", "options": ["subiect", "nume predicativ", "complement direct", "atribut"], "answer": 1, "why": "Este nume predicativ, legat de subiect prin verbul copulativ.", "n": [1]}, {"type": "classify", "q": "Funcția substantivului în nominativ (cuvântul subliniat în exemple).", "categories": ["Subiect", "Nume predicativ"], "items": [{"t": "Vântul bate tare. (vântul)", "c": 0}, {"t": "Crivățul este vântul cel mai rece. (vântul)", "c": 1}, {"t": "O rază de soare s-a strecurat. (rază)", "c": 0}, {"t": "Strada va fi un pod de gheață. (pod)", "c": 1}], "n": [1]}, {"type": "tf", "q": "Numele predicativ în nominativ este de obicei articulat hotărât.", "answer": false, "why": "Cel mai frecvent este nearticulat (Tata este avocat).", "n": [2]}]}, {"id": "u3-l11", "number": 11, "title": "Cazul acuzativ. Complementul direct. Complementul prepozițional", "section": "Limbă română", "pages": "p. 106-108", "source": "", "theory": [{"term": "Cazul acuzativ", "kind": "rule", "text": "Substantivul cu funcția sintactică de complement, precedat sau nu de prepoziție, este în cazul acuzativ.", "examples": [], "important": true}, {"term": "Complementul direct", "kind": "definition", "text": "Complementul direct este partea de propoziție care determină un verb și arată, în special, obiectul asupra căruia acționează autorul unei fapte. De exemplu: Dan colorează desenul.\nComplementul direct răspunde la întrebările pe cine?, ce?.\nSubstantivul cu funcție sintactică de complement direct stă în cazul acuzativ, cu sau fără prepoziția pe.", "examples": ["Dan colorează desenul.", "O zăresc pe Maria. (pe cine?)", "Ea plimbă câinele. (ce?)"], "important": true}, {"term": "Complementul prepozițional", "kind": "definition", "text": "Complementul prepozițional este partea de propoziție ce determină un verb și arată obiectul care este ținta acțiunii sau pentru care acționează autorul unei fapte. De exemplu: Nu se satură de cărți.\nComplementul prepozițional răspunde la întrebările: pentru cine?, pentru ce?, de cine?, de ce?, la cine?, la ce?, de la cine?, de la ce? etc.\nSubstantivul cu funcție sintactică de complement prepozițional stă în cazul acuzativ, fiind însoțit de prepoziție.", "examples": ["Nu se satură de cărți.", "Se gândește la o expoziție personală. (la ce?)", "Ea nu se plictisește de pictură. (de ce?)"], "important": true}, {"term": "Delimitarea complementului prepozițional de cel direct", "kind": "rule", "text": "Complementul prepozițional trebuie delimitat de complementul direct exprimat prin substantiv precedat de prepoziția pe. Complementul direct poate fi dublat de un pronume personal, formă neaccentuată. De exemplu: Îl ascult pe Dan., complementul direct pe Dan este dublat de îl. În propoziția Contez pe prieteni., complementul prepozițional pe prieteni nu este dublat și nici nu poate fi dublat de pronume personal, formă neaccentuată, neputându-se spune: Îi contez pe prieteni.", "examples": ["Îl ascult pe Dan. (complement direct, dublat de îl)", "Contez pe prieteni. (complement prepozițional, nu se poate dubla)"], "important": true}, {"term": "Ortografia substantivelor în nominativ și acuzativ", "kind": "norm", "text": "La nominativ și la acuzativ, substantivele au aceeași formă, existând omonimie cazuală.\nOrtografia unor substantive masculine și feminine în nominativ și în acuzativ la plural este următoarea (schema din manual: parte din cuvânt + desinență + articol hotărât):\ncopiii = copi (face parte din cuvânt) + -i (desinență) + -i (articol hotărât);  poeziile = poezi (face parte din cuvânt) + -i (desinență) + -le (articol hotărât).", "examples": ["copiii", "poeziile"], "important": true, "derived": false}, {"term": "Model de analiză: complement direct (exercițiu)", "kind": "example", "text": "„pe prietenele” - substantiv comun, genul feminin, numărul plural, cazul acuzativ, articulat cu articolul hotărât „-le”, precedat de prepoziția simplă „pe”, funcția sintactică de complement direct", "examples": [], "important": false, "derived": true}], "flashcards": [{"front": "Ce este complementul direct?", "back": "Partea de propoziție care determină un verb și arată obiectul asupra căruia acționează autorul faptei.", "n": [1]}, {"front": "Întrebările complementului direct", "back": "Pe cine?, ce?", "n": [1]}, {"front": "Ce caz are un substantiv complement direct?", "back": "Acuzativ, cu sau fără prepoziția pe.", "n": [0]}, {"front": "Ce este complementul prepozițional?", "back": "Determină un verb și arată obiectul care este ținta acțiunii sau pentru care acționează autorul.", "n": [2]}, {"front": "Întrebările complementului prepozițional", "back": "Pentru cine?, pentru ce?, de cine?, de ce?, la cine?, la ce?, de la cine?, de la ce?", "n": [2]}, {"front": "Cum deosebești complementul direct cu „pe” de cel prepozițional cu „pe”?", "back": "Complementul direct poate fi dublat de pronume personal neaccentuat (Îl ascult pe Dan); cel prepozițional nu (Contez pe prieteni).", "n": [3]}, {"front": "Ce este omonimia cazuală la nominativ și acuzativ?", "back": "Substantivele au aceeași formă la nominativ și la acuzativ.", "n": [4]}], "quiz": [{"type": "mcq", "q": "La ce întrebare răspunde complementul direct?", "options": ["cui?", "pe cine?, ce?", "unde?", "al cui?"], "answer": 1, "why": "Complementul direct răspunde la întrebările pe cine?, ce?.", "n": [1]}, {"type": "mcq", "q": "În „Îl ascult pe Dan.”, „pe Dan” este:", "options": ["complement prepozițional", "complement direct", "complement indirect", "circumstanțial"], "answer": 1, "why": "Este dublat de pronumele îl.", "n": [1, 3]}, {"type": "mcq", "q": "În „Contez pe prieteni.”, „pe prieteni” este:", "options": ["complement direct", "complement prepozițional", "subiect", "atribut"], "answer": 1, "why": "Nu poate fi dublat de pronume personal neaccentuat.", "n": [2, 3]}, {"type": "tf", "q": "Substantivul complement prepozițional este în cazul acuzativ.", "answer": true, "why": "Este însoțit de prepoziție, în acuzativ.", "n": [0]}, {"type": "tf", "q": "Complementul direct poate fi dublat de un pronume personal, formă neaccentuată.", "answer": true, "why": "Ex.: Îl ascult pe Dan.", "n": [3]}, {"type": "fill", "q": "„Nu se plictisește de pictură.” - „de pictură” este complement ____.", "answers": ["prepozițional", "prepozitional"], "why": "Răspunde la întrebarea de ce?, cu prepoziție.", "n": [2]}, {"type": "fill", "q": "La nominativ și la acuzativ substantivele au aceeași formă; fenomenul se numește omonimie ____.", "answers": ["cazuală", "cazuala"], "why": "Aceeași formă pentru cazuri diferite.", "n": [4]}, {"type": "match", "q": "Potrivește enunțul cu funcția substantivului subliniat.", "pairs": [["Dan colorează desenul.", "complement direct"], ["O zăresc pe Maria.", "complement direct"], ["Se gândește la o expoziție.", "complement prepozițional"], ["Nu se satură de cărți.", "complement prepozițional"]], "n": [1, 2]}, {"type": "classify", "q": "Încadrează întrebările.", "categories": ["Complement direct", "Complement prepozițional"], "items": [{"t": "pe cine?", "c": 0}, {"t": "ce?", "c": 0}, {"t": "la ce?", "c": 1}, {"t": "de cine?", "c": 1}, {"t": "pentru ce?", "c": 1}], "n": [1, 2]}]}, {"id": "u3-l12", "number": 12, "title": "Cazul acuzativ. Circumstanțialele. Atributul", "section": "Limbă română", "pages": "p. 109-111", "source": "", "theory": [{"term": "Complemente și circumstanțiale", "kind": "classification", "text": "Părțile de propoziție subordonate verbului sunt de două feluri:\n- unele sunt compliniri (sau completări) obligatorii, acestea fiind complemente; de exemplu, complementul direct (El vede filmul.) sau complementul prepozițional (El se gândește la lucrare.);\n- altele sunt compliniri facultative, arătând împrejurările desfășurării acțiunii, acestea fiind circumstanțiale; de exemplu: Ninge în oraș.", "examples": ["El vede filmul.", "El se gândește la lucrare.", "Ninge în oraș."], "important": true}, {"term": "Circumstanțialul de loc", "kind": "definition", "text": "Circumstanțialul de loc este un subordonat facultativ al unui verb și arată situarea și orientarea spațială.\nRăspunde la întrebările: unde?, de unde?, pe unde?, încotro?, dincotro? etc.\nÎn raport cu anumite verbe, circumstanțialul de loc este obligatoriu: Dan locuiește în București. Legumele provin din Spania. Mihai se îndreaptă spre casă.\nSubstantivul cu funcție sintactică de circumstanțial de loc este în cazul acuzativ, fiind însoțit de prepoziție.", "examples": ["Radu se joacă în grădină.", "Aleargă până la gard.", "Se întoarce spre casă."], "important": true}, {"term": "Circumstanțialul de timp", "kind": "definition", "text": "Circumstanțialul de timp este un subordonat facultativ al unui verb și arată reperele temporale pe care le are o împrejurare.\nRăspunde la întrebările: când?, de când?, până când?, cât timp? etc.\nSubstantivul cu funcție sintactică de circumstanțial de timp este în cazul acuzativ, fiind însoțit de prepoziție.", "examples": ["Am mers în vacanță la bunici.", "Am stat la ei până la sfârșitul anului."], "important": true}, {"term": "Circumstanțialul de mod", "kind": "definition", "text": "Circumstanțialul de mod este un subordonat facultativ al unui verb și arată felul în care se desfășoară o acțiune sau caracteristica unui eveniment.\nRăspunde la întrebările cum?, în ce fel? etc.\nSubstantivul cu funcție sintactică de circumstanțial de mod stă în cazul acuzativ, fiind însoțit de prepoziție.", "examples": ["Mama mi-a vorbit cu blândețe.", "În liniște, am început să fac treabă."], "important": true}, {"term": "Punctuația circumstanțialelor", "kind": "norm", "text": "Circumstanțialele nu se separă, de obicei, prin virgulă, indiferent de locul lor față de verbul determinat. Când vorbitorul dorește să le evidențieze în enunț, plasându-le, cel mai adesea, înaintea verbului de care depind, se pot despărți prin virgulă (În această seară, am scris tema.).\nSe pun între virgule circumstanțialele așezate între subiect și predicat (Ana, în această dimineață, n-a mers la școală.) sau cele așezate înaintea complementelor obligatorii, cum este complementul direct (Ana citește, cu atenție, textul.).", "examples": ["În această seară, am scris tema.", "Ana, în această dimineață, n-a mers la școală.", "Ana citește, cu atenție, textul."], "important": true}, {"term": "Atributul substantival prepozițional", "kind": "definition", "text": "Atributul exprimat prin substantiv în cazul acuzativ cu prepoziție se numește atribut substantival prepozițional.", "examples": ["cutia de creioane", "arțarul de lângă bloc", "strada cu mașini"], "important": true}, {"term": "Funcțiile substantivului în acuzativ", "kind": "classification", "text": "Substantivul în cazul acuzativ poate îndeplini funcțiile sintactice de:\n- complement direct;\n- complement prepozițional;\n- circumstanțial de loc;\n- circumstanțial de timp;\n- circumstanțial de mod;\n- atribut substantival prepozițional.", "examples": [], "important": true}], "flashcards": [{"front": "Complement vs. circumstanțial", "back": "Complementul este o complinire obligatorie a verbului; circumstanțialul este facultativ și arată împrejurările acțiunii.", "n": [0]}, {"front": "Întrebările circumstanțialului de loc", "back": "Unde?, de unde?, pe unde?, încotro?, dincotro?", "n": [1]}, {"front": "Întrebările circumstanțialului de timp", "back": "Când?, de când?, până când?, cât timp?", "n": [2]}, {"front": "Întrebările circumstanțialului de mod", "back": "Cum?, în ce fel?", "n": [3]}, {"front": "Când se pune virgulă la circumstanțial?", "back": "Când e evidențiat înaintea verbului, între subiect și predicat sau înaintea complementului obligatoriu.", "n": [4]}, {"front": "Ce este atributul substantival prepozițional?", "back": "Atributul exprimat prin substantiv în acuzativ cu prepoziție (cutia de creioane).", "n": [5]}, {"front": "Ce funcții poate avea substantivul în acuzativ?", "back": "Complement direct, complement prepozițional, circumstanțial de loc/timp/mod, atribut substantival prepozițional.", "n": [6]}], "quiz": [{"type": "mcq", "q": "În „Aleargă până la gard.”, „până la gard” este circumstanțial de:", "options": ["timp", "mod", "loc", "cauză"], "answer": 2, "why": "Răspunde la întrebarea până unde?.", "n": [1]}, {"type": "mcq", "q": "În „Mama mi-a vorbit cu blândețe.”, „cu blândețe” este circumstanțial de:", "options": ["loc", "timp", "mod", "atribut"], "answer": 2, "why": "Răspunde la întrebarea cum?.", "n": [3]}, {"type": "mcq", "q": "Care este corect punctat?", "options": ["Ana în această dimineață n-a mers la școală.", "Ana, în această dimineață, n-a mers la școală.", "Ana, în această dimineață n-a mers la școală.", "Ana în această dimineață, n-a mers la școală."], "answer": 1, "why": "Circumstanțialul dintre subiect și predicat se pune între virgule.", "n": [4]}, {"type": "tf", "q": "Circumstanțialul este o complinire facultativă a verbului.", "answer": true, "why": "Complementul este obligatoriu, circumstanțialul facultativ.", "n": [0]}, {"type": "tf", "q": "Circumstanțialele se despart întotdeauna prin virgulă.", "answer": false, "why": "De obicei nu se separă; virgula apare doar pentru evidențiere sau în poziții speciale.", "n": [4]}, {"type": "fill", "q": "Substantivul circumstanțial de timp este în cazul ____, însoțit de prepoziție.", "answers": ["acuzativ"], "why": "Toate circumstanțialele exprimate prin substantiv stau în acuzativ.", "n": [2, 6]}, {"type": "fill", "q": "„Cutia de creioane”: „de creioane” este atribut substantival ____.", "answers": ["prepozițional", "prepozitional"], "why": "Substantiv în acuzativ cu prepoziție, funcție de atribut.", "n": [5]}, {"type": "match", "q": "Potrivește exemplul cu funcția.", "pairs": [["Radu se joacă în grădină.", "circumstanțial de loc"], ["Am stat la ei până la sfârșitul anului.", "circumstanțial de timp"], ["Mama a vorbit cu blândețe.", "circumstanțial de mod"], ["cutia de creioane", "atribut substantival prepozițional"]], "n": [1, 2, 3, 5]}, {"type": "classify", "q": "Încadrează întrebările.", "categories": ["Loc", "Timp", "Mod"], "items": [{"t": "încotro?", "c": 0}, {"t": "până când?", "c": 1}, {"t": "cum?", "c": 2}, {"t": "dincotro?", "c": 0}, {"t": "cât timp?", "c": 1}, {"t": "în ce fel?", "c": 2}], "n": [1, 2, 3]}]}, {"id": "u3-l13", "number": 13, "title": "Cazul dativ. Complementul indirect", "section": "Limbă română", "pages": "p. 112", "source": "", "theory": [{"term": "Cazul dativ", "kind": "rule", "text": "Substantivul care are funcția sintactică de complement și răspunde la întrebarea cui? se află în cazul dativ.", "examples": ["I-am adus Mariei o carte."], "important": true}, {"term": "Ortografia numelor de persoane la dativ", "kind": "norm", "text": "Substantivele nume de persoane masculine sau feminine terminate în consoană sau de origine străină sunt precedate la dativ de cuvântul lui (marcă de caz). Substantivele nume de persoane feminine sfârșite în -a se termină la dativ în -ei (Robertei). Substantivele nume de persoane feminine terminate în -ca, -ga, la dativ se termină în -ăi (Ericăi, Helgăi).", "examples": ["lui Carmen", "lui Petru", "Robertei", "Ericăi", "Helgăi"], "important": true}, {"term": "Complementul indirect", "kind": "definition", "text": "Complementul indirect este partea de propoziție care determină un verb și arată beneficiarul unei acțiuni. De exemplu: Îi dau copilului un măr.\nComplementul indirect răspunde la întrebarea cui?.\nSubstantivul cu funcție sintactică de complement indirect stă în cazul dativ.", "examples": ["Îi dau copilului un măr.", "Zăpada îi dădea copacului o înfățișare ciudată. (cui dădea?)"], "important": true}, {"term": "Model de analiză: complement indirect (exercițiu)", "kind": "example", "text": "„vrăbiuțelor” - complement indirect, exprimat prin substantiv comun, genul feminin, numărul plural, cazul dativ, articulat cu articolul hotărât „-lor”", "examples": [], "important": false, "derived": true}], "flashcards": [{"front": "Ce este complementul indirect?", "back": "Partea de propoziție care determină un verb și arată beneficiarul unei acțiuni.", "n": [2]}, {"front": "La ce întrebare răspunde complementul indirect?", "back": "Cui?", "n": [0, 2]}, {"front": "În ce caz stă complementul indirect?", "back": "Dativ.", "n": [0]}, {"front": "Cum se scrie dativul lui Roberta, Erica, Helga?", "back": "Robertei, Ericăi, Helgăi (-a→-ei; -ca/-ga→-ăi).", "n": [1]}, {"front": "Când apare „lui” la dativ?", "back": "Înaintea numelor de persoane terminate în consoană sau de origine străină (lui Petru, lui Carmen).", "n": [1]}], "quiz": [{"type": "mcq", "q": "La ce întrebare răspunde complementul indirect?", "options": ["pe cine?", "cui?", "unde?", "cum?"], "answer": 1, "why": "Arată beneficiarul acțiunii: cui?.", "n": [2]}, {"type": "mcq", "q": "Care este dativul corect al numelui Erica?", "options": ["Ericei", "Ericăi", "Ericii", "Ericie"], "answer": 1, "why": "Numele feminine terminate în -ca, -ga au la dativ -ăi.", "n": [1]}, {"type": "tf", "q": "În „Îi dau copilului un măr.”, „copilului” este în cazul dativ.", "answer": true, "why": "Este complement indirect, răspunde la cui?.", "n": [0]}, {"type": "tf", "q": "Numele Carmen la dativ se scrie fără „lui”.", "answer": false, "why": "Nume de origine străină/terminate în consoană: lui Carmen.", "n": [1]}, {"type": "fill", "q": "Complementul indirect stă în cazul ____.", "answers": ["dativ"], "why": "Răspunde la întrebarea cui?.", "n": [0]}, {"type": "fill", "q": "Dativul numelui Roberta este ____.", "answers": ["robertei"], "why": "Numele feminine terminate în -a au la dativ -ei.", "n": [1]}, {"type": "match", "q": "Potrivește numele cu forma de dativ.", "pairs": [["Roberta", "Robertei"], ["Erica", "Ericăi"], ["Helga", "Helgăi"], ["Petru", "lui Petru"]], "n": [1]}]}, {"id": "u3-l14", "number": 14, "title": "Cazul genitiv. Articolul genitival. Posibilități combinatorii ale substantivului", "section": "Limbă română", "pages": "p. 113-114", "source": "", "theory": [{"term": "Cazul genitiv", "kind": "rule", "text": "Substantivul cu funcție sintactică de atribut care răspunde la întrebările al, a, ai, ale cui? este în cazul genitiv. Funcția sintactică a substantivului în cazul genitiv este de atribut substantival genitival.\nÎn dativ și genitiv, substantivele au aceeași formă.", "examples": ["fratele Roxanei", "cariocile surorii", "ochii broaștelor"], "important": true}, {"term": "Articolul genitival", "kind": "definition", "text": "Substantivul în cazul genitiv poate fi precedat de cuvintele al, a, ai, ale, care se numesc articole genitivale. Rolul acestora, în această situație, este de a marca suplimentar cazul genitiv și de a stabili relația dintre substantivul în genitiv și substantivul determinat de acesta.\nFormele articolului genitival sunt:\nsingular - masculin: al; feminin: a\nplural - masculin: ai; feminin: ale", "examples": ["pereții albi ai camerei", "iarba albastră a câmpului", "crengile galbene ale pomilor", "soarele verde al cerului"], "important": true}, {"term": "Acordul articolului genitival", "kind": "rule", "text": "Articolul genitival se acordă în gen și număr cu substantivul determinat de substantivul în genitiv. Într-o enumerare de substantive în genitiv, articolul genitival se reia înaintea fiecărui substantiv.\nÎnaintea substantivelor proprii nume de persoane masculine sau feminine terminate în consoană sau a numelor de origine străină aflate în cazul genitiv, pe lângă articolul genitival poate să apară și cuvântul lui, ca marcă a cazului.", "examples": ["perdelele sufrageriei, ale bucătăriei și ale camerei", "caietul curat al lui Dan"], "important": true}, {"term": "Posibilități combinatorii ale substantivului", "kind": "classification", "text": "Substantivul se poate combina în enunț cu alte cuvinte, fiind:\n- centru al unui grup de cuvinte, numit grup nominal, când i se subordonează atributul adjectival (caiet curat), atributul substantival prepozițional (caiet de notițe), atributul substantival genitival (caietul copilului);\n- adjunct într-un grup nominal, când este atribut substantival prepozițional (caiet de notițe), atribut substantival genitival (caietul copilului), sau într-un grup verbal, adică un grup de cuvinte având centru un verb, când este complement direct (Ia un caiet.), complement prepozițional (Mă gândesc la caiet.), complement indirect (Îi pun caietului copertă.), circumstanțial (Pixul este pe caiet.).\nÎn grupul verbal, o situație specială o au subiectul - acesta stabilește cu verbul predicat o relație de interdependență - și numele predicativ, care intră într-o relație ternară cu subiectul și cu verbul copulativ.\nUn substantiv poate fi, în același timp, centru și adjunct, intrând în grupuri diferite.", "examples": ["caiet curat", "caiet de notițe", "caietul copilului", "Ia un caiet.", "Pixul este pe caiet."], "important": true}, {"term": "Model de analiză: atribut substantival genitival (exercițiu)", "kind": "example", "text": "„a tatălui” - substantiv comun, genul masculin, numărul singular, cazul genitiv, articulat cu articolul hotărât „-lui”, precedat de articolul genitival „a”, funcția sintactică de atribut substantival genitival", "examples": [], "important": false, "derived": true}], "flashcards": [{"front": "La ce întrebări răspunde atributul substantival genitival?", "back": "Al, a, ai, ale cui?", "n": [0]}, {"front": "Formele articolului genitival", "back": "Singular: al (m.), a (f.); plural: ai (m.), ale (f.).", "n": [1]}, {"front": "Cu ce se acordă articolul genitival?", "back": "În gen și număr cu substantivul determinat de substantivul în genitiv.", "n": [2]}, {"front": "Se reia articolul genitival într-o enumerare?", "back": "Da, înaintea fiecărui substantiv în genitiv.", "n": [2]}, {"front": "Ce au în comun dativul și genitivul?", "back": "Aceeași formă a substantivelor.", "n": [0]}, {"front": "Ce este grupul nominal?", "back": "Grup de cuvinte cu substantivul drept centru (caiet curat).", "n": [3]}, {"front": "Când e substantivul adjunct în grupul verbal?", "back": "Când este complement direct, prepozițional, indirect sau circumstanțial.", "n": [3]}], "quiz": [{"type": "mcq", "q": "Care este articolul genitival potrivit: „ramurile mari ... copacilor”?", "options": ["al", "a", "ai", "ale"], "answer": 3, "why": "Ramurile este feminin plural: ale.", "n": [2]}, {"type": "mcq", "q": "Care este articolul genitival potrivit: „mașina veche ... familiei”?", "options": ["al", "a", "ai", "ale"], "answer": 1, "why": "Mașina este feminin singular: a.", "n": [2]}, {"type": "mcq", "q": "Care este articolul genitival potrivit: „pereții albi ... camerei”?", "options": ["al", "a", "ai", "ale"], "answer": 2, "why": "Pereții este masculin plural: ai.", "n": [2]}, {"type": "tf", "q": "Substantivele au aceeași formă în dativ și în genitiv.", "answer": true, "why": "Se disting prin funcția sintactică și contextul.", "n": [0]}, {"type": "tf", "q": "Într-o enumerare de substantive în genitiv, articolul genitival apare o singură dată.", "answer": false, "why": "Se reia înaintea fiecărui substantiv.", "n": [2]}, {"type": "fill", "q": "Funcția substantivului în genitiv este de atribut substantival ____.", "answers": ["genitival"], "why": "Răspunde la întrebările al, a, ai, ale cui?.", "n": [0]}, {"type": "fill", "q": "Cuvintele al, a, ai, ale se numesc articole ____.", "answers": ["genitivale", "genitival"], "why": "Marchează suplimentar genitivul.", "n": [1]}, {"type": "match", "q": "Potrivește genul și numărul cu articolul genitival.", "pairs": [["masculin singular", "al"], ["feminin singular", "a"], ["masculin plural", "ai"], ["feminin plural", "ale"]], "n": [2]}, {"type": "classify", "q": "Funcția substantivului „caiet” din grupurile date.", "categories": ["Centru de grup nominal", "Adjunct (în grup verbal)"], "items": [{"t": "caiet curat (caiet)", "c": 0}, {"t": "Ia un caiet. (caiet)", "c": 1}, {"t": "Mă gândesc la caiet. (caiet)", "c": 1}, {"t": "caiet de notițe (caiet)", "c": 0}], "n": [3]}]}, {"id": "u3-l15", "number": 15, "title": "Cazul vocativ", "section": "Limbă română", "pages": "p. 115", "source": "", "theory": [{"term": "Cazul vocativ", "kind": "definition", "text": "Substantivul care arată o chemare sau prin care i se atrage atenția unei persoane este în cazul vocativ.\nSubstantivele în cazul vocativ nu au funcție sintactică, putând fi însă centru pentru un atribut.", "examples": ["Corina, pleci departe în vacanță?", "Oameni buni, ajutați-mă!"], "important": true}, {"term": "Formele vocativului", "kind": "classification", "text": "Substantivele în vocativ pot avea:\n- formă proprie, construită cu desinențele -e (băiete, Vlade), -ule (copilule), -o (Ano) sau -lor (copiilor, fetelor);\n- aceeași formă cu nominativul (fată, Anca).", "examples": ["băiete", "Vlade", "copilule", "Ano", "copiilor", "fată", "Anca"], "important": true}, {"term": "Punctuația vocativului", "kind": "norm", "text": "În scris, substantivele în cazul vocativ se separă prin virgulă de restul propoziției.\nUneori, după substantivul în vocativ se pune semnul exclamării.\nDacă substantivul în vocativ are determinanți, întregul grup se separă prin virgulă de restul propoziției (Dragi colegi de clasă, vă felicit!).", "examples": ["Dragi colegi de clasă, vă felicit!", "Ascultă melodia, băiatule!"], "important": true}], "flashcards": [{"front": "Ce este cazul vocativ?", "back": "Cazul substantivului care arată o chemare sau prin care se atrage atenția unei persoane.", "n": [0]}, {"front": "Are substantivul în vocativ funcție sintactică?", "back": "Nu, dar poate fi centru pentru un atribut.", "n": [0]}, {"front": "Desinențele vocativului", "back": "-e, -ule, -o, -lor (sau aceeași formă cu nominativul).", "n": [1]}, {"front": "Cum se scrie vocativul în propoziție?", "back": "Se separă prin virgulă (uneori semnul exclamării).", "n": [2]}, {"front": "Cum se separă un vocativ cu determinanți?", "back": "Întregul grup se separă prin virgulă (Dragi colegi de clasă, vă felicit!).", "n": [2]}], "quiz": [{"type": "mcq", "q": "Care este vocativul substantivului „băiat”?", "options": ["băiat", "băiete", "băieți", "băiatul"], "answer": 1, "why": "Formă proprie cu desinența -e.", "n": [1]}, {"type": "mcq", "q": "Care enunț este corect punctuat?", "options": ["Mamă mă ajuți?", "Mamă, mă ajuți?", "Mamă mă, ajuți?", "Mamă mă ajuți."], "answer": 1, "why": "Vocativul se desparte prin virgulă.", "n": [2]}, {"type": "tf", "q": "Substantivul în vocativ are funcție sintactică de subiect.", "answer": false, "why": "Vocativul nu are funcție sintactică.", "n": [0]}, {"type": "tf", "q": "Unele substantive au vocativul identic cu nominativul (fată, Anca).", "answer": true, "why": "Nu toate au formă proprie.", "n": [1]}, {"type": "fill", "q": "Vocativul lui „copil” este copil____.", "answers": ["ule"], "why": "Desinența -ule: copilule.", "n": [1]}, {"type": "fill", "q": "Vocativul lui „Ana” (formă proprie) este ____.", "answers": ["ano"], "why": "Desinența -o: Ano.", "n": [1]}, {"type": "match", "q": "Potrivește substantivul cu desinența vocativului.", "pairs": [["Vlad", "-e (Vlade)"], ["copil", "-ule (copilule)"], ["Ana", "-o (Ano)"], ["fetele", "-lor (fetelor)"]], "n": [1]}, {"type": "classify", "q": "Încadrează formele de vocativ.", "categories": ["Formă proprie", "Aceeași formă cu nominativul"], "items": [{"t": "băiete", "c": 0}, {"t": "fată", "c": 1}, {"t": "Anca", "c": 1}, {"t": "copilule", "c": 0}, {"t": "copiilor", "c": 0}], "n": [1]}]}, {"id": "u3-l16", "number": 16, "title": "Descrierea unui peisaj", "section": "Redactare", "pages": "p. 116-117", "source": "", "theory": [{"term": "Cum descriem un peisaj", "kind": "rule", "text": "Pentru a descrie un peisaj, un decor, un tablou, un fenomen al naturii:\n- se poate prezenta imaginea în ansamblu;\n- se pot înfățișa diferitele elemente ale imaginii, mișcând privirea la dreapta, la stânga, sus, jos, împrejur sau urmărind planurile mai apropiate sau mai îndepărtate de privitor (prim-plan, plan secund, fundal);\n- sunt numite, prin substantive, elementele componente ale imaginii descrise și elementele lor componente;\n- se evidențiază proprietățile elementelor componente, folosindu-se adjective;\n- se pot folosi figuri de stil;\n- se dezvăluie emoțiile și sentimentele celui care face descrierea (numindu-le, folosind persoana I, singular, utilizând cuvinte ca ah, of, vai etc.);\n- se folosesc timpurile prezent sau imperfect în redactare.", "examples": ["prim-plan, plan secund, fundal"], "important": true}, {"term": "Etapele scrierii unei compuneri", "kind": "classification", "text": "Etapa 1: Pregătirea (alege subiectul - pentru cine scrii, de ce scrii; strânge informații; elaborează planul lucrării).\nEtapa 2: Ciorna (prima variantă).\nEtapa 3: Revizuirea.\nEtapa 4: Editarea.\nEtapa 5: Publicarea.", "examples": [], "important": true}], "flashcards": [{"front": "Care sunt planurile unui peisaj descris?", "back": "Prim-plan, plan secund, fundal.", "n": [0]}, {"front": "Cu ce părți de vorbire se numesc elementele componente și se evidențiază proprietățile lor?", "back": "Elementele: substantive; proprietățile: adjective.", "n": [0]}, {"front": "Cum se dezvăluie emoțiile în descriere?", "back": "Prin numirea lor, persoana I singular, cuvinte ca ah, of, vai.", "n": [0]}, {"front": "Ce timpuri se folosesc în descriere?", "back": "Prezent sau imperfect.", "n": [0]}, {"front": "Cele cinci etape ale redactării", "back": "Pregătirea, ciorna, revizuirea, editarea, publicarea.", "n": [1]}, {"front": "Ce faci în etapa de pregătire?", "back": "Alegi subiectul (pentru cine și de ce scrii), strângi informații, elaborezi planul.", "n": [1]}], "quiz": [{"type": "mcq", "q": "Care dintre acestea NU este un plan al unui peisaj?", "options": ["prim-plan", "plan secund", "fundal", "plan lateral"], "answer": 3, "why": "Planurile sunt prim-plan, plan secund, fundal.", "n": [0]}, {"type": "mcq", "q": "Ce etapă urmează după „ciorna” în redactare?", "options": ["Publicarea", "Editarea", "Revizuirea", "Pregătirea"], "answer": 2, "why": "Ordinea: pregătirea, ciorna, revizuirea, editarea, publicarea.", "n": [1]}, {"type": "tf", "q": "Într-o descriere, proprietățile elementelor componente se evidențiază cu adjective.", "answer": true, "why": "Elementele se numesc cu substantive, proprietățile cu adjective.", "n": [0]}, {"type": "tf", "q": "Într-o descriere de peisaj nu se pot dezvălui emoțiile celui care descrie.", "answer": false, "why": "Emoțiile se pot dezvălui (persoana I, ah, of, vai).", "n": [0]}, {"type": "fill", "q": "Prima etapă a redactării este ____.", "answers": ["pregătirea", "pregatirea"], "why": "Urmează ciorna.", "n": [1]}, {"type": "fill", "q": "În descriere se folosesc timpurile prezent sau ____.", "answers": ["imperfect", "imperfectul"], "why": "Prezent sau imperfect.", "n": [0]}, {"type": "match", "q": "Potrivește numărul etapei cu denumirea ei.", "pairs": [["Etapa 1", "Pregătirea"], ["Etapa 2", "Ciorna (prima variantă)"], ["Etapa 3", "Revizuirea"], ["Etapa 4", "Editarea"], ["Etapa 5", "Publicarea"]], "n": [1]}, {"type": "classify", "q": "Încadrează cuvintele după rolul lor în descriere.", "categories": ["Element component (substantiv)", "Proprietate (adjectiv)"], "items": [{"t": "câmp", "c": 0}, {"t": "alb", "c": 1}, {"t": "plopi", "c": 0}, {"t": "strălucitor", "c": 1}], "n": [0]}]}]}, {"unit": {"id": "u4", "number": 4, "title": "Popasuri cu tâlc", "summary": "Textul narativ literar în versuri (fabula), enumerația, personajele și morala; proverbele, dicția și inteligența emoțională; pronumele personal, reflexiv și numeralul; secvențe descriptive în narațiune și textul explicativ."}, "lessons": [{"id": "u4-l1", "number": 1, "title": "Textul narativ literar în versuri", "section": "Lectură", "pages": "p. 122-123", "source": "Uleul și găinile - Grigore Alexandrescu", "theory": [{"term": "Grigore Alexandrescu", "kind": "tip", "text": "Poet și prozator din generația scriitorilor legați de Revoluția de la 1848. Foarte cunoscute sunt poeziile sale în care critică defecte omenești sau aspecte negative ale vremii, sub forma unor istorioare cu tâlc (fabule): Boul și vițelul, Lupul moralist, Câinele și cățelul, Dreptatea leului etc. Este considerat cel mai mare fabulist din literatura română.", "examples": ["Boul și vițelul", "Lupul moralist", "Câinele și cățelul", "Dreptatea leului"], "important": false}, {"term": "Fabula (din prezentarea autorului) (exercițiu)", "kind": "definition", "text": "Istorioară cu tâlc în versuri, în care sunt criticate defecte omenești sau aspecte negative ale vremii (după prezentarea autorului Grigore Alexandrescu).", "examples": ["Uleul și găinile"], "important": false, "derived": true}, {"term": "Cuvinte din text (glosar)", "kind": "tip", "text": "uleu/uliu – pasăre răpitoare de zi, puternică și mare, care atacă păsări și mamifere mici.\na priimi (înv.) – a primi, a găzdui.\nslobod – liber.\na slobozi – a pune în libertate, a elibera.\nnenorocit – aflat într-o situație vrednică de plâns, într-un necaz.", "examples": [], "important": false}], "flashcards": [{"front": "Cine este considerat cel mai mare fabulist din literatura română?", "back": "Grigore Alexandrescu", "n": [0]}, {"front": "Ce este un uliu (uleu)?", "back": "O pasăre răpitoare de zi, puternică și mare, care atacă păsări și mamifere mici.", "n": [2]}, {"front": "Ce înseamnă „a slobozi”?", "back": "A pune în libertate, a elibera.", "n": [2]}, {"front": "Ce sunt fabulele lui Alexandrescu?", "back": "Istorioare cu tâlc în versuri, în care sunt criticate defecte omenești sau aspecte negative ale vremii.", "n": [1]}, {"front": "Ce înseamnă „nenorocit” în text?", "back": "Aflat într-o situație vrednică de plâns, într-un necaz.", "n": [2]}], "quiz": [{"type": "mcq", "q": "Grigore Alexandrescu este considerat:", "options": ["cel mai mare romancier român", "cel mai mare fabulist din literatura română", "primul dramaturg român", "cel mai mare povestitor popular"], "answer": 1, "why": "Manualul spune că este considerat cel mai mare fabulist din literatura română.", "n": [0]}, {"type": "tf", "q": "Grigore Alexandrescu face parte din generația scriitorilor legați de Revoluția de la 1848.", "answer": true, "why": "Așa este prezentat în biografia din manual.", "n": [0]}, {"type": "fill", "q": "Uleul este o pasăre ____ de zi, puternică și mare.", "answers": ["răpitoare"], "why": "Definiția din glosar: pasăre răpitoare de zi.", "n": [2]}, {"type": "match", "q": "Potrivește cuvântul cu sensul lui.", "pairs": [["slobod", "liber"], ["a slobozi", "a elibera"], ["a priimi", "a primi, a găzdui"], ["nenorocit", "aflat într-un necaz"]], "n": [2]}, {"type": "mcq", "q": "Care dintre titluri este o fabulă de Grigore Alexandrescu?", "options": ["Greierele și furnica", "Boul și vițelul", "Iliada", "Cocoșul și vulpea"], "answer": 1, "why": "Boul și vițelul este citată printre fabulele lui Alexandrescu; Cocoșul și vulpea este de La Fontaine.", "n": [0]}, {"type": "tf", "q": "Poeziile lui Alexandrescu în care critică defecte omenești sunt scrise sub forma unor istorioare cu tâlc (fabule).", "answer": true, "why": "Exact așa sunt descrise în manual.", "n": [1]}]}, {"id": "u4-l2", "number": 2, "title": "Acțiunea, timpul și spațiul", "section": "Lectură", "pages": "p. 124-125", "source": "Uleul și găinile - Grigore Alexandrescu", "theory": [{"term": "Textul narativ literar", "kind": "definition", "text": "Textul narativ literar poate fi scris atât în proză, cât și în versuri.", "examples": [], "important": true}, {"term": "Textul narativ literar în versuri", "kind": "definition", "text": "Textul narativ literar în versuri reprezintă un anumit tip de poezie în care se relatează, de către un narator, o întâmplare la care iau parte mai multe personaje. De regulă, în astfel de texte, acțiunea este alertă, dialogurile sunt vii și se acordă o mare importanță muzicalității, obținute prin rime variate, lungimea sau scurtimea versurilor și ritm.", "examples": [], "important": true}, {"term": "Originea textelor narative în versuri", "kind": "definition", "text": "Textele narative literare în versuri își au originea în tradițiile orale. Înainte de a învăța să scrie, oamenii au folosit versurile cu rimă și ritm pentru a relata întâmplări semnificative într-o formă ușor de memorat. Uneori, era vorba despre întâmplări eroice (ca în Iliada și Odiseea de Homer sau în cântecele despre peripețiile cavalerilor medievali sau ale haiducilor), alteori despre întâmplări cu tâlc, care meritau să fie ținute minte pentru învățătura pe care o transmiteau.", "examples": ["Iliada și Odiseea de Homer"], "important": true}, {"term": "Fabula", "kind": "definition", "text": "În fabule se oferă o lecție de viață prin intermediul unei întâmplări simple, puse pe seama unor animale, plante sau obiecte ce întruchipează trăsături omenești. Pentru că întâmplările au o semnificație general valabilă, spațiul și timpul narațiunii sunt vag precizate.", "examples": [], "important": true}, {"term": "Morala", "kind": "definition", "text": "Aceste texte au o morală, care poate fi explicită (rostită fie de către narator, fie de un personaj) sau implicită (cititorii fiind cei care trebuie să o deducă din întâmplarea prezentată).", "examples": [], "important": true}, {"term": "Naratorul și persoana I (exercițiu)", "kind": "tip", "text": "În finalul textului Uleul și găinile, versurile separate printr-un spațiu alb conțin pronumele eu și verbe la persoana I, numărul singular: ele desemnează naratorul, care își exprimă opinia (morala).", "examples": ["Eu d-aș fi fost găină nu l-aș fi slobozit"], "important": false, "derived": true}, {"term": "Fixarea acțiunii în text (exercițiu)", "kind": "tip", "text": "Acțiunea poate fi reconstituită ordonând evenimentele; întâmplările care generează consecințe în lanț se pot nota cu conectori precum: așa că, astfel încât, ca urmare.", "examples": ["Ion a legat uliul prins de cotețul găinilor, așa că găinile s-au obișnuit cu el."], "important": false, "derived": true}], "flashcards": [{"front": "Cum poate fi scris un text narativ literar?", "back": "Atât în proză, cât și în versuri.", "n": [0]}, {"front": "Ce relatează un text narativ literar în versuri?", "back": "O întâmplare la care iau parte mai multe personaje, relatată de un narator.", "n": [1]}, {"front": "Cum obține muzicalitatea un text narativ în versuri?", "back": "Prin rime variate, lungimea sau scurtimea versurilor și ritm.", "n": [1]}, {"front": "Unde își au originea textele narative în versuri?", "back": "În tradițiile orale.", "n": [2]}, {"front": "De ce sunt spațiul și timpul vag precizate în fabule?", "back": "Pentru că întâmplările au o semnificație general valabilă.", "n": [3]}, {"front": "Ce este morala explicită? Dar cea implicită?", "back": "Explicită: rostită de narator sau de un personaj. Implicită: cititorii o deduc din întâmplare.", "n": [4]}, {"front": "Ce oferă fabulele?", "back": "O lecție de viață printr-o întâmplare simplă, pusă pe seama unor animale, plante sau obiecte care întruchipează trăsături omenești.", "n": [3]}], "quiz": [{"type": "mcq", "q": "Care este caracteristica obișnuită a acțiunii într-un text narativ în versuri?", "options": ["lentă și descriptivă", "alertă", "fără personaje", "fără narator"], "answer": 1, "why": "De regulă acțiunea este alertă, dialogurile sunt vii.", "n": [1]}, {"type": "tf", "q": "Textul narativ literar poate fi scris numai în proză.", "answer": false, "why": "Poate fi scris atât în proză, cât și în versuri.", "n": [0]}, {"type": "fill", "q": "Muzicalitatea textelor narative în versuri se obține prin rime variate, lungimea versurilor și ____.", "answers": ["ritm"], "why": "Rime variate, lungimea sau scurtimea versurilor și ritm.", "n": [1]}, {"type": "mcq", "q": "De ce sunt spațiul și timpul narațiunii vag precizate în fabule?", "options": ["autorul a uitat să le precizeze", "întâmplările au o semnificație general valabilă", "fabulele nu au acțiune", "textele sunt foarte scurte"], "answer": 1, "why": "Întâmplările au o semnificație general valabilă.", "n": [3]}, {"type": "mcq", "q": "Morala este implicită atunci când:", "options": ["este rostită de narator", "este rostită de un personaj", "cititorii trebuie să o deducă din întâmplare", "apare în titlu"], "answer": 2, "why": "Morala implicită este dedusă de cititori din întâmplarea prezentată.", "n": [4]}, {"type": "tf", "q": "Textele narative în versuri își au originea în tradițiile orale.", "answer": true, "why": "Oamenii foloseau versuri cu rimă și ritm pentru a ține minte întâmplările.", "n": [2]}, {"type": "match", "q": "Potrivește tipul de morală cu descrierea.", "pairs": [["morală explicită", "rostită de narator sau de un personaj"], ["morală implicită", "dedusă de cititori din întâmplare"]], "n": [4]}, {"type": "fill", "q": "În fabule se oferă o lecție de viață prin intermediul unei întâmplări simple, puse pe seama unor animale, plante sau ____.", "answers": ["obiecte"], "why": "Animale, plante sau obiecte ce întruchipează trăsături omenești.", "n": [3]}]}, {"id": "u4-l3", "number": 3, "title": "Enumerația. Personajele", "section": "Lectură", "pages": "p. 126-127", "source": "Uleul și găinile - Grigore Alexandrescu", "theory": [{"term": "Enumerația", "kind": "definition", "text": "Enumerația este figura de stil care constă în înșiruirea mai multor termeni de același fel (substantive, adjective, verbe etc.), pentru accentuarea ideii exprimate sau pentru detalierea aspectelor descrise. Termenii acestei înșiruiri se despart prin virgulă.", "examples": ["Găini, cocoși și gâște", "S-apucară de lucru: azi, mâine, se-ncercară"], "important": true}, {"term": "Personajele din fabule", "kind": "definition", "text": "În fabule, personajele – care pot fi animale, plante, păsări sau obiecte – sunt personificate, devenind măști pentru anumite tipuri de oameni, criticați pentru defectele lor: prostia, lăudăroșenia, dorința de putere, cruzimea, orgoliul, zgârcenia etc.", "examples": [], "important": true}, {"term": "Opoziția dintre personaje", "kind": "definition", "text": "Întâmplarea simplă pe care o prezintă un astfel de text narativ se bazează, de regulă, pe opoziția dintre două personaje. Încă din Antichitate, scriitorii (Esop, Fedru și alții) au atras atenția asupra acestei opoziții în titlurile creațiilor lor: Greierele și furnica, Lupul și mielul, Șoarecele de câmp și șoarecele de la oraș, Corbul și vulpea, Stejarul și trestia etc. Adesea, unul dintre personaje este într-o poziție superioară, de care este mândru sau cu care se laudă, iar celălalt, într-o poziție inferioară, lipsit de posibilități sau resurse. În urma unui eveniment neprevăzut, raportul dintre personaje se inversează.", "examples": ["Greierele și furnica", "Lupul și mielul", "Corbul și vulpea"], "important": true}, {"term": "Clasificarea personajelor (schema din manual) (exercițiu)", "kind": "classification", "text": "Personaje: animaliere / umane; principale / secundare; individuale / colective.", "examples": ["uliul – animalier, principal, individual", "găinile – animaliere, colective", "Ion – uman, secundar"], "important": false, "derived": true}, {"term": "Personificarea (exercițiu)", "kind": "tip", "text": "Figura de stil folosită de autor în prezentarea animalelor: animalele (păsările) se comportă ca oamenii, vorbesc și au defecte și calități omenești.", "examples": [], "important": false, "derived": true}], "flashcards": [{"front": "Ce este enumerația?", "back": "Figura de stil care constă în înșiruirea mai multor termeni de același fel, pentru accentuarea ideii sau detalierea aspectelor.", "n": [0]}, {"front": "Cum se despart termenii unei enumerații?", "back": "Prin virgulă.", "n": [0]}, {"front": "Ce devin personajele în fabule?", "back": "Măști pentru anumite tipuri de oameni, criticați pentru defectele lor.", "n": [1]}, {"front": "Pe ce se bazează, de regulă, întâmplarea unei fabule?", "back": "Pe opoziția dintre două personaje.", "n": [2]}, {"front": "Ce se întâmplă în urma unui eveniment neprevăzut?", "back": "Raportul dintre personaje se inversează.", "n": [2]}, {"front": "Ce figură de stil se folosește la prezentarea animalelor ca oameni?", "back": "Personificarea.", "n": [4]}, {"front": "Cine sunt autorii antici de fabule?", "back": "Esop, Fedru și alții.", "n": [1]}], "quiz": [{"type": "mcq", "q": "Care este enumerația din versul „Găini, cocoși și gâște întâi se îngroziră”?", "options": ["întâi se îngroziră", "găini, cocoși și gâște", "se îngroziră", "nu există enumerație"], "answer": 1, "why": "Sunt înșiruite trei substantive de același fel, despărțite prin virgulă.", "n": [0]}, {"type": "tf", "q": "Termenii unei enumerații se despart prin virgulă.", "answer": true, "why": "Așa spune definiția din manual.", "n": [0]}, {"type": "fill", "q": "În fabule, personajele sunt ____, devenind măști pentru anumite tipuri de oameni.", "answers": ["personificate"], "why": "Animalele, plantele, păsările sau obiectele sunt personificate.", "n": [1]}, {"type": "mcq", "q": "Enumerația se folosește pentru:", "options": ["a ascunde ideea", "accentuarea ideii exprimate sau detalierea aspectelor descrise", "a schimba naratorul", "a încheia textul"], "answer": 1, "why": "Aceasta este funcția enumerației.", "n": [0]}, {"type": "classify", "q": "Încadrează personajele după tip.", "categories": ["Personaje animaliere", "Personaje umane"], "items": [{"t": "uliul", "c": 0}, {"t": "găinile", "c": 0}, {"t": "Ion", "c": 1}, {"t": "cocoșii", "c": 0}], "n": [3]}, {"type": "match", "q": "Potrivește titlurile cu perechea de personaje opuse.", "pairs": [["Greierele și furnica", "greierele – furnica"], ["Lupul și mielul", "lupul – mielul"], ["Corbul și vulpea", "corbul – vulpea"], ["Stejarul și trestia", "stejarul – trestia"]], "n": [2]}, {"type": "tf", "q": "În fabule, personajele sunt criticate pentru defecte precum prostia, lăudăroșenia, cruzimea sau zgârcenia.", "answer": true, "why": "Defectele enumerate în manual includ și prostia, orgoliul, dorința de putere.", "n": [1]}, {"type": "mcq", "q": "În opoziția dintre personaje, de obicei, un personaj:", "options": ["nu are nicio calitate", "este într-o poziție superioară, iar celălalt într-una inferioară", "este mereu animal, iar celălalt om", "apare doar în final"], "answer": 1, "why": "Unul e într-o poziție superioară, celălalt în una inferioară, apoi raportul se inversează.", "n": [2]}]}, {"id": "u4-l4", "number": 4, "title": "Semnificațiile textului", "section": "Lectură", "pages": "p. 128", "source": "Uleul și găinile - Grigore Alexandrescu", "theory": [{"term": "Rolul moralei (exercițiu)", "kind": "tip", "text": "Morala lămurește într-un mod simplu și ușor de reținut semnificația întâmplării prezentate; invită cititorii să reflecteze la propriile acțiuni și să le corecteze, dacă este cazul; îi face pe cititori să-și înțeleagă mai bine semenii; îi ajută să se ferească de anumite tipuri de oameni.", "examples": [], "important": false, "derived": true}, {"term": "Fabula după La Fontaine (citat din Provocări)", "kind": "tip", "text": "Jean de La Fontaine: „O fabulă-i poveste – minciună-ncornorată – / dar multe adevăruri și-nvățături ne-arată.” (încornorat – aici: mare). Fabula transmite adevăruri și învățături prin graiul și pilda animalelor.", "examples": [], "important": false, "derived": true}, {"term": "Morala poeziei Uleul și găinile (exercițiu)", "kind": "example", "text": "Morala poeziei este exprimată sub forma unei constatări cu caracter general (Uleii sunt cinstiți, / Când sunt nenorociți) și poate fi reformulată ca recomandare sau îndemn de conduită.", "examples": ["Uleii sunt cinstiți, Când sunt nenorociți."], "important": false, "derived": true}], "flashcards": [{"front": "Cum este exprimată morala poeziei Uleul și găinile?", "back": "Sub forma unei constatări cu caracter general.", "n": [2]}, {"front": "Cum poate fi reformulată o morală exprimată ca constatare?", "back": "Ca recomandare sau ca îndemn de conduită.", "n": [2]}, {"front": "Ce rol are morala față de narațiune?", "back": "Lămurește simplu și ușor de reținut semnificația întâmplării.", "n": [0]}, {"front": "Ce spune La Fontaine despre fabulă?", "back": "Că e o poveste care ne arată multe adevăruri și învățături.", "n": [1]}], "quiz": [{"type": "mcq", "q": "Care este un rol al moralei?", "options": ["să încurce cititorul", "să lămurească simplu și ușor de reținut semnificația întâmplării", "să descrie peisajul", "să schimbe naratorul"], "answer": 1, "why": "Morala lămurește semnificația într-un mod simplu și ușor de reținut.", "n": [0]}, {"type": "tf", "q": "Morala poeziei Uleul și găinile este exprimată ca o constatare cu caracter general.", "answer": true, "why": "Poate fi reformulată ca recomandare sau îndemn.", "n": [2]}, {"type": "fill", "q": "Morala poate fi reformulată ca recomandare sau ca ____ de conduită.", "answers": ["îndemn"], "why": "Constatarea generală se poate transforma în îndemn de conduită.", "n": [2]}, {"type": "mcq", "q": "Cine a spus că fabula este o „poveste” care ne arată „multe adevăruri și-nvățături”?", "options": ["Grigore Alexandrescu", "Jean de La Fontaine", "Esop", "Anton Pann"], "answer": 1, "why": "Versurile sunt ale lui Jean de La Fontaine.", "n": [1]}]}, {"id": "u4-l5", "number": 5, "title": "Noi pagini – alte idei", "section": "Lectură", "pages": "p. 129-131", "source": "Iepurele și broasca-țestoasă - Jean de La Fontaine", "theory": [{"term": "Jean de La Fontaine", "kind": "tip", "text": "Unul dintre marii scriitori ai lumii, a trăit în Franța în secolul al XVII-lea, în vremea Regelui-Soare, Ludovic al XIV-lea. Deși se inspiră din creațiile antice ale lui Esop, La Fontaine le dezvoltă în versuri armonioase, cu un limbaj elegant și variat, introduce dialoguri, ca în teatru, făcând textul mai viu, precum și secvențe descriptive sau secvențe în care este argumentată o idee. Scopul declarat al operelor sale este „să instruiască și să placă”.", "examples": [], "important": false}, {"term": "Structura narațiunii Iepurele și broasca-țestoasă (exercițiu)", "kind": "classification", "text": "Morala se află la începutul textului (Decât s-alergi e mult mai bine / să pleci la drum când se cuvine!). Narațiunea propriu-zisă cuprinde trei momente importante: provocarea, întrecerea și victoria.", "examples": ["provocarea", "întrecerea", "victoria"], "important": false, "derived": true}, {"term": "Dictonul Festina lente!", "kind": "tip", "text": "La Fontaine traduce dictonul latinesc Festina lente! („Grăbește-te încet!”).", "examples": [], "important": false}, {"term": "Glosar", "kind": "tip", "text": "iască – nume dat mai multor ciuperci parazite în formă de copită de cal, uscate și tari, care cresc pe trunchiurile arborilor.\na purcede – a pleca, a porni la drum.\npripeală – grabă mare.", "examples": [], "important": false}, {"term": "Opoziția iepure – broască (exercițiu)", "kind": "example", "text": "Cele două animale sunt puse în opoziție prin viteză: iepurele este rapid (sprințar), broasca-țestoasă este lentă („cel mai lent și cel mai rapid animal”).", "examples": [], "important": false, "derived": true}], "flashcards": [{"front": "Când a trăit La Fontaine și unde?", "back": "În Franța, în secolul al XVII-lea, în vremea Regelui-Soare, Ludovic al XIV-lea.", "n": [0]}, {"front": "Din ce se inspiră La Fontaine?", "back": "Din creațiile antice ale lui Esop.", "n": [0]}, {"front": "Care este scopul declarat al operelor lui La Fontaine?", "back": "„Să instruiască și să placă”.", "n": [0]}, {"front": "Care sunt cele trei momente ale narațiunii Iepurele și broasca-țestoasă?", "back": "Provocarea, întrecerea și victoria.", "n": [1]}, {"front": "Ce înseamnă Festina lente!?", "back": "„Grăbește-te încet!”", "n": [2]}, {"front": "Ce înseamnă a purcede?", "back": "A pleca, a porni la drum.", "n": [3]}, {"front": "Ce este iasca?", "back": "Nume dat unor ciuperci parazite în formă de copită, care cresc pe trunchiurile arborilor.", "n": [3]}], "quiz": [{"type": "mcq", "q": "Care este scopul declarat al operelor lui La Fontaine?", "options": ["să înfricoșeze", "să instruiască și să placă", "să descrie natura", "să facă reclamă"], "answer": 1, "why": "„Să instruiască și să placă”.", "n": [0]}, {"type": "tf", "q": "La Fontaine a trăit în Franța, în secolul al XVII-lea.", "answer": true, "why": "În vremea Regelui-Soare, Ludovic al XIV-lea.", "n": [0]}, {"type": "fill", "q": "Narațiunea propriu-zisă din Iepurele și broasca-țestoasă are trei momente: provocarea, întrecerea și ____.", "answers": ["victoria"], "why": "Provocare, întrecere, victorie.", "n": [1]}, {"type": "match", "q": "Potrivește cuvântul cu sensul.", "pairs": [["a purcede", "a pleca, a porni la drum"], ["pripeală", "grabă mare"], ["iască", "ciupercă parazită uscată și tare"], ["Festina lente!", "Grăbește-te încet!"]], "n": [3]}, {"type": "mcq", "q": "Ce a făcut La Fontaine cu fabulele lui Esop?", "options": ["le-a copiat identic", "le-a dezvoltat în versuri armonioase, cu dialoguri și secvențe descriptive", "le-a transformat în piese de teatru în proză", "le-a scurtat la două rânduri"], "answer": 1, "why": "Le dezvoltă în versuri armonioase, introduce dialoguri, secvențe descriptive și argumentative.", "n": [0]}, {"type": "tf", "q": "În textul Iepurele și broasca-țestoasă morala apare la începutul textului.", "answer": true, "why": "Textul începe cu versurile: Decât s-alergi e mult mai bine / să pleci la drum când se cuvine!", "n": [1]}, {"type": "mcq", "q": "Care este însușirea care pune cele două animale în opoziție?", "options": ["culoarea", "viteza", "mărimea casei", "vârsta"], "answer": 1, "why": "Iepurele este rapid, broasca-țestoasă este lentă.", "n": [4]}]}, {"id": "u4-l6", "number": 6, "title": "Valori ale culturii populare în spațiul românesc: înțelepciunea proverbelor", "section": "Interculturalitate", "pages": "p. 132-133", "source": "", "theory": [{"term": "Proverbele", "kind": "definition", "text": "Valorile culturii unui popor, concepțiile lui despre viață, natură, soartă, muncă etc. sunt prezente adesea în proverbe, enunțuri scurte și sugestive care concentrează înțelepciunea de veacuri a acelei comunități. Se consideră că proverbele s-au născut în timpuri străvechi, când oamenii au început să-și organizeze traiul în comun conform unor reguli de conduită și unor principii morale. Proverbele au la bază o experiență de viață comună, de aceea multe pot fi întâlnite în forme asemănătoare sau chiar identice la popoare diferite.", "examples": ["Piatra ce se rostogolește nu prinde mușchi. (română)", "A rolling stone gather no moss. (engleză)", "Pierre qui roule n’amasse pas mousse. (franceză)"], "important": true}, {"term": "Forma proverbelor", "kind": "definition", "text": "Prin intermediul proverbelor, oamenii își transmit cultura și valorile într-o formă expresivă, ușor de ținut minte, folosind rime sau figuri de stil.", "examples": ["Lenea e cucoană mare, care cere de mâncare.", "Tăcerea e de aur, vorba e de argint."], "important": true}, {"term": "Proverbe cu semnificațiile lor (exercițiu)", "kind": "example", "text": "„Apa trece, pietrele rămân.” – lucrurile neînsemnate trec și rămân cele importante.\n„După ploaie, vine soare.” – fericirea urmează adesea după un necaz.\n„Meseria e brățară de aur.” – dacă ai o meserie, poți să-ți câștigi existența.\n„Până nu faci foc, nu iese fum.” – un zvon are întotdeauna un sâmbure de adevăr.\n„Râde ciob de oală spartă.” – unii critică defectele altora, dar pe ale lor nu le văd.", "examples": [], "important": false, "derived": true}, {"term": "Actul de limbaj în proverbe (exercițiu)", "kind": "example", "text": "Proverbele pot exprima acte de limbaj: interzicere („Nu-ți băga nasul unde nu-ți fierbe oala!”) sau recomandare („La pomul lăudat să nu te duci cu sacul.”).", "examples": [], "important": false, "derived": true}, {"term": "Proverbe completate (exercițiu)", "kind": "example", "text": "„Zidurile au urechi.”\n„Noaptea, toate pisicile sunt negre.”\n„Cine seamănă vânt culege furtună.”\n„Pisica cu mănuși nu prinde șoareci.”", "examples": [], "important": false, "derived": true}], "flashcards": [{"front": "Ce sunt proverbele?", "back": "Enunțuri scurte și sugestive care concentrează înțelepciunea de veacuri a unei comunități.", "n": [0]}, {"front": "De ce apar proverbe asemănătoare la popoare diferite?", "back": "Pentru că au la bază o experiență de viață comună.", "n": [0]}, {"front": "Cum își transmit oamenii valorile prin proverbe?", "back": "Într-o formă expresivă, ușor de ținut minte, folosind rime sau figuri de stil.", "n": [1]}, {"front": "Ce înseamnă „Apa trece, pietrele rămân”?", "back": "Lucrurile neînsemnate trec și rămân cele importante.", "n": [2]}, {"front": "Ce înseamnă „Meseria e brățară de aur”?", "back": "Dacă ai o meserie, poți să-ți câștigi existența.", "n": [2]}, {"front": "Ce înseamnă „Râde ciob de oală spartă”?", "back": "Unii critică defectele altora, dar pe ale lor nu le văd.", "n": [2]}, {"front": "Ce înseamnă „Până nu faci foc, nu iese fum”?", "back": "Un zvon are întotdeauna un sâmbure de adevăr.", "n": [2]}], "quiz": [{"type": "mcq", "q": "Proverbele sunt:", "options": ["texte lungi în proză", "enunțuri scurte și sugestive care concentrează înțelepciunea unei comunități", "poezii cu strofe", "dialoguri între personaje"], "answer": 1, "why": "Definiția din manual.", "n": [0]}, {"type": "tf", "q": "Multe proverbe se regăsesc în forme asemănătoare sau identice la popoare diferite.", "answer": true, "why": "Au la bază o experiență de viață comună.", "n": [0]}, {"type": "match", "q": "Potrivește proverbul cu semnificația.", "pairs": [["Apa trece, pietrele rămân.", "Lucrurile neînsemnate trec și rămân cele importante."], ["După ploaie, vine soare.", "Fericirea urmează adesea după un necaz."], ["Meseria e brățară de aur.", "Dacă ai o meserie, poți să-ți câștigi existența."], ["Râde ciob de oală spartă.", "Unii critică defectele altora, dar pe ale lor nu le văd."], ["Până nu faci foc, nu iese fum.", "Un zvon are întotdeauna un sâmbure de adevăr."]], "n": [2]}, {"type": "fill", "q": "Completează proverbul: „Zidurile au ____.”", "answers": ["urechi"], "why": "Zidurile au urechi.", "n": [4]}, {"type": "fill", "q": "„Cine seamănă ____ culege furtună.”", "answers": ["vânt"], "why": "Cine seamănă vânt culege furtună.", "n": [4]}, {"type": "tf", "q": "Proverbele folosesc uneori rime sau figuri de stil.", "answer": true, "why": "Exemplu: Tăcerea e de aur, vorba e de argint.", "n": [1]}, {"type": "mcq", "q": "Proverbul „Piatra ce se rostogolește nu prinde mușchi” se spune despre oamenii care:", "options": ["muncesc mult", "se mută mereu și își schimbă meseria evitând responsabilitățile", "sunt foarte bogați", "sunt foarte tăcuți"], "answer": 1, "why": "Așa explică manualul sensul proverbului.", "n": [2]}]}, {"id": "u4-l7", "number": 7, "title": "Dicția în interacțiunile verbale. Inteligența emoțională: exprimarea adecvată a emoțiilor", "section": "Comunicare orală", "pages": "p. 134-135", "source": "", "theory": [{"term": "Dicția", "kind": "definition", "text": "Dicția reprezintă pronunțarea clară și corectă a cuvintelor. În toate interacțiunile verbale, o bună articulare este principala condiție ca un mesaj să fie înțeles. Aceasta înseamnă ca emițătorul să nu vorbească prea repede, înghițind silabele, nici pe un ton prea coborât, ci să rostească deslușit cuvintele, reglându-și debitul verbal. Pe de altă parte, vorbitorul nu trebuie să articuleze cuvintele în mod exagerat, efectul fiind artificial și obositor pentru ascultători.", "examples": [], "important": true}, {"term": "Încurcăturile de limbă", "kind": "tip", "text": "Există numeroase exerciții care pot corecta o dicție defectuoasă, printre ele fiind așa-numitele încurcături de limbă (engl. twisted tongue, fr. virelangue).", "examples": ["Pe cap un capac, pe capac un ac.", "Știu că știi că știuca-i știucă și mai știu că știuca mușcă."], "important": true}, {"term": "Apostroful", "kind": "norm", "text": "În scris, căderea accidentală a unor sunete sau silabe din rostirea neîngrijită, familiară sau populară a unor personaje este redată prin apostrof, un semn ortografic în formă de virgulă, așezat în partea de sus a cuvântului căruia i-au dispărut sunete (omu’ = omul, un’ = unde etc.).", "examples": ["omu’ = omul", "un’ = unde"], "important": true}, {"term": "Inteligența emoțională", "kind": "definition", "text": "Inteligența emoțională reprezintă capacitatea unei ființe umane de a-și înțelege și de a-și folosi emoțiile într-un mod pozitiv. Ea reunește, în mare, trei componente:\n- conștientizarea de sine: a observa propria persoană și a recunoaște sentimentele personale, a-ți cunoaște punctele tari și punctele slabe, a-ți regla stările de spirit;\n- empatia: a înțelege sentimentele altora și preocupările lor, a aborda o situație din perspectiva celorlalți, a ști că oamenii simt și reacționează diferit și a nu-i învinovăți pentru acest motiv;\n- autocontrolul emoțional: a înțelege relația dintre gânduri, reacții și emoții, dintre fapte și consecințe; a găsi metode de a stăpâni sentimentele negative: teama, mânia, tristețea, neliniștea, stresul etc.; a fi mereu motivat pozitiv.", "examples": [], "important": true}], "flashcards": [{"front": "Ce este dicția?", "back": "Pronunțarea clară și corectă a cuvintelor.", "n": [0]}, {"front": "Ce este un apostrof?", "back": "Semn ortografic în formă de virgulă, așezat sus, care arată căderea unor sunete dintr-un cuvânt (omu’ = omul).", "n": [2]}, {"front": "Ce sunt încurcăturile de limbă?", "back": "Exerciții care ajută la corectarea unei dicții defectuoase.", "n": [1]}, {"front": "Ce este inteligența emoțională?", "back": "Capacitatea de a-și înțelege și folosi emoțiile într-un mod pozitiv.", "n": [3]}, {"front": "Care sunt cele trei componente ale inteligenței emoționale?", "back": "Conștientizarea de sine, empatia, autocontrolul emoțional.", "n": [3]}, {"front": "Ce este empatia?", "back": "A înțelege sentimentele altora și preocupările lor, a privi situația din perspectiva celorlalți.", "n": [3]}, {"front": "Ce înseamnă autocontrol emoțional?", "back": "A înțelege relația dintre gânduri, reacții și emoții și a stăpâni sentimentele negative.", "n": [3]}], "quiz": [{"type": "mcq", "q": "Dicția este:", "options": ["viteza de scriere", "pronunțarea clară și corectă a cuvintelor", "alegerea cuvintelor frumoase", "tonul foarte ridicat"], "answer": 1, "why": "Definiția din manual.", "n": [0]}, {"type": "tf", "q": "O bună dicție înseamnă să articulezi cuvintele în mod cât mai exagerat.", "answer": false, "why": "Articularea exagerată este artificială și obositoare.", "n": [0]}, {"type": "fill", "q": "Căderea unor sunete în rostirea familiară se marchează în scris prin ____.", "answers": ["apostrof"], "why": "Apostroful: omu’ = omul.", "n": [2]}, {"type": "match", "q": "Potrivește componenta inteligenței emoționale cu descrierea.", "pairs": [["conștientizarea de sine", "a recunoaște sentimentele personale, punctele tari și slabe"], ["empatia", "a înțelege sentimentele altora"], ["autocontrolul emoțional", "a stăpâni sentimentele negative"]], "n": [3]}, {"type": "mcq", "q": "Ce reprezintă „un’” din enunțul „Un’ se duce băiatu’ ăla?”", "options": ["unde", "unu", "un", "uneori"], "answer": 0, "why": "Apostroful marchează căderea unor sunete: un’ = unde.", "n": [2]}, {"type": "tf", "q": "Încurcăturile de limbă ajută la corectarea unei dicții defectuoase.", "answer": true, "why": "Sunt exerciții pentru dicție.", "n": [1]}, {"type": "classify", "q": "Încadrează situațiile după componenta inteligenței emoționale.", "categories": ["Empatie", "Autocontrol emoțional"], "items": [{"t": "a privi situația din perspectiva celorlalți", "c": 0}, {"t": "a stăpâni mânia", "c": 1}, {"t": "a înțelege sentimentele altora", "c": 0}, {"t": "a stăpâni teama sau stresul", "c": 1}], "n": [3]}]}, {"id": "u4-l8", "number": 8, "title": "Pronumele (actualizare)", "section": "Limbă română", "pages": "p. 136-139", "source": "", "theory": [{"term": "Pronumele personal", "kind": "definition", "text": "Pronumele personal este partea de vorbire care ține locul unui substantiv într-un enunț.", "examples": ["Lupul reprezintă un simbol al cruzimii. – El reprezintă un simbol al cruzimii."], "important": true}, {"term": "Persoana pronumelui", "kind": "classification", "text": "Pronumele are trei persoane, astfel:\n- persoana I – desemnează vorbitorul (eu, noi);\n- persoana a II-a – desemnează ascultătorul (tu, voi);\n- persoana a III-a – desemnează persoana sau obiectul despre ce se vorbește (el/ea, ei/ele).", "examples": ["eu, noi", "tu, voi", "el, ea, ei, ele"], "important": true}, {"term": "Numărul și genul pronumelui", "kind": "rule", "text": "Pronumele are două numere: singular și plural. Genul apare numai la persoana a III-a: masculin (el, ei) și feminin (ea, ele).", "examples": [], "important": true}, {"term": "Formele accentuate și neaccentuate", "kind": "rule", "text": "Toate cazurile au forme accentuate. Pentru cazurile acuzativ și dativ, pronumele personal are, pe lângă forme accentuate, și forme neaccentuate, numite și clitice.", "examples": [], "important": true}, {"term": "Etimologia cuvântului pronume", "kind": "tip", "text": "Cuvântul pronume vine din limba latină (pronomen, din pro însemnând „în loc de”, „pentru” și nomen, adică „nume, substantiv”) și din limba franceză (pronom).", "examples": [], "important": false}, {"term": "Formele pronumelui personal (tabel)", "kind": "classification", "text": "Persoana I: sg. N eu; D mie / îmi, mi; Ac mine / mă, m-. Pl. N noi; D nouă / ne, ni; Ac noi / ne.\nPersoana a II-a: sg. N tu; D ție / îți, ți; Ac tine / te; V tu!. Pl. N voi; D vouă / vă, v-, vi; Ac voi / vă, v-; V voi!.\nPersoana a III-a: sg. m. N el; G lui; D lui / îi, i; Ac el / îl, l-, -l. sg. f. N ea; G ei; D ei / îi, i; Ac ea / o. Pl. m. N ei; G lor; D lor / le, li; Ac ei / îi, i-, -i. Pl. f. N ele; G lor; D lor / le, li; Ac ele / le.\n(La persoanele I și a II-a nu există genitiv. Formele accentuate se scriu înaintea barei, cele neaccentuate/clitice după.)", "examples": [], "important": true}, {"term": "Pronumele personal de politețe", "kind": "definition", "text": "Pronumele personal de politețe (numit și pronume personal de reverență) indică respectul față de o persoană. Acest tip de pronume are forme numai pentru persoana a II-a și pentru persoana a III-a.", "examples": [], "important": true}, {"term": "Gradele de politețe", "kind": "classification", "text": "Pronumele personale de politețe și formulele de reverență exprimă grade diferite de respect: grad redus de politețe (dumneata, dânsul, dânsa etc.), politețe standard (dumneavoastră), grad sporit de politețe (domnia-voastră).", "examples": ["dumneata", "dumneavoastră", "domnia-voastră"], "important": true}, {"term": "Formule de politețe vs. pronume de politețe", "kind": "rule", "text": "Nu trebuie confundate pronumele de politețe domnia-sa, domnia-voastră cu formulele de politețe Domnia Sa, Domnia Voastră, ieșite din uz.", "examples": ["domnia-sa", "Domnia Sa (ieșită din uz)"], "important": true}, {"term": "Formulele reverențioase", "kind": "rule", "text": "Formulele reverențioase sunt folosite în situații de comunicare oficiale sau protocolare și se ortografiază cu majuscule la ambii termeni: Excelența Voastră, Majestatea Voastră, Sfinția Voastră etc.", "examples": ["Excelența Voastră", "Majestatea Voastră", "Sfinția Voastră"], "important": true}, {"term": "Acordul pronumelui dumneavoastră", "kind": "rule", "text": "Pronumele dumneavoastră se folosește întotdeauna cu un verb la persoana a II-a plural, chiar dacă adresarea se face către o singură persoană.", "examples": ["Dumneavoastră sunteți ocupat?"], "important": true}, {"term": "Politețea în vorbirea populară", "kind": "tip", "text": "În vorbirea populară și familiară, există pronume personale de politețe pentru adresarea respectuoasă către cei în vârstă: mata, matale, mătăluță, mătălică, tălică. Pronumele dânsul, dânsa, dânșii, dânsele exprimă grad minim de respect, la persoana a III-a. Regional, în Moldova, sunt folosite ca pronume personale: Dânsa, pisica, unde s-a ascuns?", "examples": ["mata", "matale", "Dânsa, pisica, unde s-a ascuns?"], "important": false}, {"term": "Formele pronumelui personal de politețe (tabel)", "kind": "classification", "text": "Persoana a II-a, singular: grad redus – N-Ac-V dumneata, G-D dumitale; standard – N-Ac-G-D-V dumneavoastră; grad sporit – N-Ac-V domnia-ta, G-D domniei-tale.\nPlural: standard – N-Ac-G-D-V dumneavoastră; grad sporit – N-Ac-V domniile-voastre, G-D domniilor-voastre.\nPersoana a III-a, singular: grad redus – N-Ac m. dânsul, f. dânsa; G-D m. dânsului, f. dânsei; standard – N-Ac-G-D m. dumnealui, f. dumneaei; N-Ac m.-f. dumneasa (rar); G-D m.-f. dumisale; grad sporit – N-Ac domnia-sa (f. domnia-ei, m. domnia-lui, rar); G-D domniei-sale (f. domniei-ei, m. domniei-lui, rar).\nPlural: grad redus – N-Ac m. dânșii, f. dânsele; G-D m. dânșilor, f. dânselor; standard – N-Ac-G-D dumnealor; grad sporit – N-Ac domniile-lor, G-D domniilor-lor.", "examples": [], "important": true}, {"term": "Formule reverențioase pentru persoane (exercițiu)", "kind": "example", "text": "Alteța Sa – prinț/prințesă; Excelența Sa – ambasador; Eminența Sa – cardinal; Majestatea Sa – rege/regină; Preafericirea Sa – patriarh; Sanctitatea Sa – papă; Înaltpreasfinția Sa – mitropolit.", "examples": ["Majestatea Sa – rege/regină", "Excelența Sa – ambasador", "Sanctitatea Sa – papă"], "important": false, "derived": true}, {"term": "Ortograme (exercițiu)", "kind": "norm", "text": "Ortograme de diferențiat: l-a/la, ne-a/nea, ți-i/ții, vi-i/vii.", "examples": ["L-a văzut ieri. / Merge la școală.", "Ne-a spus adevărul. / Nea Ion", "Ți-i dau acum. / Tu ții cartea.", "Vi-i trimit mâine. / Florile sunt vii."], "important": false, "derived": true}, {"term": "Model de analiză a pronumelui (exercițiu)", "kind": "example", "text": "„mi” – pronume personal, persoana I, numărul singular, cazul dativ, formă neaccentuată.", "examples": [], "important": false, "derived": true}], "flashcards": [{"front": "Ce este pronumele personal?", "back": "Partea de vorbire care ține locul unui substantiv într-un enunț.", "n": [0]}, {"front": "Ce persoană desemnează eu / noi?", "back": "Persoana I – vorbitorul.", "n": [1]}, {"front": "Ce persoană desemnează tu / voi?", "back": "Persoana a II-a – ascultătorul.", "n": [1]}, {"front": "La ce persoană apare genul la pronumele personal?", "back": "Numai la persoana a III-a (el, ei / ea, ele).", "n": [2]}, {"front": "Cum se mai numesc formele neaccentuate?", "back": "Clitice.", "n": [3]}, {"front": "Pentru ce cazuri există forme neaccentuate?", "back": "Acuzativ și dativ.", "n": [3]}, {"front": "Care sunt cele trei grade de politețe?", "back": "Redus (dumneata, dânsul), standard (dumneavoastră), sporit (domnia-voastră).", "n": [7]}, {"front": "Cu ce verb se folosește dumneavoastră?", "back": "Cu verb la persoana a II-a plural, chiar dacă adresarea e către o singură persoană.", "n": [10]}, {"front": "Cum se scriu formulele reverențioase?", "back": "Cu majuscule la ambii termeni: Excelența Voastră, Majestatea Voastră.", "n": [9]}, {"front": "Pentru ce persoane există pronume de politețe?", "back": "Numai pentru persoana a II-a și a III-a.", "n": [6]}], "quiz": [{"type": "mcq", "q": "Pronumele personal este partea de vorbire care:", "options": ["arată o însușire", "ține locul unui substantiv", "arată un număr", "exprimă o acțiune"], "answer": 1, "why": "Definiția din manual.", "n": [0]}, {"type": "classify", "q": "Încadrează pronumele după persoană.", "categories": ["Persoana I", "Persoana a II-a", "Persoana a III-a"], "items": [{"t": "eu", "c": 0}, {"t": "noi", "c": 0}, {"t": "tu", "c": 1}, {"t": "voi", "c": 1}, {"t": "ea", "c": 2}, {"t": "ei", "c": 2}], "n": [1]}, {"type": "tf", "q": "Genul pronumelui personal apare la toate cele trei persoane.", "answer": false, "why": "Genul apare numai la persoana a III-a.", "n": [2]}, {"type": "fill", "q": "Formele neaccentuate ale pronumelui personal se mai numesc ____.", "answers": ["clitice"], "why": "Forme neaccentuate = clitice.", "n": [3]}, {"type": "mcq", "q": "Care este pronumele de politețe cu grad sporit de politețe?", "options": ["dumneata", "dânsul", "domnia-voastră", "tu"], "answer": 2, "why": "Domnia-voastră – grad sporit; dumneavoastră – standard; dumneata, dânsul – redus.", "n": [7]}, {"type": "tf", "q": "Pronumele dumneavoastră se folosește cu un verb la persoana a II-a plural, chiar dacă adresarea e către o singură persoană.", "answer": true, "why": "Ex.: Dumneavoastră sunteți ocupat?", "n": [10]}, {"type": "match", "q": "Potrivește forma cu cazul/persoana.", "pairs": [["mie", "dativ, persoana I, singular, accentuat"], ["mine", "acuzativ, persoana I, singular, accentuat"], ["lor", "genitiv/dativ, persoana a III-a, plural"], ["tu!", "vocativ, persoana a II-a, singular"]], "n": [5, 3]}, {"type": "mcq", "q": "Cum se scrie corect formula reverențioasă?", "options": ["majestatea voastră", "Majestatea voastră", "Majestatea Voastră", "majestatea Voastră"], "answer": 2, "why": "Formulele reverențioase se scriu cu majuscule la ambii termeni.", "n": [9]}, {"type": "fill", "q": "Pronumele de politețe au forme numai pentru persoana a II-a și persoana a ____-a.", "answers": ["iii", "iii-a", "treia", "a iii-a"], "why": "Forme numai pentru persoana a II-a și a III-a.", "n": [6]}, {"type": "classify", "q": "Încadrează pronumele de politețe după gradul de politețe.", "categories": ["Grad redus", "Politețe standard", "Grad sporit"], "items": [{"t": "dumneata", "c": 0}, {"t": "dânsa", "c": 0}, {"t": "dumneavoastră", "c": 1}, {"t": "dumnealui", "c": 1}, {"t": "domnia-voastră", "c": 2}, {"t": "domnia-sa", "c": 2}], "n": [7, 12]}, {"type": "tf", "q": "Pronumele de politețe domnia-sa, domnia-voastră trebuie confundate cu formulele de politețe Domnia Sa, Domnia Voastră.", "answer": false, "why": "Nu trebuie confundate: formulele de politețe Domnia Sa, Domnia Voastră sunt ieșite din uz.", "n": [8]}]}, {"id": "u4-l9", "number": 9, "title": "Posibilități combinatorii ale pronumelui. Funcțiile sintactice ale pronumelui. Anticiparea și reluarea unor complemente prin clitice pronominale", "section": "Limbă română", "pages": "p. 140-141", "source": "", "theory": [{"term": "Funcțiile sintactice ale pronumelui", "kind": "definition", "text": "Pronumele personal și pronumele personal de politețe au aceleași funcții sintactice ca substantivul. În enunțuri, pronumele poate apărea în calitate de:\n- centru al unui grup de cuvinte, de exemplu: Dumneata de lângă geam, vino aici!;\n- adjunct într-un grup de cuvinte, de exemplu: cartea de la voi, le-am primit, îmi șoptești etc.", "examples": ["Dumneata de lângă geam, vino aici!", "cartea de la voi"], "important": true}, {"term": "Tabel: funcție sintactică – caz", "kind": "classification", "text": "Subiect – N: Ei au acceptat provocarea. Dumnealor au aflat?\nNume predicativ – N: Mesagerul este el. Câștigătorul sunteți domnia-voastră.\nAtribut pronominal prepozițional – Ac: Moștenirea de la ei s-a risipit. Veștile despre dânșii sunt bune.\nAtribut pronominal genitival – G: Unde a dispărut caietul ei? Scrisoarea dânsei este veche.\nComplement direct – Ac: Pe noi nu ne-a trecut pe listă. Pe dumneavoastră v-am întâlnit ieri?\nComplement prepozițional – Ac: Vorbim despre ele. Ne gândim numai la domniile-lor.\nComplement indirect – D: Le-am spus doar lor vestea. Dumneaei i-ai explicat?\nCircumstanțial de loc – Ac: Plec la ei. Fetița se îndreaptă spre dumneavoastră.\nCircumstanțial de mod – Ac: Procedează ca mine! Vreau să dansez cândva ca domnia-sa.\nCircumstanțial de timp – Ac: Am sosit după voi. Ai ajuns acolo după dumnealor.", "examples": ["Ei au acceptat provocarea. (subiect, N)", "Pe noi nu ne-a trecut pe listă. (complement direct, Ac)", "Le-am spus doar lor vestea. (complement indirect, D)"], "important": true}, {"term": "Anticiparea și reluarea complementelor (clitice)", "kind": "definition", "text": "Formele neaccentuate ale pronumelui personal dublează, în limba română, complementul direct și complementul indirect. Dublarea prin forme neaccentuate/clitice se numește:\n- anticipare, când forma neaccentuată se află înaintea complementului: L-am întrebat pe dânsul. (CD); I-am dat Anei o carte.;\n- reluare, când forma neaccentuată stă după complement: Pe Ana am văzut-o ieri. (CD); Mamei i-am adus o ciocolată. (CI).", "examples": ["L-am întrebat pe dânsul. (anticipare, CD)", "I-am dat Anei o carte. (anticipare, CI)", "Pe Ana am văzut-o ieri. (reluare, CD)", "Mamei i-am adus o ciocolată. (reluare, CI)"], "important": true}, {"term": "Ordinea cliticelor", "kind": "rule", "text": "Dacă apar două forme neaccentuate în aceeași propoziție, cliticul de dativ stă înaintea cliticului de acuzativ: Mi l-a dat ieri. Le-o spune verde în față. Adu-i-le imediat.", "examples": ["Mi l-a dat ieri.", "Le-o spune verde în față.", "Adu-i-le imediat."], "important": true}, {"term": "Model de analiză (exercițiu)", "kind": "example", "text": "„i” – pronume personal, persoana a III-a, numărul singular, genul masculin, cazul dativ, formă neaccentuată, funcție sintactică de complement indirect (reluare).", "examples": [], "important": false, "derived": true}], "flashcards": [{"front": "Ce funcții sintactice au pronumele personale?", "back": "Aceleași ca substantivul: subiect, nume predicativ, atribut, complement direct/indirect/prepozițional, circumstanțial.", "n": [0]}, {"front": "În ce caz stă pronumele subiect?", "back": "Nominativ.", "n": [1]}, {"front": "În ce caz stă pronumele complement indirect?", "back": "Dativ.", "n": [1]}, {"front": "Ce se numește anticipare?", "back": "Când forma neaccentuată (clitic) se află înaintea complementului: L-am întrebat pe dânsul.", "n": [2]}, {"front": "Ce se numește reluare?", "back": "Când forma neaccentuată stă după complement: Pe Ana am văzut-o ieri.", "n": [2]}, {"front": "Care este ordinea a două clitice?", "back": "Cliticul de dativ înaintea celui de acuzativ: Mi l-a dat.", "n": [3]}, {"front": "În ce caz stă atributul pronominal genitival?", "back": "Genitiv: caietul ei.", "n": [1]}, {"front": "În ce caz stă complementul direct exprimat prin pronume?", "back": "Acuzativ: Pe noi nu ne-a trecut pe listă.", "n": [1]}], "quiz": [{"type": "mcq", "q": "În enunțul „Ei au acceptat provocarea.”, pronumele „ei” este:", "options": ["complement direct", "subiect, nominativ", "atribut genitival", "complement indirect"], "answer": 1, "why": "Subiectul stă în nominativ.", "n": [1]}, {"type": "match", "q": "Potrivește exemplul cu funcția sintactică a pronumelui subliniat.", "pairs": [["Mesagerul este el.", "nume predicativ"], ["Unde a dispărut caietul ei?", "atribut pronominal genitival"], ["Plec la ei.", "circumstanțial de loc"], ["Procedează ca mine!", "circumstanțial de mod"], ["Am sosit după voi.", "circumstanțial de timp"]], "n": [1]}, {"type": "classify", "q": "Încadrează exemplele după tipul de dublare a complementului prin clitic.", "categories": ["Anticipare", "Reluare"], "items": [{"t": "L-am întrebat pe dânsul.", "c": 0}, {"t": "I-am dat Anei o carte.", "c": 0}, {"t": "Pe Ana am văzut-o ieri.", "c": 1}, {"t": "Mamei i-am adus o ciocolată.", "c": 1}], "n": [2]}, {"type": "tf", "q": "Dacă apar două clitice în aceeași propoziție, cel de acuzativ stă înaintea celui de dativ.", "answer": false, "why": "Cliticul de dativ stă înaintea celui de acuzativ: Mi l-a dat.", "n": [3]}, {"type": "fill", "q": "Complementul indirect exprimat prin pronume stă în cazul ____.", "answers": ["dativ"], "why": "Complementul indirect – dativ.", "n": [1]}, {"type": "mcq", "q": "Care este atributul pronominal prepozițional?", "options": ["caietul ei", "moștenirea de la ei", "Ei au venit", "Le-am spus lor"], "answer": 1, "why": "De la ei – pronume în acuzativ precedat de prepoziție.", "n": [1]}, {"type": "tf", "q": "Formele neaccentuate ale pronumelui dublează complementul direct și complementul indirect.", "answer": true, "why": "Aceasta este anticiparea sau reluarea prin clitice.", "n": [2]}, {"type": "mcq", "q": "Care enunț ilustrează reluarea complementului direct?", "options": ["L-am întrebat pe dânsul.", "Pe Ana am văzut-o ieri.", "I-am dat Anei o carte.", "Mi l-a dat ieri."], "answer": 1, "why": "Cliticul (o) stă după complementul Pe Ana.", "n": [2]}]}, {"id": "u4-l10", "number": 10, "title": "Pronumele reflexiv", "section": "Limbă română", "pages": "p. 142-143", "source": "", "theory": [{"term": "Pronumele reflexiv", "kind": "definition", "text": "Pronumele reflexiv exprimă identitatea de persoană și de număr dintre obiectul asupra căruia se exercită direct sau indirect acțiunea verbelor și subiectul acestora.", "examples": ["Mama se machiază și își dă cu parfum.", "Amândoi se privesc în oglindă și își zâmbesc."], "important": true}, {"term": "Formele pronumelui reflexiv", "kind": "classification", "text": "În limba română, pronumele reflexiv are forme proprii numai pentru persoana a III-a și pentru cazurile dativ și acuzativ. Aceste forme sunt identice la singular și la plural și nu au categoria genului. Pronumele reflexiv are forme accentuate și forme neaccentuate (clitice):\nAcuzativ – accentuate: (pe) sine; neaccentuate: se, s-.\nDativ – accentuate: sieși, sie; neaccentuate: își, și-.", "examples": ["Se ceartă pe sine.", "Își spune sieși în gând o poveste."], "important": true}, {"term": "Reflexivul la persoanele I și a II-a", "kind": "rule", "text": "La persoana I și a II-a, atât la singular, cât și plural, se împrumută formele neaccentuate ale pronumelor personale de acuzativ și dativ. Formele neaccentuate ale pronumelui la persoana I și a II-a sunt pronume reflexive când au aceeași persoană și același număr cu verbul.", "examples": ["Mă întreb. – mă = reflexiv (I sg. + I sg.)", "Mă întreabă. – mă = personal (I sg. + III sg.)"], "important": true}, {"term": "Model de analiză (exercițiu)", "kind": "example", "text": "„și” – pronume reflexiv, persoana a III-a, numărul singular, cazul dativ, formă neaccentuată.", "examples": [], "important": false, "derived": true}, {"term": "Ortografie: s-a / sa, s-au / sau (exercițiu)", "kind": "norm", "text": "Corecturi din exercițiul 6: Sa spălat → S-a spălat; sa șters → s-a șters; s-a ia spus → i-a spus; Sau încurajat → S-au încurajat; S-au te duci, s-au rămâi → Sau te duci, sau rămâi. Observație: s-a / s-au sunt formate din pronumele reflexiv se + auxiliarul a avea (s-a spălat, s-au încurajat), iar sau este conjuncție care leagă două posibilități.", "examples": ["S-a spălat pe mâini.", "S-au încurajat unii pe alții.", "Sau te duci, sau rămâi."], "important": false, "derived": true}], "flashcards": [{"front": "Ce exprimă pronumele reflexiv?", "back": "Identitatea de persoană și număr dintre obiectul acțiunii și subiectul verbului.", "n": [0]}, {"front": "Pentru ce persoană are pronumele reflexiv forme proprii?", "back": "Numai pentru persoana a III-a.", "n": [1]}, {"front": "Pentru ce cazuri are forme proprii?", "back": "Dativ și acuzativ.", "n": [1]}, {"front": "Care sunt formele reflexive de acuzativ?", "back": "Accentuată: (pe) sine; neaccentuate: se, s-.", "n": [1]}, {"front": "Care sunt formele reflexive de dativ?", "back": "Accentuate: sieși, sie; neaccentuate: își, și-.", "n": [1]}, {"front": "Are pronumele reflexiv gen?", "back": "Nu; formele sunt identice la singular și plural și nu au gen.", "n": [1]}, {"front": "Când e „mă” reflexiv la persoana I?", "back": "Când are aceeași persoană și același număr cu verbul: Mă întreb.", "n": [2]}, {"front": "Când e „mă” pronume personal?", "back": "Când persoana verbului e diferită: Mă întreabă.", "n": [2]}], "quiz": [{"type": "mcq", "q": "Care dintre formele de mai jos este pronume reflexiv de dativ, formă neaccentuată?", "options": ["se", "își", "sine", "sieși"], "answer": 1, "why": "Își, și- = dativ neaccentuat; se, s- = acuzativ neaccentuat; sine = acuzativ accentuat; sieși = dativ accentuat.", "n": [1]}, {"type": "match", "q": "Potrivește forma cu cazul și felul ei.", "pairs": [["sine", "acuzativ, accentuat"], ["se", "acuzativ, neaccentuat"], ["sieși", "dativ, accentuat"], ["își", "dativ, neaccentuat"]], "n": [1]}, {"type": "tf", "q": "Pronumele reflexiv are forme proprii la toate persoanele.", "answer": false, "why": "Are forme proprii numai la persoana a III-a.", "n": [1]}, {"type": "classify", "q": "Precizează dacă pronumele subliniat este personal sau reflexiv.", "categories": ["Personal", "Reflexiv"], "items": [{"t": "Mă întreabă (el).", "c": 0}, {"t": "Mă întreb.", "c": 1}, {"t": "Ne coafăm la fel.", "c": 1}, {"t": "Coafați-ne repede!", "c": 0}, {"t": "Îți impui să faci sport.", "c": 1}, {"t": "Îți impune să faci sport.", "c": 0}], "n": [2]}, {"type": "fill", "q": "Formele neaccentuate ale reflexivului se mai numesc ____.", "answers": ["clitice"], "why": "Forme neaccentuate (clitice).", "n": [1]}, {"type": "mcq", "q": "În „Când se văd, se salută mereu.”, pronumele „se” este:", "options": ["personal, dativ", "reflexiv, acuzativ", "reflexiv, dativ", "personal, acuzativ"], "answer": 1, "why": "Se = reflexiv, persoana a III-a, acuzativ, neaccentuat.", "n": [1, 0]}, {"type": "tf", "q": "În „Mă întreb”, pronumele „mă” este reflexiv pentru că are aceeași persoană și același număr cu verbul.", "answer": true, "why": "Mă – persoana I singular, întreb – persoana I singular.", "n": [2]}, {"type": "mcq", "q": "Cum se scrie corect?", "options": ["Sa spălat pe mâini.", "S-a spălat pe mâini.", "Sa-a spălat pe mâini.", "S a spălat pe mâini."], "answer": 1, "why": "S-a = pronume reflexiv + verbul auxiliar a (a se spăla).", "n": [4]}]}, {"id": "u4-l11", "number": 11, "title": "Numeralul (actualizare). Valorile morfologice ale numeralului", "section": "Limbă română", "pages": "p. 144-145", "source": "", "theory": [{"term": "Numeralul", "kind": "definition", "text": "Numeralul este partea de vorbire care exprimă un număr sau arată ordinea obiectelor prin numărare.", "examples": ["trei cărți", "al doilea an"], "important": true}, {"term": "Numeralul cardinal", "kind": "definition", "text": "Numeralul cardinal exprimă un număr. Din punctul de vedere al structurii, numeralele cardinale sunt:\n- simple: numeralele de la 1 la 10 (unu/una, doi/două, trei, …, nouă, zece);\n- compuse:\na) numeralele de la 11 la 19 (unsprezece, doisprezece etc.);\nb) numeralele compuse cu un numeral de la 2 la 9 + substantivul zeci (douăzeci, treizeci etc.);\nc) numeralele compuse cu un numeral de la 1 la 19 + substantivele sută/sute, mie/mii, milion/milioane, miliard/miliarde (o sută, două mii, trei milioane etc.);\nd) numeralele compuse cu structură mixtă, legate prin și sau prin de (o sută treizeci și patru, douăzeci de mii etc.).", "examples": ["zece", "unsprezece", "douăzeci", "o sută", "două mii", "o sută treizeci și patru", "douăzeci de mii"], "important": true}, {"term": "Genul numeralului cardinal", "kind": "rule", "text": "Numeralele cardinale nu au gen (patru băieți/patru fete), cu excepția numeralelor unu (un)/una (o), doi/două și a compuselor cu acestea: doisprezece băieți/douăsprezece fete.", "examples": ["patru băieți / patru fete", "doisprezece băieți / douăsprezece fete"], "important": true}, {"term": "Numeralul ordinal", "kind": "definition", "text": "Numeralul ordinal exprimă ordinea obiectelor prin numărare. Numeralul ordinal are forme diferite după gen: primul/prima, întâiul/întâia, al doilea/a doua etc.", "examples": ["primul / prima", "întâiul / întâia", "al doilea / a doua"], "important": true}, {"term": "Structura numeralului ordinal", "kind": "rule", "text": "Numeralul ordinal se formează de la un numeral cardinal. Schema din manual (al șaptelea, a șaptea) indică elementele: particulă (al / a), numeral cardinal, articol hotărât și marca numeralului ordinal.", "examples": ["al șaptelea", "a șaptea"], "important": true}, {"term": "Valoarea adjectivală", "kind": "definition", "text": "Numeralele pot avea trei valori. Valoare adjectivală, când se acordă în gen și caz cu un substantiv: trei cai, a doua stradă. De regulă, în această situație numeralul precedă substantivul.\nArticolul demonstrativ care însoțește numeralul cu valoare adjectivală marchează informațiile de gen, număr și caz: cel de-al treilea copil (masculin, singular, N-Ac), celor trei copile/celor trei copii (plural, G-D).\nNumeralele cardinale de la douăzeci în sus se leagă de substantiv prin prepoziția de: douăzeci de copii, treizeci și șapte de caiete. Gruparea numeral cardinal + de are valoare adjectivală, demonstrată de acordul în gen al articolului demonstrativ cu substantivul: cei douăzeci de băieți/cele douăzeci de fete.", "examples": ["trei cai", "a doua stradă", "cel de-al treilea copil", "douăzeci de copii", "cei douăzeci de băieți / cele douăzeci de fete"], "important": true}, {"term": "Valoarea pronominală", "kind": "definition", "text": "Valoare pronominală, când numeralul înlocuiește un substantiv, comportându-se asemenea pronumelui.", "examples": ["Două dintre cărțile împrumutate mi-au plăcut. A treia a fost mai puțin interesantă.", "La concurs s-au înscris trei."], "important": true}, {"term": "Valoarea substantivală", "kind": "definition", "text": "Valoare substantivală, când numeralul apare ca denumire (tramvaiul 34, anul 1848, etajul 1 etc.) sau în enunțurile matematice (Doi plus trei fac cinci.).", "examples": ["tramvaiul 34", "anul 1848", "etajul 1", "Doi plus trei fac cinci.", "vila 4"], "important": true}, {"term": "Norme de corectitudine (exercițiu)", "kind": "norm", "text": "Corecturi din exercițiul 4 „Normă și abatere”: două sute lei → două sute de lei; pagina șaișpe → pagina șaisprezece; la orele zece → la ora zece; clasa a doisprezecea → clasa a douăsprezecea (substantivul clasă este feminin, deci se folosește forma de feminin).", "examples": ["două sute de lei", "pagina șaisprezece", "la ora zece", "clasa a douăsprezecea"], "important": false, "derived": true}], "flashcards": [{"front": "Ce este numeralul?", "back": "Partea de vorbire care exprimă un număr sau arată ordinea obiectelor prin numărare.", "n": [0]}, {"front": "Care sunt numeralele cardinale simple?", "back": "Cele de la 1 la 10.", "n": [1]}, {"front": "Care numerale cardinale au gen?", "back": "Unu/una, doi/două și compusele cu acestea.", "n": [2]}, {"front": "Ce exprimă numeralul ordinal?", "back": "Ordinea obiectelor prin numărare.", "n": [3]}, {"front": "Care este structura lui „al șaptelea”?", "back": "Articol hotărât + particulă + numeral cardinal + marcă a numeralului ordinal.", "n": [4]}, {"front": "Când are numeralul valoare adjectivală?", "back": "Când se acordă în gen și caz cu un substantiv: trei cai, a doua stradă.", "n": [5]}, {"front": "Când are numeralul valoare pronominală?", "back": "Când înlocuiește un substantiv, comportându-se ca pronumele.", "n": [6]}, {"front": "Când are numeralul valoare substantivală?", "back": "Când denumește (tramvaiul 34, anul 1848) sau apare în enunțuri matematice.", "n": [7]}, {"front": "Cu ce prepoziție se leagă numeralele de la douăzeci în sus de substantiv?", "back": "Cu prepoziția de: douăzeci de copii.", "n": [5]}], "quiz": [{"type": "mcq", "q": "Care este numeral cardinal compus?", "options": ["zece", "cinci", "doisprezece", "trei"], "answer": 2, "why": "Numeralele de la 11 la 19 sunt compuse; 1–10 sunt simple.", "n": [1]}, {"type": "classify", "q": "Încadrează numeralele.", "categories": ["Cardinal", "Ordinal"], "items": [{"t": "trei", "c": 0}, {"t": "al doilea", "c": 1}, {"t": "douăzeci", "c": 0}, {"t": "prima", "c": 1}, {"t": "unsprezece", "c": 0}, {"t": "a treia", "c": 1}], "n": [1, 3]}, {"type": "tf", "q": "Toate numeralele cardinale au gen.", "answer": false, "why": "Au gen doar unu/una, doi/două și compusele cu acestea.", "n": [2]}, {"type": "fill", "q": "Numeralele cardinale de la douăzeci în sus se leagă de substantiv prin prepoziția ____.", "answers": ["de"], "why": "douăzeci de copii.", "n": [5]}, {"type": "classify", "q": "Stabilește valoarea morfologică a numeralului subliniat.", "categories": ["Adjectivală", "Pronominală", "Substantivală"], "items": [{"t": "trei cai", "c": 0}, {"t": "A treia a fost mai puțin interesantă.", "c": 1}, {"t": "tramvaiul 34", "c": 2}, {"t": "Doi plus trei fac cinci.", "c": 2}, {"t": "La concurs s-au înscris trei.", "c": 1}, {"t": "a doua stradă", "c": 0}], "n": [5, 6, 7]}, {"type": "mcq", "q": "Care enunț este corect?", "options": ["Aveți de plătit două sute lei.", "Aveți de plătit două sute de lei.", "Aveți de plătit două sute leii.", "Aveți de plătit două sutelei."], "answer": 1, "why": "De la douăzeci în sus numeralul se leagă de substantiv prin „de”.", "n": [5, 8]}, {"type": "tf", "q": "În „cei douăzeci de băieți”, articolul demonstrativ marchează genul, numărul și cazul substantivului.", "answer": true, "why": "Gruparea numeral + de are valoare adjectivală.", "n": [5]}, {"type": "match", "q": "Potrivește exemplul cu valoarea numeralului.", "pairs": [["trei cai", "adjectivală"], ["Două dintre cărți mi-au plăcut.", "pronominală"], ["anul 1848", "substantivală"], ["a doua stradă", "adjectivală"]], "n": [5, 6, 7]}, {"type": "mcq", "q": "Numeralul ordinal se formează:", "options": ["de la un substantiv", "de la un numeral cardinal", "de la un verb", "de la un adverb"], "answer": 1, "why": "Se formează de la un numeral cardinal.", "n": [4]}]}, {"id": "u4-l12", "number": 12, "title": "Inserarea unor secvențe descriptive într-o narațiune", "section": "Redactare", "pages": "p. 146-147", "source": "Adevărata floare - Jean-Claude Carrière; Super! Sunt un gândac! - Ciprian Măceșaru", "theory": [{"term": "Rolul secvențelor descriptive în narațiune", "kind": "definition", "text": "Într-o narațiune, pasajele descriptive încetinesc ritmul desfășurării evenimentelor, dar au întotdeauna o anumită semnificație, fiind în strânsă legătură cu acțiunea și cu personajele.", "examples": [], "important": true}, {"term": "Locul pasajelor descriptive", "kind": "classification", "text": "Pasajele descriptive pot fi situate:\n- la începutul narațiunii, pentru a construi cadrul spațial și temporal al întâmplării (decorul, atmosfera) și pentru a prezenta personajele, anunțând rolul lor în desfășurarea evenimentelor;\n- în interiorul narațiunii, pentru a oferi informații necesare înțelegerii întâmplărilor relatate, prin descrierea unui personaj, a unui peisaj, a unui loc sau a unui obiect;\n- la sfârșitul narațiunii, pentru a pune în evidență semnificația deznodământului.", "examples": [], "important": true}, {"term": "Timpurile verbale în narațiune și descriere", "kind": "rule", "text": "Spre deosebire de narațiune, în care timpul predominant al verbelor este perfectul compus sau perfectul simplu, în descriere se folosește imperfectul sau prezentul.", "examples": [], "important": true}, {"term": "Cine realizează descrierea", "kind": "rule", "text": "Descrierea inserată într-un text narativ la persoana a III-a poate fi realizată de narator sau de un personaj.", "examples": [], "important": true}, {"term": "Pașii redactării (sarcina din Aplicații)", "kind": "tip", "text": "Pașii din sarcina de redactare: păstrează situația inițială și personajele; identifică 2-3 urmări posibile și alege-o pe cea potrivită; concepe un deznodământ care oferă soluția problemei; stabilește locul secvențelor descriptive (folosește enumerații, epitete, comparații); păstrează timpul verbal din text, iar în descrieri folosește imperfectul; scrie o primă variantă și dă-i un titlu; revizuiește (claritatea ideilor, paragrafe, gramatică, ortografie, punctuație); scrie varianta finală, lizibilă.", "examples": ["colorate în zeci de nuanțe", "strălucitoare ca pietrele prețioase"], "important": false, "derived": true}], "flashcards": [{"front": "Cum influențează descrierea ritmul narațiunii?", "back": "Încetinește ritmul desfășurării evenimentelor.", "n": [0]}, {"front": "Unde pot fi situate pasajele descriptive?", "back": "La început, în interior sau la sfârșitul narațiunii.", "n": [1]}, {"front": "Rolul descrierii la începutul narațiunii?", "back": "Construiește cadrul spațial și temporal și prezintă personajele.", "n": [1]}, {"front": "Rolul descrierii la sfârșitul narațiunii?", "back": "Pune în evidență semnificația deznodământului.", "n": [1]}, {"front": "Ce timpuri predomină în narațiune?", "back": "Perfectul compus sau perfectul simplu.", "n": [2]}, {"front": "Ce timpuri se folosesc în descriere?", "back": "Imperfectul sau prezentul.", "n": [2]}, {"front": "Cine poate realiza descrierea într-un text la persoana a III-a?", "back": "Naratorul sau un personaj.", "n": [3]}], "quiz": [{"type": "mcq", "q": "Pasajele descriptive dintr-o narațiune:", "options": ["accelerează acțiunea", "încetinesc ritmul desfășurării evenimentelor", "înlocuiesc personajele", "elimină naratorul"], "answer": 1, "why": "Încetinesc ritmul, dar au întotdeauna o anumită semnificație.", "n": [0]}, {"type": "tf", "q": "În descriere se folosesc imperfectul sau prezentul.", "answer": true, "why": "În narațiune predomină perfectul compus sau simplu.", "n": [2]}, {"type": "fill", "q": "În narațiune, timpul predominant al verbelor este perfectul compus sau perfectul ____.", "answers": ["simplu"], "why": "Perfect compus sau perfect simplu.", "n": [2]}, {"type": "classify", "q": "Încadrează rolul după locul pasajului descriptiv.", "categories": ["La început", "În interior", "La sfârșit"], "items": [{"t": "construiește cadrul spațial și temporal", "c": 0}, {"t": "oferă informații necesare înțelegerii întâmplărilor", "c": 1}, {"t": "pune în evidență semnificația deznodământului", "c": 2}, {"t": "prezintă personajele și anunță rolul lor", "c": 0}], "n": [1]}, {"type": "tf", "q": "Descrierea într-un text narativ la persoana a III-a poate fi realizată doar de un personaj.", "answer": false, "why": "Poate fi realizată de narator sau de un personaj.", "n": [3]}, {"type": "mcq", "q": "Care dintre următoarele NU este un loc potrivit pentru un pasaj descriptiv?", "options": ["la începutul narațiunii", "în interiorul narațiunii", "la sfârșitul narațiunii", "niciunul – toate sunt potrivite"], "answer": 3, "why": "Descrierea poate fi la început, în interior sau la sfârșit.", "n": [1]}]}, {"id": "u4-l13", "number": 13, "title": "Textul explicativ", "section": "Redactare", "pages": "p. 148-149", "source": "Uliii și porumbeii (joc); De ce au elefanții trompă? - Michaela Strachan", "theory": [{"term": "Textul explicativ", "kind": "definition", "text": "Textul explicativ oferă informații organizate într-un domeniu particular al cunoașterii, având ca scop înțelegerea unui fenomen, a unui fapt, a unei situații. Textul explicativ are două tipuri de realizare:\n- cauzal, când răspunde la întrebarea de ce? (explicație privind fenomene, evenimente, idei etc.);\n- procedural, când răspunde la întrebarea cum? (explicarea unor pași ce trebuie parcurși pentru a realiza: un obiect, un experiment, un desen, o mâncare etc.).", "examples": ["De ce au elefanții trompă? (cauzal)", "Regulile jocului Uliii și porumbeii (procedural)"], "important": true}, {"term": "Textul explicativ cauzal", "kind": "definition", "text": "Din categoria textelor explicative cauzale, fac parte articolele de dicționar, unele texte din manuale școlare, enciclopedii, unele texte din presă. Ele pot apărea și în textele literare. Explicațiile sunt introduse prin formulări care exprimă: cauza (fiindcă, pentru că, din motivul, de aceea etc.), consecința/concluzia (așadar, ca urmare etc.), o explicație suplimentară (mai exact, adică etc.).", "examples": ["fiindcă", "pentru că", "așadar", "ca urmare", "mai exact", "adică"], "important": true}, {"term": "Textul explicativ procedural", "kind": "definition", "text": "Din categoria textelor explicative procedurale, fac parte rețetele, instrucțiunile de diverse tipuri, prospectele. Aceste texte sunt organizate în părți distincte, evidențiate de marcatori sau de cuvinte scrise colorat și îngroșat, pentru a puncta ideile cele mai importante. Așezarea în pagină este, uneori, legată de imagini care completează explicațiile. Verbele sunt folosite, de regulă, la modul indicativ, timpul prezent, persoana a III-a. Unele instrucțiuni pot utiliza și modul imperativ sau infinitivul.", "examples": ["rețete", "reguli de joc", "prospecte"], "important": true}, {"term": "Cuvinte de legătură în explicație (exercițiu)", "kind": "tip", "text": "Pentru De ce...?: cauze și consecințe în ordine logică, cu cuvinte ca adică, cu alte cuvinte, fiindcă, mai exact, pentru că. Pentru Cum...?: resursele necesare și pașii în ordinea corectă, cu cuvinte ca: mai întâi, apoi, în cele din urmă. Se folosește vocabular precis, adaptat receptorului, imagini/tabele/marcatori, verbe la imperativ și/sau indicativ prezent.", "examples": ["mai întâi", "apoi", "în cele din urmă"], "important": false, "derived": true}], "flashcards": [{"front": "Ce este textul explicativ?", "back": "Text care oferă informații organizate dintr-un domeniu, pentru înțelegerea unui fenomen, fapt sau situații.", "n": [0]}, {"front": "Care sunt cele două tipuri de text explicativ?", "back": "Cauzal (de ce?) și procedural (cum?).", "n": [0]}, {"front": "La ce întrebare răspunde textul explicativ cauzal?", "back": "De ce?", "n": [0]}, {"front": "La ce întrebare răspunde textul explicativ procedural?", "back": "Cum?", "n": [0]}, {"front": "Exemple de texte explicative procedurale", "back": "Rețete, instrucțiuni, prospecte.", "n": [2]}, {"front": "Cuvinte care introduc cauza", "back": "Fiindcă, pentru că, din motivul, de aceea.", "n": [3]}, {"front": "Cuvinte care introduc consecința/concluzia", "back": "Așadar, ca urmare.", "n": [3]}, {"front": "Cuvinte care introduc o explicație suplimentară", "back": "Mai exact, adică.", "n": [3]}, {"front": "Ce moduri și timp au de regulă verbele în textele procedurale?", "back": "Indicativ prezent, persoana a III-a; uneori imperativ sau infinitiv.", "n": [2]}], "quiz": [{"type": "mcq", "q": "Textul explicativ procedural răspunde la întrebarea:", "options": ["de ce?", "cum?", "cine?", "când?"], "answer": 1, "why": "Procedural = cum? (pași de parcurs).", "n": [0]}, {"type": "classify", "q": "Încadrează textele.", "categories": ["Explicativ cauzal", "Explicativ procedural"], "items": [{"t": "articol de dicționar", "c": 0}, {"t": "rețetă", "c": 1}, {"t": "regulile unui joc", "c": 1}, {"t": "text de enciclopedie", "c": 0}, {"t": "prospect", "c": 1}], "n": [1, 2]}, {"type": "tf", "q": "Textul explicativ cauzal răspunde la întrebarea „de ce?”.", "answer": true, "why": "Explică cauze ale unor fenomene, evenimente, idei.", "n": [0]}, {"type": "fill", "q": "Cuvintele „așadar” și „ca urmare” introduc o ____ sau concluzie.", "answers": ["consecință", "consecinta"], "why": "Consecința/concluzia.", "n": [3]}, {"type": "match", "q": "Potrivește cuvintele cu rolul lor.", "pairs": [["fiindcă", "cauză"], ["așadar", "consecință/concluzie"], ["mai exact", "explicație suplimentară"], ["pentru că", "cauză"]], "n": [3]}, {"type": "mcq", "q": "Verbele din textele procedurale sunt, de regulă, la:", "options": ["conjunctiv", "indicativ prezent, persoana a III-a", "condițional-optativ", "gerunziu"], "answer": 1, "why": "Unele instrucțiuni folosesc și imperativul sau infinitivul.", "n": [2]}, {"type": "tf", "q": "Textele explicative procedurale sunt organizate în părți distincte, evidențiate de marcatori sau cuvinte colorate și îngroșate.", "answer": true, "why": "Pentru a puncta ideile principale.", "n": [2]}, {"type": "mcq", "q": "Care este un conector pentru etapele unui proces?", "options": ["fiindcă", "mai întâi", "așadar", "adică"], "answer": 1, "why": "Mai întâi, apoi, în cele din urmă marchează etapele pașilor.", "n": [3]}]}]}, {"unit": {"id": "u5", "number": 5, "title": "Călătorii de tot felul", "summary": "Textul narativ literar (acțiune, spațiu, timp, dialog, personaje, comic), textul argumentativ, limba română în Europa, actele de limbaj, parafrazarea, adjectivul, adverbul și transformarea vorbirii directe în vorbire indirectă."}, "lessons": [{"id": "u5-l1", "number": 1, "title": "Textul narativ literar", "section": "Lectură", "pages": "p. 154-157", "source": "D-l Goe... - I.L. Caragiale", "theory": [{"term": "I.L. Caragiale (1852-1912)", "kind": "tip", "text": "Scriitor din a doua jumătate a secolului al XIX-lea. Este unul dintre reprezentanții de seamă ai literaturii române, alături de Mihai Eminescu, Ion Creangă și Ioan Slavici. A scris piese de teatru și texte narative. Este considerat cel mai mare dramaturg român, piesele sale, dintre care fac parte O noapte furtunoasă, O scrisoare pierdută și D-ale carnavalului, fiind permanent jucate și reinterpretate pe marile scene.", "examples": ["O noapte furtunoasă", "O scrisoare pierdută", "D-ale carnavalului"], "important": false}, {"term": "D-l Goe... (publicare)", "kind": "tip", "text": "Textul D-l Goe... a fost publicat în ziarul Universul din 12 mai 1900 și apoi inclus în volumul Momente și schițe, apărut în anul următor.", "examples": [], "important": false}], "flashcards": [{"front": "Cine este autorul textului D-l Goe...?", "back": "I.L. Caragiale", "n": [1]}, {"front": "În ce ziar a fost publicat D-l Goe... și când?", "back": "Universul, 12 mai 1900", "n": [1]}, {"front": "În ce volum a fost inclus D-l Goe...?", "back": "Momente și schițe (apărut în anul următor)", "n": [1]}, {"front": "Cu ce scriitori este I.L. Caragiale reprezentant de seamă al literaturii române?", "back": "Mihai Eminescu, Ion Creangă, Ioan Slavici", "n": [0]}, {"front": "Ce este considerat I.L. Caragiale în literatura română?", "back": "Cel mai mare dramaturg român", "n": [0]}], "quiz": [{"type": "mcq", "q": "În ce ziar a fost publicat textul D-l Goe...?", "options": ["Scânteia", "Universul", "Timpul", "Românul"], "answer": 1, "why": "Textul a apărut în Universul din 12 mai 1900.", "n": [1]}, {"type": "tf", "q": "I.L. Caragiale a scris doar proză, nu și piese de teatru.", "answer": false, "why": "A scris piese de teatru și texte narative.", "n": [0]}, {"type": "fill", "q": "D-l Goe... a fost inclus în volumul ____ și schițe.", "answers": ["momente"], "why": "Volumul se numește Momente și schițe.", "n": [1]}, {"type": "match", "q": "Potrivește piesa cu autorul/tipul de operă.", "pairs": [["O scrisoare pierdută", "piesă de teatru de I.L. Caragiale"], ["D-l Goe...", "text narativ (schiță) de I.L. Caragiale"], ["Momente și schițe", "volum de I.L. Caragiale"]], "n": [0, 1]}, {"type": "mcq", "q": "În ce a doua jumătate de secol a activat I.L. Caragiale?", "options": ["a secolului al XVIII-lea", "a secolului al XIX-lea", "a secolului al XX-lea", "a secolului al XVII-lea"], "answer": 1, "why": "Este scriitor din a doua jumătate a secolului al XIX-lea.", "n": [0]}]}, {"id": "u5-l2", "number": 2, "title": "Acțiunea, spațiul și timpul", "section": "Lectură", "pages": "p. 158-159", "source": "D-l Goe... - I.L. Caragiale", "theory": [{"term": "Textul narativ de dimensiuni reduse (schița)", "kind": "definition", "text": "Există texte narative de dimensiuni reduse, a căror acțiune este limitată la un singur eveniment semnificativ din viața personajelor. În aceste texte, spațiul desfășurării întâmplărilor este restrâns, timpul este limitat, ritmul acțiunii este alert, iar detaliile, deși puține, sunt semnificative. Multe dintre textele narative ale lui I.L. Caragiale, incluse în volumul Momente și schițe, au aceste trăsături.", "examples": ["D-l Goe..."], "important": true}], "flashcards": [{"front": "La câte evenimente se referă acțiunea unui text narativ de dimensiuni reduse?", "back": "La un singur eveniment semnificativ din viața personajelor", "n": [0]}, {"front": "Cum este spațiul într-un text narativ scurt (schiță)?", "back": "Restrâns", "n": [0]}, {"front": "Cum este timpul într-un text narativ scurt?", "back": "Limitat", "n": [0]}, {"front": "Cum este ritmul acțiunii într-o schiță?", "back": "Alert", "n": [0]}, {"front": "Cum sunt detaliile într-o schiță?", "back": "Puține, dar semnificative", "n": [0]}], "quiz": [{"type": "tf", "q": "Într-un text narativ de dimensiuni reduse, acțiunea se referă la un singur eveniment semnificativ.", "answer": true, "why": "Acțiunea este limitată la un singur eveniment semnificativ din viața personajelor.", "n": [0]}, {"type": "mcq", "q": "Care dintre următoarele NU este trăsătură a textelor narative de dimensiuni reduse?", "options": ["spațiu restrâns", "timp limitat", "ritm lent al acțiunii", "detalii puține, dar semnificative"], "answer": 2, "why": "Ritmul acțiunii este alert, nu lent.", "n": [0]}, {"type": "fill", "q": "În textele narative scurte, spațiul desfășurării întâmplărilor este ____.", "answers": ["restrâns"], "why": "Spațiul este restrâns.", "n": [0]}, {"type": "fill", "q": "În textele narative scurte, ritmul acțiunii este ____.", "answers": ["alert"], "why": "Ritmul este alert.", "n": [0]}, {"type": "classify", "q": "Încadrează trăsăturile după cum aparțin sau nu unei schițe.", "categories": ["Trăsătură a schiței", "Nu este trăsătură a schiței"], "items": [{"t": "un singur eveniment semnificativ", "c": 0}, {"t": "spațiu restrâns", "c": 0}, {"t": "timp limitat", "c": 0}, {"t": "mai multe evenimente fără legătură, pe ani de zile", "c": 1}, {"t": "ritm alert", "c": 0}], "n": [0]}, {"type": "match", "q": "Potrivește elementul cu caracteristica lui în schiță.", "pairs": [["acțiunea", "limitată la un singur eveniment semnificativ"], ["spațiul", "restrâns"], ["timpul", "limitat"], ["ritmul acțiunii", "alert"]], "n": [0]}]}, {"id": "u5-l3", "number": 3, "title": "Dialogul în textul literar", "section": "Lectură", "pages": "p. 160-161", "source": "D-l Goe... - I.L. Caragiale", "theory": [{"term": "Dialogul", "kind": "definition", "text": "Dialogul este comunicarea verbală dintre două sau mai multe persoane care își transmit informații în diverse scopuri. Intervenția în dialog a unui partener de discuție se numește replică. Dialogul este alcătuit dintr-o succesiune de cel puțin două replici legate logic între ele.", "examples": [], "important": true}, {"term": "Dialogul în opera literară", "kind": "definition", "text": "În opera literară, dialogul este un procedeu prin care se imită dialogul real și prin care este reprodusă o discuție dintre două sau mai multe personaje. Intervenția unui personaj se marchează în scris prin linie de dialog.", "examples": [], "important": true}, {"term": "Verbele de declarație", "kind": "definition", "text": "Semnalarea replicilor se face prin verbe de declarație. Din categoria acestor verbe fac parte: a zice, a spune, a întreba, a răspunde, a adăuga, a exclama, a striga, a ruga etc.", "examples": ["zice mam’ mare", "adaogă tanti Mița"], "important": false}, {"term": "Poziția verbelor de declarație", "kind": "rule", "text": "Verbele de declarație pot apărea:\n- înaintea replicii unui personaj, fiind urmate de semnul două-puncte;\n- după replica unui personaj, fiind precedate de virgulă, de puncte de suspensie, de semnul exclamării sau de semnul întrebării;\n- în interiorul replicii unui personaj, fiind izolate prin virgule sau prin linii de pauză.", "examples": [], "important": false}, {"term": "Elemente nonverbale și paraverbale în textul literar", "kind": "rule", "text": "Elementele nonverbale și cele paraverbale din comunicarea orală sunt semnalate în textul literar prin cuvinte sau grupuri de cuvinte ce se referă la mimica, gestica, privirea personajelor sau la debitul lor verbal, la intensitatea vocală, la pauzele făcute de acestea.", "examples": [], "important": false}, {"term": "Rolul semnelor de punctuație în dialog", "kind": "rule", "text": "În dialogul dintr-un text literar, semnele de punctuație au diverse roluri:\n! sugerează emoția, surpriza, furia, starea de nervozitate etc.;\n? marchează o întrebare sau nedumerire;\n... marchează ezitările, întreruperile sau pauzele în vorbire ale personajelor.", "examples": ["Să opreascăăă!!!"], "important": false}], "flashcards": [{"front": "Ce este dialogul?", "back": "Comunicarea verbală dintre două sau mai multe persoane care își transmit informații în diverse scopuri.", "n": [0]}, {"front": "Cum se numește intervenția unui partener în dialog?", "back": "Replică", "n": [0]}, {"front": "Din câte replici se alcătuiește, minimum, un dialog?", "back": "Cel puțin două replici legate logic între ele", "n": [0]}, {"front": "Prin ce se marchează în scris intervenția unui personaj?", "back": "Prin linia de dialog", "n": [1]}, {"front": "Dă exemple de verbe de declarație.", "back": "a zice, a spune, a întreba, a răspunde, a adăuga, a exclama, a striga, a ruga", "n": [2]}, {"front": "Ce marchează punctele de suspensie în dialog?", "back": "Ezitările, întreruperile sau pauzele în vorbire", "n": [5]}, {"front": "Ce sugerează semnul exclamării în dialog?", "back": "Emoția, surpriza, furia, nervozitatea", "n": [5]}], "quiz": [{"type": "mcq", "q": "Cum se numește intervenția unui partener de discuție într-un dialog?", "options": ["narațiune", "replică", "descriere", "monolog"], "answer": 1, "why": "Intervenția în dialog a unui partener se numește replică.", "n": [0]}, {"type": "tf", "q": "Un dialog este alcătuit din cel puțin două replici legate logic între ele.", "answer": true, "why": "Aceasta este definiția din manual.", "n": [0]}, {"type": "tf", "q": "În textul literar, intervenția unui personaj se marchează prin ghilimele duble în mijlocul rândului.", "answer": false, "why": "Se marchează prin linie de dialog.", "n": [1]}, {"type": "fill", "q": "Intervenția unui personaj se marchează în scris prin ____ de dialog.", "answers": ["linie", "linia"], "why": "Se folosește linia de dialog.", "n": [1]}, {"type": "mcq", "q": "Ce marchează punctele de suspensie la finalul unei replici?", "options": ["furia", "întrebarea", "ezitările, întreruperile sau pauzele", "bucuria"], "answer": 2, "why": "... marchează ezitările, întreruperile sau pauzele în vorbire.", "n": [5]}, {"type": "match", "q": "Potrivește semnul de punctuație cu rolul lui în dialog.", "pairs": [["!", "sugerează emoția, surpriza, furia"], ["?", "marchează o întrebare sau nedumerire"], ["...", "marchează ezitările, întreruperile sau pauzele"]], "n": [5]}, {"type": "classify", "q": "Încadrează cuvintele.", "categories": ["Verb de declarație", "Nu este verb de declarație"], "items": [{"t": "a zice", "c": 0}, {"t": "a răspunde", "c": 0}, {"t": "a striga", "c": 0}, {"t": "a alerga", "c": 1}, {"t": "a adăuga", "c": 0}, {"t": "a dormi", "c": 1}], "n": [2]}, {"type": "mcq", "q": "Când verbul de declarație apare înaintea replicii, după el se pune:", "options": ["virgulă", "două-puncte", "punct și virgulă", "semnul întrebării"], "answer": 1, "why": "Verbele care apar înaintea replicii sunt urmate de semnul două-puncte.", "n": [3]}, {"type": "mcq", "q": "Prin ce sunt semnalate în textul literar elementele nonverbale și paraverbale din comunicarea orală?", "options": ["prin cuvinte sau grupuri de cuvinte care se referă la mimica, gestica, privirea sau la intensitatea vocală a personajelor", "prin ghilimele duble", "prin schimbarea fontului textului", "prin numerotarea replicilor"], "answer": 0, "why": "Aceste elemente sunt semnalate prin cuvinte sau grupuri de cuvinte ce se referă la mimică, gestică, privire, debit verbal, intensitate vocală, pauze.", "n": [4]}]}, {"id": "u5-l4", "number": 4, "title": "Personajele", "section": "Lectură", "pages": "p. 162-163", "source": "D-l Goe... - I.L. Caragiale", "theory": [{"term": "Figuranții", "kind": "definition", "text": "Figuranții sunt personaje prezente la desfășurarea unor întâmplări ca simpli martori, rolul lor în acțiune fiind foarte scăzut.", "examples": [], "important": true}, {"term": "Modalități de caracterizare a personajului", "kind": "rule", "text": "Trăsăturile unui personaj pot fi numite în text de narator, de celelalte personaje sau de el însuși ori pot fi deduse din faptele personajului, din atitudinea sa, din modul în care se comportă sau vorbește.", "examples": [], "important": true}, {"term": "Rolul dialogului în caracterizare", "kind": "rule", "text": "Prin dialog, adică prin modul în care se exprimă, prin modul în care se raportează la celelalte personaje, prin subiectele abordate, prin ritmul vorbirii și prin tonul vocii, personajele își dezvăluie felul de a fi, de a gândi, de a se comporta, dar și atitudinile sau gradul de cultură.", "examples": [], "important": true}, {"term": "Detalii care însoțesc replicile", "kind": "rule", "text": "Verbele de declarație și indicii referitori la gesturile, mimica și la tonul vocii personajului sunt detalii care însoțesc replicile, oferind informații despre trăsăturile personajului.", "examples": [], "important": true}], "flashcards": [{"front": "Ce sunt figuranții?", "back": "Personaje prezente la întâmplări ca simpli martori, cu rol foarte scăzut în acțiune.", "n": [0]}, {"front": "Cum pot fi aflate trăsăturile unui personaj?", "back": "Prin narator, prin alte personaje, prin autocaracterizare sau prin fapte, atitudine, comportament, vorbire.", "n": [1]}, {"front": "Ce dezvăluie personajele prin dialog?", "back": "Felul de a fi, de a gândi, de a se comporta, atitudinile și gradul de cultură.", "n": [2]}, {"front": "Ce informații oferă verbele de declarație și indicii despre gesturi, mimică și ton?", "back": "Informații despre trăsăturile personajului.", "n": [3]}], "quiz": [{"type": "mcq", "q": "Care este rolul figuranților în acțiune?", "options": ["foarte important", "foarte scăzut", "decisiv", "aceleași ca al personajului principal"], "answer": 1, "why": "Figuranții sunt simpli martori, cu rol foarte scăzut.", "n": [0]}, {"type": "tf", "q": "Trăsăturile unui personaj pot fi deduse și din faptele lui.", "answer": true, "why": "Trăsăturile pot fi deduse din fapte, atitudine, comportament, vorbire.", "n": [1]}, {"type": "tf", "q": "Trăsăturile unui personaj pot fi numite doar de narator.", "answer": false, "why": "Pot fi numite și de alte personaje sau de personaj însuși, ori deduse din fapte.", "n": [1]}, {"type": "fill", "q": "____ sunt personaje prezente ca simpli martori, cu rol foarte scăzut în acțiune.", "answers": ["figuranții", "figuranti", "figuranții."], "why": "Aceasta este definiția figuranților.", "n": [0]}, {"type": "classify", "q": "Cum află cititorul trăsăturile personajului?", "categories": ["Direct (numite)", "Indirect (deduse)"], "items": [{"t": "naratorul spune cum este personajul", "c": 0}, {"t": "alt personaj îl numește „încăpățânat”", "c": 0}, {"t": "din faptele lui", "c": 1}, {"t": "din modul în care vorbește", "c": 1}, {"t": "din atitudinea față de alții", "c": 1}], "n": [1]}, {"type": "match", "q": "Potrivește elementul cu ce ne arată despre personaj.", "pairs": [["verbele de declarație și gesturile", "detalii care însoțesc replicile"], ["dialogul", "dezvăluie felul de a fi, atitudinile, gradul de cultură"], ["figuranții", "martori cu rol foarte scăzut"], ["trăsăturile personajului", "numite de narator, de alte personaje, de el însuși sau deduse din fapte"]], "n": [2, 3]}]}, {"id": "u5-l5", "number": 5, "title": "Semnificațiile textului", "section": "Lectură", "pages": "p. 164-165", "source": "D-l Goe... - I.L. Caragiale", "theory": [{"term": "Comicul", "kind": "definition", "text": "În categoria comicului intră actele de limbaj, situațiile sau personajele din viață ori din artă care provoacă râsul. În textul D-l Goe..., comicul se realizează prin contrastul dintre aparență și esență, dintre vechi și nou, dintre efort și rezultatul lui.", "examples": ["Mam’ mare își face cruce, apoi aprinde o țigară..."], "important": false}, {"term": "Ironia", "kind": "definition", "text": "Ironia este o formă a comicului realizată prin cuvinte, fraze, expresii, afirmații care sunt opusul a ceea ce gândește în realitate cineva. În textul studiat, ironia poate fi sesizată în atitudinea naratorului față de personaje.", "examples": ["Dar nu e vreme de discuții filologice: sosește trenul..."], "important": false}, {"term": "Titlul D-l Goe...", "kind": "tip", "text": "Titlul textului este alcătuit din prescurtarea din epoca respectivă a substantivului domnul și numele personajului principal, un nume de alint, probabil de la Gheorghe, urmat de puncte de suspensie. Inițial, Caragiale intenționase să-și intituleze textul 10 Mai.", "examples": ["D-l = domnul", "Goe = nume de alint, probabil de la Gheorghe"], "important": false}], "flashcards": [{"front": "Ce este comicul?", "back": "Actele de limbaj, situațiile sau personajele din viață ori din artă care provoacă râsul.", "n": [0]}, {"front": "Prin ce contraste se realizează comicul în D-l Goe...?", "back": "Aparență-esență, vechi-nou, efort-rezultatul lui.", "n": [0]}, {"front": "Ce este ironia?", "back": "Formă a comicului realizată prin cuvinte, fraze, expresii, afirmații care sunt opusul a ceea ce gândește cineva în realitate.", "n": [1]}, {"front": "Unde se observă ironia în D-l Goe...?", "back": "În atitudinea naratorului față de personaje.", "n": [1]}, {"front": "Ce înseamnă „D-l” din titlu?", "back": "Prescurtarea din epocă a lui „domnul”.", "n": [2]}, {"front": "Cum voia inițial Caragiale să intituleze textul?", "back": "10 Mai", "n": [2]}], "quiz": [{"type": "mcq", "q": "Ironia este o formă a comicului în care cuvintele exprimă:", "options": ["exact ce gândește vorbitorul", "opusul a ceea ce gândește în realitate cineva", "doar întrebări", "doar exclamații"], "answer": 1, "why": "Ironia = opusul a ceea ce gândește în realitate cineva.", "n": [1]}, {"type": "tf", "q": "Comicul din D-l Goe... se bazează, printre altele, pe contrastul dintre aparență și esență.", "answer": true, "why": "Alte contraste: vechi-nou, efort-rezultat.", "n": [0]}, {"type": "fill", "q": "Titlul inițial al textului, gândit de Caragiale, era ____ Mai.", "answers": ["10", "zece"], "why": "Autorul intenționase titlul 10 Mai.", "n": [2]}, {"type": "mcq", "q": "Care este sensul lui „Goe” din titlu?", "options": ["numele de familie al personajului", "un nume de alint, probabil de la Gheorghe", "numele unui oraș", "numele autorului"], "answer": 1, "why": "Goe este un nume de alint, probabil de la Gheorghe.", "n": [2]}, {"type": "classify", "q": "Încadrează contrastele.", "categories": ["Contrast care produce comic în text", "Nu este menționat ca sursă a comicului"], "items": [{"t": "aparență - esență", "c": 0}, {"t": "vechi - nou", "c": 0}, {"t": "efort - rezultatul lui", "c": 0}, {"t": "zi - noapte", "c": 1}], "n": [0]}, {"type": "match", "q": "Potrivește termenul cu explicația.", "pairs": [["comic", "provoacă râsul"], ["ironie", "exprimarea opusului a ceea ce gândești"], ["D-l", "prescurtare pentru domnul"]], "n": [0, 1, 2]}]}, {"id": "u5-l6", "number": 6, "title": "Textul argumentativ", "section": "Lectură", "pages": "p. 166-167", "source": "Motive pentru care călătoriile te fac mai bun - Samantha Fanelli", "theory": [], "flashcards": [], "quiz": []}, {"id": "u5-l7", "number": 7, "title": "Organizarea textului argumentativ", "section": "Lectură", "pages": "p. 168-169", "source": "Motive pentru care călătoriile te fac mai bun - Samantha Fanelli", "theory": [{"term": "Textul argumentativ și premisa", "kind": "definition", "text": "Textul argumentativ are scopul de a convinge cititorii cu privire la o opinie sau un punct de vedere față de o idee pusă în discuție. Opinia sau punctul de vedere se formulează într-un enunț numit premisă (sau ipoteză, teză). Premisa se formulează într-un enunț prin care se exprimă acordul sau dezacordul față de problemă.", "examples": ["Cred că printre momentele care te ajută să te dezvolți se numără și călătoriile.", "Nu cred că prin călătorii ajungi să te cunoști pe tine."], "important": true}, {"term": "Argumentele", "kind": "definition", "text": "Pentru a convinge cititorul, se folosesc argumente, adică idei care susțin punctul de vedere formulat în premisă. Argumentele pot fi fapte, dovezi, exemple, impresii, convingeri personale, culturale etc. Argumentele sunt însoțite de exemple care le fac credibile.", "examples": [], "important": true}, {"term": "Contraargumentele", "kind": "definition", "text": "În textul argumentativ, uneori, apar contraargumente, care combat păreri ce se referă la ideea din premisă.", "examples": ["Pe de altă parte, este adevărat că uneori lucrurile iau întorsături neașteptate și neplăcute atunci când călătorești."], "important": true}, {"term": "Concluzia", "kind": "definition", "text": "Textul argumentativ se încheie cu o concluzie, un enunț sintetic în care se reformulează afirmativ punctul de vedere din premisă, nuanțat după expunerea argumentelor.", "examples": [], "important": true}, {"term": "Schema textului argumentativ", "kind": "classification", "text": "Modelul textual: Introducere (a - este formulată premisa) -> Cuprins (b - argument 1, argument 2, argument n; c - susținerea argumentelor cu exemple) -> Încheiere (d - concluzie). Model: Este bine să călătorești (a), pentru că astfel îți poți depăși limitele (b). De exemplu, când am urcat pe vârful Moldoveanu, am descoperit că îmi pot învinge teama de înălțime (c). Așadar, călătorind, te poți descoperi pe tine (d).", "examples": ["Este bine să călătorești (a), pentru că astfel îți poți depăși limitele (b). De exemplu, când am urcat pe vârful Moldoveanu, am descoperit că îmi pot învinge teama de înălțime (c). Așadar, călătorind, te poți descoperi pe tine (d)."], "important": false}, {"term": "Cuvinte și formule specifice textului argumentativ", "kind": "classification", "text": "În textul argumentativ se utilizează cuvinte și formule specifice:\n- care asigură ierarhizarea argumentelor: în primul rând..., în al doilea rând..., mai întâi..., apoi..., după aceea..., nu în ultimul rând..., în cele din urmă... etc.;\n- prin care se introduc exemplele care susțin argumentele: de exemplu..., astfel, de pildă etc.;\n- care asigură legătura dintre idei: pentru că..., deoarece..., ca urmare..., spre deosebire de... etc.;\n- prin care se introduce concluzia: în concluzie..., așadar... etc.", "examples": ["în primul rând", "de exemplu", "pentru că", "în concluzie"], "important": false}, {"term": "Formule de implicare a cititorilor; timpul verbal", "kind": "rule", "text": "Uneori, în textul argumentativ apar și cuvinte sau formule specifice care asigură implicarea cititorilor: după cum știți..., așa cum vă dați seama..., nu cred că vă îndoiți de... etc.\nÎn general, timpul verbal utilizat în textul argumentativ este prezentul modului indicativ.", "examples": ["după cum știți...", "așa cum vă dați seama..."], "important": false}], "flashcards": [{"front": "Care este scopul textului argumentativ?", "back": "Să convingă cititorii cu privire la o opinie sau un punct de vedere.", "n": [0]}, {"front": "Ce este premisa?", "back": "Enunțul în care se formulează opinia/punctul de vedere (se mai numește ipoteză sau teză).", "n": [0]}, {"front": "Ce sunt argumentele?", "back": "Idei care susțin punctul de vedere din premisă (fapte, dovezi, exemple, impresii, convingeri).", "n": [1]}, {"front": "Ce sunt contraargumentele?", "back": "Enunțuri care combat păreri legate de ideea din premisă.", "n": [2]}, {"front": "Ce este concluzia?", "back": "Enunț sintetic care reformulează afirmativ punctul de vedere din premisă, nuanțat după expunerea argumentelor.", "n": [3]}, {"front": "Care sunt cele trei părți ale textului argumentativ?", "back": "Introducerea, cuprinsul, încheierea.", "n": [4]}, {"front": "Ce timp verbal se folosește de obicei în textul argumentativ?", "back": "Prezentul modului indicativ.", "n": [6]}, {"front": "Dă exemple de conectori pentru introducerea concluziei.", "back": "în concluzie..., așadar...", "n": [4]}], "quiz": [{"type": "mcq", "q": "Care este scopul textului argumentativ?", "options": ["să amuze", "să convingă", "să descrie un peisaj", "să povestească o întâmplare"], "answer": 1, "why": "Textul argumentativ are scopul de a convinge cititorii.", "n": [0]}, {"type": "fill", "q": "Opinia sau punctul de vedere dintr-un text argumentativ se formulează într-un enunț numit ____.", "answers": ["premisă", "premisa", "ipoteză", "teză"], "why": "Se numește premisă (sau ipoteză, teză).", "n": [0]}, {"type": "tf", "q": "Argumentele pot fi fapte, dovezi, exemple, impresii sau convingeri personale.", "answer": true, "why": "Așa este precizat în manual.", "n": [1]}, {"type": "tf", "q": "Concluzia contrazice complet premisa.", "answer": false, "why": "Concluzia reformulează afirmativ punctul de vedere din premisă, nuanțat.", "n": [3]}, {"type": "match", "q": "Potrivește partea textului cu elementul corespunzător.", "pairs": [["Introducerea", "premisa"], ["Cuprinsul", "argumente susținute cu exemple"], ["Încheierea", "concluzia"]], "n": [4]}, {"type": "classify", "q": "Încadrează formulele.", "categories": ["Ierarhizează argumentele", "Introduc exemple", "Introduc concluzia"], "items": [{"t": "în primul rând", "c": 0}, {"t": "de exemplu", "c": 1}, {"t": "în concluzie", "c": 2}, {"t": "de pildă", "c": 1}, {"t": "nu în ultimul rând", "c": 0}, {"t": "așadar", "c": 2}], "n": [5]}, {"type": "mcq", "q": "Ce combat contraargumentele?", "options": ["propria concluzie", "păreri legate de ideea din premisă", "exemplele", "titlul"], "answer": 1, "why": "Contraargumentele combat păreri ce se referă la ideea din premisă.", "n": [2]}, {"type": "mcq", "q": "Ce timp verbal se folosește în general în textul argumentativ?", "options": ["perfectul simplu", "imperfectul", "prezentul indicativ", "viitorul"], "answer": 2, "why": "De regulă, prezentul modului indicativ.", "n": [6]}]}, {"id": "u5-l8", "number": 8, "title": "Noi pagini - alte idei", "section": "Lectură", "pages": "p. 170-171", "source": "George și cheia secretă a Universului - Lucy și Stephen Hawking", "theory": [{"term": "Metoda SINELG (semnele de lectură)", "kind": "rule", "text": "Citește textul folosind metoda SINELG. Pe măsură ce îl parcurgi, notează pe margine, cu creionul, următoarele semne:\n✓ dacă ceva din ceea ce ai citit confirmă ceea ce știi sau crezi că știi;\n- dacă situația/informația contrazice sau diferă de ceea ce știi sau crezi că știi;\n+ dacă situația/informația este nouă;\n? dacă situația/informația este neclară sau dacă vrei să știi mai multe despre aspectul respectiv.", "examples": ["+ = informație nouă", "? = neclar / vreau să aflu mai mult"], "important": false}], "flashcards": [{"front": "SINELG: ce înseamnă semnul +?", "back": "Situația/informația este nouă.", "n": [0]}, {"front": "SINELG: ce înseamnă semnul -?", "back": "Informația contrazice sau diferă de ceea ce știi sau crezi că știi.", "n": [0]}, {"front": "SINELG: ce înseamnă semnul ?", "back": "Informația este neclară sau vrei să afli mai multe.", "n": [0]}, {"front": "SINELG: ce înseamnă bifa (✓)?", "back": "Informația confirmă ceea ce știi sau crezi că știi.", "n": [0]}], "quiz": [{"type": "mcq", "q": "Ce semn SINELG notezi pentru o informație nouă?", "options": ["?", "-", "+", "✓"], "answer": 2, "why": "+ înseamnă că informația este nouă.", "n": [0]}, {"type": "mcq", "q": "Ce semn notezi când informația contrazice ceea ce știai?", "options": ["+", "-", "?", "✓"], "answer": 1, "why": "Semnul - marchează informațiile care contrazic ce știi.", "n": [0]}, {"type": "tf", "q": "În metoda SINELG, semnele se notează cu creionul, pe marginea textului, pentru a putea fi șterse ulterior.", "answer": true, "why": "Așa cere manualul.", "n": [0]}, {"type": "match", "q": "Potrivește semnul SINELG cu sensul.", "pairs": [["✓", "confirmă ce știi"], ["-", "contrazice ce știi"], ["+", "informație nouă"], ["?", "neclar / vreau mai multe informații"]], "n": [0]}, {"type": "fill", "q": "Cu semnul ____ notezi informațiile neclare sau despre care vrei să știi mai mult.", "answers": ["?", "semnul întrebării", "întrebării"], "why": "Semnul întrebării marchează neclaritatea.", "n": [0]}]}, {"id": "u5-l9", "number": 9, "title": "Limba română în Europa. Comunitatea lingvistică a vorbitorilor de limbă română de pretutindeni", "section": "Interculturalitate", "pages": "p. 172-174", "source": "În limba ta - Grigore Vieru; Despre limba română - Nichita Stănescu; e-mailul Luminiței", "theory": [{"term": "Limba română în lume", "kind": "definition", "text": "Limba română este utilizată de peste 24 000 000 de vorbitori din întreaga lume. Limba română este limba oficială a României, a Republicii Moldova și a provinciei Voivodina din Serbia. Este, în același timp, una dintre limbile oficiale ale Uniunii Europene.", "examples": [], "important": true}, {"term": "Limba română în Europa și în afara ei", "kind": "definition", "text": "În Europa, limba română se vorbește în comunitățile românești din Ucraina (Cernăuți, Bugeac, Transcarpatia, Balta), Serbia (Valea Timocului), Ungaria (Gyula), Bulgaria, Cipru, Italia, Spania. Există însă comunități de vorbitori de limbă română și în alte țări europene, de exemplu în Austria, Belgia, Germania, Irlanda, Portugalia, dar și în afara spațiului european, cei mai mulți trăind în Israel, Statele Unite ale Americii, Canada, Australia și Noua Zeelandă.", "examples": [], "important": true}, {"term": "Comunitatea lingvistică a vorbitorilor de limba română", "kind": "definition", "text": "Comunitatea lingvistică a vorbitorilor de limba română include nu doar țările în care limba română este limbă oficială sau limbă a minorităților etnice, ci și diaspora.", "examples": [], "important": true}, {"term": "Cursuri de limba română pentru străini", "kind": "tip", "text": "Cursuri pentru străinii care vor să învețe limba română se organizează în peste 50 de țări, printre care se numără China, Finlanda, Suedia și Turcia.", "examples": [], "important": true}, {"term": "Diaspora (istoria cuvântului)", "kind": "definition", "text": "Cuvântul diaspora a pătruns în limba română din franceză, în care a fost preluat din greacă. Diaspora este un cuvânt compus din: dia, care înseamnă „prin”, și spora – „a împrăștia” și a fost folosit în istorie pentru a numi totalitatea comunităților evreiești împrăștiate în afara Palestinei în urma captivității babiloniene (sec. al VI-lea î.H.) și, mai târziu, a cuceririi Ierusalimului (70 d.H.). În prezent, termenul desemnează orice grup etnic aflat în afara granițelor țării de origine.", "examples": ["dia = prin", "spora = a împrăștia"], "important": false}, {"term": "Ziua Limbii Române", "kind": "tip", "text": "Din 2013, în 31 august, în România și în comunitățile românești din întreaga lume, se sărbătorește Ziua Limbii Române, la aceeași dată cu Limba Noastră, o sărbătoare similară celebrată în Republica Moldova.", "examples": ["31 august"], "important": false}], "flashcards": [{"front": "Câți vorbitori are limba română în lume?", "back": "Peste 24 000 000", "n": [0]}, {"front": "Unde este limba română limbă oficială?", "back": "În România, Republica Moldova și provincia Voivodina din Serbia.", "n": [0]}, {"front": "Este limba română limbă oficială a Uniunii Europene?", "back": "Da, una dintre limbile oficiale ale UE.", "n": [0]}, {"front": "Ce înseamnă diaspora azi?", "back": "Orice grup etnic aflat în afara granițelor țării de origine.", "n": [4]}, {"front": "Din ce cuvinte grecești este compus diaspora?", "back": "dia = „prin” și spora = „a împrăștia”", "n": [4]}, {"front": "Cine alcătuiește comunitatea lingvistică a vorbitorilor de limba română?", "back": "Țările cu română limbă oficială sau a minorităților etnice, plus diaspora.", "n": [2]}, {"front": "Când se sărbătorește Ziua Limbii Române?", "back": "31 august (din 2013)", "n": [5]}, {"front": "În câte țări se organizează cursuri de română pentru străini?", "back": "În peste 50 de țări", "n": [3]}], "quiz": [{"type": "mcq", "q": "Care dintre următoarele este țară/regiune în care româna este limbă oficială?", "options": ["Republica Moldova", "Ungaria", "Bulgaria", "Ucraina"], "answer": 0, "why": "Româna este limbă oficială în România, Republica Moldova și Voivodina (Serbia); în Ungaria, Bulgaria și Ucraina există doar comunități românești.", "n": [0]}, {"type": "tf", "q": "Limba română este una dintre limbile oficiale ale Uniunii Europene.", "answer": true, "why": "Așa este precizat în manual.", "n": [0]}, {"type": "fill", "q": "Termenul ____ desemnează în prezent orice grup etnic aflat în afara granițelor țării de origine.", "answers": ["diaspora"], "why": "Aceasta este explicația cuvântului diaspora.", "n": [4]}, {"type": "fill", "q": "Ziua Limbii Române se sărbătorește pe ____ august.", "answers": ["31"], "why": "Din 2013, în 31 august.", "n": [5]}, {"type": "match", "q": "Potrivește elementul cu explicația.", "pairs": [["dia", "prin"], ["spora", "a împrăștia"], ["Voivodina", "provincie din Serbia cu română limbă oficială"], ["Valea Timocului", "comunitate românească din Serbia"]], "n": [0, 1, 4]}, {"type": "classify", "q": "Încadrează țările după cum româna este sau nu limbă oficială.", "categories": ["Română limbă oficială", "Nu este limbă oficială"], "items": [{"t": "România", "c": 0}, {"t": "Republica Moldova", "c": 0}, {"t": "Ungaria", "c": 1}, {"t": "Bulgaria", "c": 1}, {"t": "Voivodina (Serbia)", "c": 0}], "n": [0, 1]}, {"type": "mcq", "q": "Ce include comunitatea lingvistică a vorbitorilor de limba română?", "options": ["doar România", "doar țările cu română limbă oficială", "țările cu română limbă oficială sau a minorităților, și diaspora", "doar țările din UE"], "answer": 2, "why": "Include țările cu limbă oficială sau a minorităților etnice și diaspora.", "n": [2]}]}, {"id": "u5-l10", "number": 10, "title": "Performarea actelor de limbaj", "section": "Comunicare orală", "pages": "p. 176-177", "source": "", "theory": [{"term": "Actele de limbaj", "kind": "definition", "text": "Actele de limbaj sau de vorbire reprezintă unitatea minimală dintr-o situație concretă de comunicare. În comunicare sunt importante atât cuvintele și enunțurile în sine, cât și contextul în care apar, pentru că acesta influențează ceea ce înțelegem.", "examples": [], "important": true}, {"term": "Structura actului de limbaj", "kind": "definition", "text": "Orice act de limbaj presupune formularea de către un vorbitor a unei secvențe lingvistice, cu o anumită intenție, urmărind producerea unui efect asupra interlocutorului.", "examples": [], "important": true}, {"term": "Secvența lingvistică", "kind": "definition", "text": "Secvența lingvistică este un enunț construit de vorbitor prin respectarea regulilor fonetice, semantice și gramaticale ale unei limbi.", "examples": [], "important": true}, {"term": "Intenția vorbitorului", "kind": "definition", "text": "Orice vorbitor produce un enunț cu o anumită intenție, cu scopul de a acționa asupra interlocutorului: de a-l informa, de a-i atrage atenția, de a-i reproșa, de a-l amenința etc.", "examples": [], "important": true}, {"term": "Mijloace de exprimare a intenției", "kind": "classification", "text": "Intenția poate fi exprimată prin:\n- verbe care numesc actul de limbaj, folosite la modul indicativ, timpul prezent, persoana I, singular, de exemplu: afirm, rog, întreb, promit, mulțumesc, declar etc.;\n- verbe la modul imperativ;\n- diverse cuvinte sau grupuri de cuvinte, de exemplu: nu (marchează o interdicție sau un refuz), te rog, nu-i așa? etc.;\n- elemente paraverbale: intonația, tonul vocii, debitul verbal;\n- elemente nonverbale: gesturi, mimică.", "examples": ["afirm", "promit", "te rog", "nu-i așa?"], "important": true}, {"term": "Efectul actului de limbaj", "kind": "definition", "text": "Enunțul are un efect asupra vorbitorului: îl lasă indiferent, îl determină să acționeze, îi induce teamă etc.", "examples": [], "important": true}, {"term": "Actul de vorbire eficient / ineficient", "kind": "classification", "text": "Un act de vorbire poate fi:\n- eficient, când are asupra interlocutorului efectul dorit;\n- ineficient, când nu produce asupra interlocutorului efectul dorit.", "examples": [], "important": true}], "flashcards": [{"front": "Ce sunt actele de limbaj?", "back": "Unitatea minimală dintr-o situație concretă de comunicare.", "n": [0]}, {"front": "Ce presupune orice act de limbaj?", "back": "Formularea de către un vorbitor a unei secvențe lingvistice, cu o anumită intenție, pentru a produce un efect asupra interlocutorului.", "n": [1]}, {"front": "Ce este secvența lingvistică?", "back": "Un enunț construit prin respectarea regulilor fonetice, semantice și gramaticale ale limbii.", "n": [2]}, {"front": "Dă exemple de intenții ale vorbitorului.", "back": "a informa, a atrage atenția, a reproșa, a amenința", "n": [3]}, {"front": "Ce verbe numesc actul de limbaj (exprimă intenția)?", "back": "Verbe la indicativ prezent, persoana I singular (afirm, rog, întreb, promit, mulțumesc, declar).", "n": [4]}, {"front": "Când este eficient un act de vorbire?", "back": "Când are asupra interlocutorului efectul dorit.", "n": [6]}, {"front": "Ce sunt elementele paraverbale?", "back": "Intonația, tonul vocii, debitul verbal.", "n": [4]}, {"front": "Ce sunt elementele nonverbale?", "back": "Gesturile și mimica.", "n": [4]}], "quiz": [{"type": "mcq", "q": "Care este unitatea minimală dintr-o situație concretă de comunicare?", "options": ["cuvântul", "actul de limbaj", "propoziția", "paragraful"], "answer": 1, "why": "Actele de limbaj sunt unitatea minimală a comunicării concrete.", "n": [0]}, {"type": "tf", "q": "Contextul în care apare un enunț influențează ceea ce înțelegem.", "answer": true, "why": "Contextul este important în comunicare.", "n": [0]}, {"type": "tf", "q": "Un act de vorbire este ineficient când are asupra interlocutorului efectul dorit.", "answer": false, "why": "Atunci este eficient; ineficient este când NU produce efectul dorit.", "n": [6]}, {"type": "fill", "q": "Un act de vorbire este ____ când produce asupra interlocutorului efectul dorit.", "answers": ["eficient"], "why": "Eficient = efectul dorit.", "n": [6]}, {"type": "classify", "q": "Încadrează mijloacele de exprimare a intenției.", "categories": ["Verbal", "Paraverbal", "Nonverbal"], "items": [{"t": "verbul „promit”", "c": 0}, {"t": "tonul vocii", "c": 1}, {"t": "intonația", "c": 1}, {"t": "gestul", "c": 2}, {"t": "mimica", "c": 2}, {"t": "debitul verbal", "c": 1}], "n": [4]}, {"type": "match", "q": "Potrivește termenul cu explicația.", "pairs": [["secvență lingvistică", "enunț construit după regulile limbii"], ["intenție", "scopul de a acționa asupra interlocutorului"], ["efect", "reacția interlocutorului (indiferență, acțiune, teamă)"], ["act eficient", "produce efectul dorit"]], "n": [2, 3, 5]}, {"type": "mcq", "q": "Ce marchează cuvântul „nu” în exprimarea intenției?", "options": ["o promisiune", "o interdicție sau un refuz", "o întrebare", "o mulțumire"], "answer": 1, "why": "„nu” marchează o interdicție sau un refuz.", "n": [4]}]}, {"id": "u5-l11", "number": 11, "title": "Strategii de concepere și de comprehensiune a textului oral", "section": "Comunicare orală", "pages": "p. 178-179", "source": "", "theory": [{"term": "Parafrazarea", "kind": "definition", "text": "Parafrazarea constă în reformularea prin cuvinte proprii a unor texte sau a unor enunțuri, produse anterior de altcineva, păstrând intact sensul acestora.", "examples": [], "important": true}, {"term": "Tipuri de parafraze", "kind": "classification", "text": "Există parafraze care:\na) înlocuiesc cuvintele prin sinonime sau expresii sinonime;\nb) schimbă complet textul, dar păstrează ideile.", "examples": [], "important": true}, {"term": "Rolul parafrazei", "kind": "rule", "text": "Parafraza ajută la clarificarea unor idei sau la explicarea acestora într-un limbaj mai simplu, fiind o strategie de lămurire a ideilor sau de evitare a repetițiilor.", "examples": [], "important": true}, {"term": "Informațiile explicite", "kind": "definition", "text": "Informațiile explicite sunt cele pe care vorbitorii le formulează direct. (De exemplu, enunțul Lumea este atât de extraordinară! conține explicit informația că vorbitorul consideră lumea un loc extraordinar. O altă informație explicită din schimbul de replici dat o reprezintă existența fotografiilor în ghid.)", "examples": ["Lumea este atât de extraordinară!"], "important": true}, {"term": "Informațiile implicite", "kind": "definition", "text": "Informațiile implicite sunt cele care sunt deduse din context, fără a fi formulate direct. Ele sunt deducții pe care le fac interlocutorii pe baza informațiilor spuse direct și a celor pe care le dețin deja. (De exemplu, enunțul Lumea este atât de extraordinară! conține implicit informația că băiatul este entuziasmat de diversitatea lumii. O altă informație implicită din schimbul de replici de mai sus o reprezintă faptul că există și destinații mai puțin atractive.)", "examples": ["există și destinații mai puțin atractive"], "important": true}], "flashcards": [{"front": "Ce este parafrazarea?", "back": "Reformularea prin cuvinte proprii a unui text sau enunț produs de altcineva, păstrând intact sensul.", "n": [0]}, {"front": "Care sunt cele două tipuri de parafraze?", "back": "a) înlocuire cu sinonime sau expresii sinonime; b) schimbarea completă a textului, cu păstrarea ideilor.", "n": [1]}, {"front": "La ce ajută parafraza?", "back": "La clarificarea ideilor, explicarea lor mai simplă, evitarea repetițiilor.", "n": [2]}, {"front": "Ce sunt informațiile explicite?", "back": "Cele formulate direct de vorbitori.", "n": [3]}, {"front": "Ce sunt informațiile implicite?", "back": "Cele deduse din context, fără a fi formulate direct.", "n": [4]}, {"front": "Pe ce se bazează deducerea informațiilor implicite?", "back": "Pe informațiile spuse direct și pe cele pe care interlocutorii le dețin deja.", "n": [4]}], "quiz": [{"type": "mcq", "q": "Parafrazarea înseamnă:", "options": ["copierea exactă a unui text", "reformularea cu cuvinte proprii, păstrând sensul", "rezumarea doar a titlului", "traducerea în altă limbă"], "answer": 1, "why": "Parafrazarea = reformulare cu cuvinte proprii, cu sensul intact.", "n": [0]}, {"type": "tf", "q": "Într-o parafrază, sensul textului inițial trebuie păstrat intact.", "answer": true, "why": "Așa o definește manualul.", "n": [0]}, {"type": "tf", "q": "Informațiile implicite sunt cele formulate direct de vorbitor.", "answer": false, "why": "Acelea sunt explicite; cele implicite se deduc din context.", "n": [4]}, {"type": "fill", "q": "Informațiile ____ sunt deduse din context, fără a fi formulate direct.", "answers": ["implicite"], "why": "Aceasta este definiția informațiilor implicite.", "n": [4]}, {"type": "match", "q": "Potrivește termenul cu definiția.", "pairs": [["parafrazare", "reformulare cu cuvinte proprii, cu sensul păstrat"], ["informație explicită", "formulată direct"], ["informație implicită", "dedusă din context"]], "n": [0, 3, 4]}, {"type": "classify", "q": "Încadrează informațiile din dialogul cu ghidul de călătorie.", "categories": ["Explicită", "Implicită"], "items": [{"t": "ghidul conține fotografii atractive", "c": 0}, {"t": "băiatul consideră lumea extraordinară", "c": 0}, {"t": "există și destinații mai puțin atractive", "c": 1}, {"t": "băiatul este entuziasmat de diversitatea lumii", "c": 1}], "n": [3, 4]}, {"type": "mcq", "q": "Care dintre acestea este un tip de parafrază?", "options": ["înlocuirea cuvintelor prin sinonime", "repetarea exactă a textului", "adăugarea de idei noi", "eliminarea sensului"], "answer": 0, "why": "O parafrază poate înlocui cuvintele prin sinonime sau expresii sinonime.", "n": [1]}]}, {"id": "u5-l12", "number": 12, "title": "Adjectivul (actualizare)", "section": "Limbă română", "pages": "p. 180-181", "source": "", "theory": [{"term": "Adjectivul", "kind": "definition", "text": "Adjectivul este partea de vorbire care exprimă o însușire a unui obiect (lucru, ființă, fenomen al naturii etc.) și determină un substantiv. Adjectivele sunt: propriu-zise (bucuros); provenite din verb la participiu (adormit).", "examples": ["bucuros", "adormit"], "important": true}, {"term": "Adjective variabile și invariabile", "kind": "definition", "text": "Când își modifică forma în vorbire, adjectivele sunt variabile, iar când nu își modifică forma sunt invariabile.", "examples": [], "important": true}, {"term": "Formele flexionare ale adjectivelor variabile", "kind": "classification", "text": "Adjectivele variabile pot avea:\n- patru forme flexionare: frumos (masculin, singular), frumoasă (feminin, singular), frumoși (masculin, plural), frumoase (feminin, plural);\n- trei forme flexionare: adânc (masculin, singular), adâncă (feminin, singular), adânci (masculin și feminin, plural);\n- două forme flexionare: dulce (masculin și feminin, singular), dulci (masculin și feminin, plural).", "examples": ["frumos, frumoasă, frumoși, frumoase", "adânc, adâncă, adânci", "dulce, dulci"], "important": true}, {"term": "Adjective invariabile", "kind": "example", "text": "Dintre adjectivele invariabile fac parte antiglonț, eficace, vernil, violet.", "examples": ["antiglonț", "eficace", "vernil", "violet"], "important": false}, {"term": "Acordul și locul adjectivului", "kind": "rule", "text": "Adjectivul se acordă în gen, număr și caz cu substantivul determinat. Locul obișnuit al adjectivului este după substantivul determinat. Când se află înaintea substantivului, preia articolul hotărât de la acesta.", "examples": [], "important": true}, {"term": "Articolul demonstrativ (adjectival)", "kind": "rule", "text": "Articolul demonstrativ leagă un adjectiv de substantivul determinat. Articolul demonstrativ se acordă în gen, număr și caz cu substantivul determinat de adjectiv.", "examples": ["costumul cel alb", "steaua cea luminoasă"], "important": true}, {"term": "Formele articolului demonstrativ", "kind": "classification", "text": "Forme ale articolului demonstrativ:\nMasculin singular: N-Ac-V cel; G-D celui.\nMasculin plural: N-Ac-V cei; G-D celor.\nFeminin singular: N-Ac-V cea; G-D celei.\nFeminin plural: N-Ac-V cele; G-D celor.", "examples": ["cel, cei, cea, cele", "celui, celor, celei"], "important": false}, {"term": "Gradele de comparație ale adjectivului (definiție)", "kind": "definition", "text": "Gradele de comparație sunt formele pe care le ia adjectivul pentru a arăta în ce măsură un obiect are o însușire în raport cu alte obiecte sau cu alte momente ale existenței sale.", "examples": [], "important": true}, {"term": "Gradele de comparație ale adjectivului (clasificare)", "kind": "classification", "text": "pozitiv: piatră strălucitoare\ncomparativ de egalitate: piatră tot atât de strălucitoare, piatră la fel de strălucitoare\ncomparativ de inegalitate - superioritate: piatră mai strălucitoare\ncomparativ de inegalitate - inferioritate: piatră mai puțin strălucitoare\nsuperlativ relativ de superioritate: piatra cea mai strălucitoare\nsuperlativ relativ de inferioritate: piatra cea mai puțin strălucitoare\nsuperlativ absolut de superioritate: piatră foarte strălucitoare\nsuperlativ absolut de inferioritate: piatră foarte puțin strălucitoare", "examples": ["piatră strălucitoare", "piatră mai strălucitoare", "piatra cea mai strălucitoare", "piatră foarte strălucitoare"], "important": true}, {"term": "Adjective fără grade de comparație", "kind": "rule", "text": "Unele adjective nu au grade de comparație, pentru că sunt la origine (în limba latină) comparative sau superlative (superior, inferior, anterior, posterior, optim etc.), pentru că însușirea exprimată nu poate fi modificată (complet, unic, principal etc.) sau pentru că sensul cuvântului nu permite comparația (cosmic, brașovean etc.).", "examples": ["superior", "inferior", "complet", "unic", "cosmic", "brașovean"], "important": false}, {"term": "Model de analiză a adjectivului", "kind": "example", "text": "„cel mai răcoros” – adjectiv propriu-zis, variabil, cu patru forme flexionare, se acordă în gen, număr și caz cu substantivul „locul” (neutru, singular, acuzativ), grad de comparație superlativ relativ de superioritate, funcția sintactică de atribut adjectival.", "examples": ["locul cel mai răcoros"], "important": false}], "flashcards": [{"front": "Ce este adjectivul?", "back": "Partea de vorbire care exprimă o însușire a unui obiect și determină un substantiv.", "n": [0]}, {"front": "Ce feluri de adjective există?", "back": "Propriu-zise (bucuros) și provenite din verb la participiu (adormit).", "n": [0]}, {"front": "Câte forme flexionare are „frumos”?", "back": "Patru: frumos, frumoasă, frumoși, frumoase.", "n": [2]}, {"front": "Câte forme flexionare are „adânc”?", "back": "Trei: adânc, adâncă, adânci.", "n": [2]}, {"front": "Câte forme flexionare are „dulce”?", "back": "Două: dulce, dulci.", "n": [2]}, {"front": "Ce rol are articolul demonstrativ?", "back": "Leagă un adjectiv de substantivul determinat.", "n": [5]}, {"front": "Care sunt formele articolului demonstrativ la N-Ac-V?", "back": "cel, cei, cea, cele", "n": [6]}, {"front": "Care sunt gradele de comparație ale adjectivului?", "back": "Pozitiv, comparativ (egalitate, superioritate, inferioritate), superlativ (relativ și absolut).", "n": [7, 8]}, {"front": "Dă exemple de adjective invariabile.", "back": "antiglonț, eficace, vernil, violet", "n": [1, 3]}], "quiz": [{"type": "mcq", "q": "Adjectivul „frumos” are:", "options": ["două forme flexionare", "trei forme flexionare", "patru forme flexionare", "o singură formă"], "answer": 2, "why": "frumos, frumoasă, frumoși, frumoase.", "n": [2]}, {"type": "mcq", "q": "Care este gradul de comparație în „piatra cea mai strălucitoare”?", "options": ["comparativ de superioritate", "superlativ relativ de superioritate", "superlativ absolut de superioritate", "pozitiv"], "answer": 1, "why": "cea mai + adjectiv = superlativ relativ de superioritate.", "n": [8]}, {"type": "tf", "q": "Adjectivul se acordă în gen, număr și caz cu substantivul determinat.", "answer": true, "why": "Aceasta este regula acordului.", "n": [4]}, {"type": "tf", "q": "Locul obișnuit al adjectivului este înaintea substantivului determinat.", "answer": false, "why": "Locul obișnuit este după substantiv.", "n": [4]}, {"type": "fill", "q": "Articolul demonstrativ feminin singular la N-Ac-V este ____.", "answers": ["cea"], "why": "Forme: cel, cei, cea, cele.", "n": [6]}, {"type": "fill", "q": "„Piatră foarte strălucitoare” este exemplu de superlativ ____ de superioritate.", "answers": ["absolut"], "why": "foarte + adjectiv = superlativ absolut.", "n": [8]}, {"type": "classify", "q": "Încadrează adjectivele după numărul formelor flexionare.", "categories": ["Patru forme", "Trei forme", "Două forme"], "items": [{"t": "frumos", "c": 0}, {"t": "adânc", "c": 1}, {"t": "dulce", "c": 2}, {"t": "cuminte", "c": 2}, {"t": "mic", "c": 1}], "n": [2]}, {"type": "classify", "q": "Încadrează adjectivele după felul lor.", "categories": ["Propriu-zis", "Provenit din verb la participiu"], "items": [{"t": "bucuros", "c": 0}, {"t": "adormit", "c": 1}, {"t": "masiv", "c": 0}, {"t": "întunecat", "c": 1}], "n": [0]}, {"type": "match", "q": "Potrivește exemplul cu gradul de comparație.", "pairs": [["piatră strălucitoare", "pozitiv"], ["piatră mai strălucitoare", "comparativ de superioritate"], ["piatră la fel de strălucitoare", "comparativ de egalitate"], ["piatră mai puțin strălucitoare", "comparativ de inferioritate"]], "n": [8]}, {"type": "mcq", "q": "Care adjectiv NU are grade de comparație?", "options": ["frumos", "unic", "mare", "gras"], "answer": 1, "why": "Însușirea exprimată de „unic” nu poate fi modificată.", "n": [9]}]}, {"id": "u5-l13", "number": 13, "title": "Posibilități combinatorii ale adjectivului", "section": "Limbă română", "pages": "p. 182-183", "source": "", "theory": [{"term": "Adjectivul: adjunct și centru", "kind": "definition", "text": "Adjectivul se poate combina în propoziții cu alte cuvinte, fiind:\n- adjunct într-un grup de cuvinte, de exemplu: drum lung;\n- centru al unui grup de cuvinte, de exemplu: drum plin de gropi.\nPentru adjectiv, definitorie este calitatea de adjunct.", "examples": ["drum lung", "drum plin de gropi"], "important": true}, {"term": "Atributul adjectival", "kind": "definition", "text": "În propoziție, adjectivul adjunct are funcția sintactică de atribut adjectival, atunci când determină un substantiv.", "examples": ["Copiii au călătorit prin spațiul cosmic."], "important": true}, {"term": "Numele predicativ", "kind": "definition", "text": "Adjectivul adjunct are funcția sintactică de nume predicativ, atunci când precizează caracteristica subiectului, de care se leagă prin verbul copulativ a fi, intrând într-o relație ternară cu acestea. Numele predicativ se acordă în gen, număr și caz cu subiectul.", "examples": ["Annie este inteligentă."], "important": true}, {"term": "Dublu rol: adjunct și centru", "kind": "rule", "text": "Adjectivul poate îndeplini în același timp un rol dublu, de adjunct și de centru.", "examples": ["Piatra strălucitoare ca soarele l-a atras."], "important": false}, {"term": "Adjunctul adjectivului", "kind": "rule", "text": "Adjunctul adjectivului poate fi un substantiv precedat de prepoziție, care are funcția sintactică de complement (prepozițional și indirect) sau circumstanțial (de loc, de timp sau de mod).", "examples": ["George este un băiat dornic de aventură (complement prepozițional) și recunoscător prietenilor (complement indirect).", "Băiatul era ud la picioare. (circumstanțial de loc)", "Maria este agitată încă de la primirea veștii. (circumstanțial de timp)", "Piatra strălucitoare ca soarele l-a atras. (circumstanțial de mod)"], "important": false}], "flashcards": [{"front": "Care este calitatea definitorie a adjectivului în combinații?", "back": "Cea de adjunct.", "n": [0]}, {"front": "Ce funcție are adjectivul care determină un substantiv?", "back": "Atribut adjectival.", "n": [1]}, {"front": "Ce funcție are adjectivul legat de subiect prin verbul copulativ a fi?", "back": "Nume predicativ.", "n": [2]}, {"front": "Cu ce se acordă numele predicativ?", "back": "Cu subiectul, în gen, număr și caz.", "n": [2]}, {"front": "Ce funcții poate avea adjunctul unui adjectiv (substantiv cu prepoziție)?", "back": "Complement (prepozițional, indirect) sau circumstanțial (de loc, timp, mod).", "n": [4]}, {"front": "Ce funcție are „ca soarele” în „piatra strălucitoare ca soarele”?", "back": "Circumstanțial de mod.", "n": [4]}], "quiz": [{"type": "mcq", "q": "În „Copiii au călătorit prin spațiul cosmic”, adjectivul „cosmic” are funcția de:", "options": ["nume predicativ", "atribut adjectival", "subiect", "complement"], "answer": 1, "why": "Determină substantivul „spațiul”.", "n": [1]}, {"type": "mcq", "q": "În „Annie este inteligentă”, „inteligentă” este:", "options": ["atribut adjectival", "complement", "nume predicativ", "circumstanțial"], "answer": 2, "why": "Se leagă de subiect prin verbul copulativ a fi.", "n": [2]}, {"type": "tf", "q": "Pentru adjectiv, definitorie este calitatea de adjunct.", "answer": true, "why": "Așa afirmă manualul.", "n": [0]}, {"type": "tf", "q": "Numele predicativ nu se acordă cu subiectul.", "answer": false, "why": "Se acordă în gen, număr și caz cu subiectul.", "n": [2]}, {"type": "fill", "q": "Adjectivul care determină un substantiv are funcția de atribut ____.", "answers": ["adjectival"], "why": "Atribut adjectival.", "n": [1]}, {"type": "fill", "q": "Verbul copulativ care leagă numele predicativ de subiect în exemplele din manual este a ____.", "answers": ["fi"], "why": "Verbul copulativ a fi.", "n": [2]}, {"type": "match", "q": "Potrivește exemplul cu funcția sintactică a adjunctului adjectivului.", "pairs": [["dornic de aventură", "complement prepozițional"], ["recunoscător prietenilor", "complement indirect"], ["ud la picioare", "circumstanțial de loc"], ["agitată încă de la primirea veștii", "circumstanțial de timp"], ["strălucitoare ca soarele", "circumstanțial de mod"]], "n": [4]}, {"type": "classify", "q": "Stabilește funcția adjectivului subliniat.", "categories": ["Atribut adjectival", "Nume predicativ"], "items": [{"t": "drum lung (substantiv + adjectiv)", "c": 0}, {"t": "Costumele astronauților sunt grele.", "c": 1}, {"t": "Astronautul Neil Armstrong este celebru.", "c": 1}, {"t": "cerul înstelat", "c": 0}], "n": [1, 2]}, {"type": "tf", "q": "Adjectivul poate îndeplini în același timp rolul de adjunct și pe cel de centru.", "answer": true, "why": "Adjectivul poate îndeplini în același timp un rol dublu, de adjunct și de centru.", "n": [3]}]}, {"id": "u5-l14", "number": 14, "title": "Adverbul. Felurile adverbului", "section": "Limbă română", "pages": "p. 184-185", "source": "", "theory": [{"term": "Adverbul", "kind": "definition", "text": "Adverbul este partea de vorbire care determină un verb și care exprimă împrejurările desfășurării unei acțiuni.", "examples": [], "important": true}, {"term": "Felurile adverbului după înțeles", "kind": "classification", "text": "După înțeles, adverbele sunt:\n- de loc (aici, deasupra, jos, sus);\n- de timp (acum, astăzi, curând, mereu);\n- de mod (agale, alene, așa, bine).", "examples": ["aici, deasupra, jos, sus", "acum, astăzi, curând, mereu", "agale, alene, așa, bine"], "important": true}, {"term": "Adverbul este invariabil", "kind": "rule", "text": "Adverbul nu își schimbă forma în funcție de context.", "examples": [], "important": true}], "flashcards": [{"front": "Ce este adverbul?", "back": "Partea de vorbire care determină un verb și exprimă împrejurările desfășurării unei acțiuni.", "n": [0]}, {"front": "Care sunt felurile adverbului după înțeles?", "back": "De loc, de timp, de mod.", "n": [1]}, {"front": "Exemple de adverbe de loc.", "back": "aici, deasupra, jos, sus", "n": [1]}, {"front": "Exemple de adverbe de timp.", "back": "acum, astăzi, curând, mereu", "n": [1]}, {"front": "Exemple de adverbe de mod.", "back": "agale, alene, așa, bine", "n": [1]}, {"front": "Își schimbă adverbul forma după context?", "back": "Nu, este invariabil.", "n": [2]}], "quiz": [{"type": "mcq", "q": "Adverbul determină, în general:", "options": ["un substantiv", "un verb", "un pronume", "o prepoziție"], "answer": 1, "why": "Adverbul determină un verb.", "n": [0]}, {"type": "tf", "q": "Adverbul își schimbă forma în funcție de context.", "answer": false, "why": "Adverbul nu își schimbă forma.", "n": [2]}, {"type": "fill", "q": "Adverbul „astăzi” este un adverb de ____.", "answers": ["timp"], "why": "Exemplu de adverb de timp.", "n": [1]}, {"type": "fill", "q": "Adverbul „jos” este un adverb de ____.", "answers": ["loc"], "why": "Exemplu de adverb de loc.", "n": [1]}, {"type": "classify", "q": "Încadrează adverbele.", "categories": ["De loc", "De timp", "De mod"], "items": [{"t": "aici", "c": 0}, {"t": "sus", "c": 0}, {"t": "mereu", "c": 1}, {"t": "curând", "c": 1}, {"t": "agale", "c": 2}, {"t": "bine", "c": 2}, {"t": "deasupra", "c": 0}, {"t": "acum", "c": 1}], "n": [1]}, {"type": "match", "q": "Potrivește adverbul cu felul lui.", "pairs": [["deasupra", "de loc"], ["astăzi", "de timp"], ["alene", "de mod"], ["mereu", "de timp"]], "n": [1]}]}, {"id": "u5-l15", "number": 15, "title": "Gradele de comparație și funcțiile sintactice ale adverbului", "section": "Limbă română", "pages": "p. 186-187", "source": "", "theory": [{"term": "Gradele de comparație ale adverbului", "kind": "classification", "text": "Gradele de comparație ale adverbului sunt aceleași ca ale adjectivului:\npozitiv: învață bine\ncomparativ de egalitate: învață tot atât de bine, învață la fel de bine\ncomparativ de inegalitate - superioritate: învață mai bine\ncomparativ de inegalitate - inferioritate: învață mai puțin bine\nsuperlativ relativ de superioritate: învață cel mai bine\nsuperlativ relativ de inferioritate: învață cel mai puțin bine\nsuperlativ absolut de superioritate: învață foarte bine\nsuperlativ absolut de inferioritate: învață foarte puțin bine", "examples": ["învață bine", "învață mai bine", "învață cel mai bine", "învață foarte bine"], "important": true}, {"term": "Adverbe fără grade de comparație", "kind": "rule", "text": "Majoritatea adverbelor nu au grade de comparație; de exemplu: acolo, aici, ieri, firește etc.", "examples": ["acolo", "aici", "ieri", "firește"], "important": true}, {"term": "Funcțiile sintactice ale adverbului", "kind": "classification", "text": "Adverbul poate avea funcție sintactică de:\n- circumstanțial de loc; răspunde la întrebările: unde?, de unde?, pe unde?, încotro?, dincotro? De exemplu: Elevii au ieșit afară.\n- circumstanțial de timp; răspunde la întrebările: când?, de când?, până când?, cât timp? etc. De exemplu: Acum, elevii se joacă în curte.\n- circumstanțial de mod; răspunde la întrebarea cum?, în ce mod? etc. De exemplu: Toți elevii învață bine.", "examples": ["Elevii au ieșit afară.", "Acum, elevii se joacă în curte.", "Toți elevii învață bine."], "important": true}, {"term": "Semiadverbele", "kind": "definition", "text": "Unele adverbe nu au funcție sintactică. Acestea se numesc semiadverbe. De exemplu: Îl tot caut. Mă cam grăbesc. Mai vine doar o colegă.", "examples": ["Îl tot caut.", "Mă cam grăbesc.", "Mai vine doar o colegă."], "important": true}], "flashcards": [{"front": "Care sunt gradele de comparație ale adverbului?", "back": "Aceleași ca ale adjectivului: pozitiv, comparativ, superlativ.", "n": [0]}, {"front": "Ce grad este „învață mai bine”?", "back": "Comparativ de superioritate.", "n": [0]}, {"front": "Ce grad este „învață cel mai bine”?", "back": "Superlativ relativ de superioritate.", "n": [0]}, {"front": "Ce grad este „învață foarte bine”?", "back": "Superlativ absolut de superioritate.", "n": [0]}, {"front": "Au majoritatea adverbelor grade de comparație?", "back": "Nu (acolo, aici, ieri, firește).", "n": [1]}, {"front": "La ce întrebări răspunde circumstanțialul de loc?", "back": "unde?, de unde?, pe unde?, încotro?, dincotro?", "n": [2]}, {"front": "La ce întrebări răspunde circumstanțialul de timp?", "back": "când?, de când?, până când?, cât timp?", "n": [2]}, {"front": "Ce sunt semiadverbele?", "back": "Adverbe fără funcție sintactică (tot, cam, mai).", "n": [3]}], "quiz": [{"type": "mcq", "q": "Care este gradul de comparație în „învață la fel de bine”?", "options": ["comparativ de egalitate", "comparativ de superioritate", "superlativ relativ", "pozitiv"], "answer": 0, "why": "la fel de / tot atât de = comparativ de egalitate.", "n": [0]}, {"type": "mcq", "q": "Care adverb are grade de comparație?", "options": ["acolo", "ieri", "bine", "firește"], "answer": 2, "why": "Majoritatea adverbelor (acolo, ieri, firește) nu au grade; „bine” are.", "n": [1]}, {"type": "tf", "q": "Majoritatea adverbelor au grade de comparație.", "answer": false, "why": "Majoritatea nu au grade de comparație.", "n": [1]}, {"type": "tf", "q": "Semiadverbele nu au funcție sintactică.", "answer": true, "why": "Așa se definesc semiadverbele.", "n": [3]}, {"type": "fill", "q": "„Mă cam grăbesc” – cuvântul „cam” este un ____.", "answers": ["semiadverb"], "why": "Nu are funcție sintactică.", "n": [3]}, {"type": "fill", "q": "Adverbul din „Elevii au ieșit afară” are funcția de circumstanțial de ____.", "answers": ["loc"], "why": "Răspunde la întrebarea unde?", "n": [2]}, {"type": "classify", "q": "Stabilește funcția adverbului subliniat.", "categories": ["Circumstanțial de loc", "Circumstanțial de timp", "Circumstanțial de mod"], "items": [{"t": "Acum, elevii se joacă în curte. (acum)", "c": 1}, {"t": "Elevii au ieșit afară. (afară)", "c": 0}, {"t": "Toți elevii învață bine. (bine)", "c": 2}, {"t": "Acolo au lucrat bine. (acolo)", "c": 0}], "n": [2]}, {"type": "match", "q": "Potrivește exemplul cu gradul de comparație.", "pairs": [["învață bine", "pozitiv"], ["învață mai puțin bine", "comparativ de inferioritate"], ["învață cel mai puțin bine", "superlativ relativ de inferioritate"], ["învață foarte puțin bine", "superlativ absolut de inferioritate"]], "n": [0]}]}, {"id": "u5-l16", "number": 16, "title": "Transformarea vorbirii directe în vorbire indirectă", "section": "Redactare", "pages": "p. 188-189", "source": "", "theory": [{"term": "Vorbirea directă", "kind": "definition", "text": "Vorbirea directă reprezintă reproducerea întocmai a cuvintelor atribuite unei persoane sau unui personaj.", "examples": ["„— Nu pot! zbiară Goe dinăuntru.”"], "important": true}, {"term": "Vorbirea indirectă", "kind": "definition", "text": "Vorbirea indirectă reprezintă redarea, prin relatare, a spuselor unei persoane sau ale unui personaj.", "examples": ["Din interior, Goe strigă că nu poate."], "important": true}, {"term": "Trecerea vorbirii directe în vorbire indirectă", "kind": "rule", "text": "Trecerea vorbirii directe în vorbire indirectă se realizează prin:\n- eliminarea liniei de dialog;\n- folosirea verbelor de declarație;\n- plasarea, după verbele de declarație, a unor cuvinte de legătură, precum că, să, ca să, dacă, unde, când, care etc.;\n- eliminarea enunțurilor imperative, exclamative, interogative;\n- trecerea verbelor și a pronumelor de la persoana I sau a II-a la persoana a III-a;\n- trecerea verbelor de la modul imperativ la modul conjunctiv;\n- trecerea substantivelor în cazul vocativ la acuzativ sau dativ;\n- eliminarea cuvintelor care sunt exclamații sau imită sunete din natură;\n- reproducerea cât mai exactă a cuvintelor personajului.", "examples": ["„— Aide! zice mam’ mare, ieși odată! Ne-ai speriat.” -> Bunica îi cere să iasă odată, fiindcă le-a speriat.", "„— Goe! maică! Acolo ești?” -> Bunica îl întreabă pe Goe dacă este în acel loc."], "important": true}], "flashcards": [{"front": "Ce este vorbirea directă?", "back": "Reproducerea întocmai a cuvintelor atribuite unei persoane sau unui personaj.", "n": [0]}, {"front": "Ce este vorbirea indirectă?", "back": "Redarea, prin relatare, a spuselor unei persoane sau ale unui personaj.", "n": [1]}, {"front": "Ce se întâmplă cu linia de dialog la trecerea în vorbire indirectă?", "back": "Se elimină.", "n": [2]}, {"front": "Ce cuvinte de legătură se plasează după verbul de declarație?", "back": "că, să, ca să, dacă, unde, când, care etc.", "n": [2]}, {"front": "La ce persoană trec verbele și pronumele?", "back": "De la persoana I sau a II-a la persoana a III-a.", "n": [2]}, {"front": "Ce se întâmplă cu modul imperativ?", "back": "Trece la modul conjunctiv.", "n": [2]}, {"front": "Ce se întâmplă cu vocativul?", "back": "Trece la acuzativ sau dativ.", "n": [2]}, {"front": "Ce se elimină dintre enunțuri și cuvinte?", "back": "Enunțurile imperative, exclamative, interogative și exclamațiile/onomatopeele.", "n": [2]}], "quiz": [{"type": "mcq", "q": "Care dintre acestea reprezintă vorbirea directă?", "options": ["Bunica îl întreabă pe Goe dacă este acolo.", "— Goe! maică! Acolo ești?", "Goe strigă că nu poate.", "Ea a spus că i-a plăcut."], "answer": 1, "why": "Vorbirea directă reproduce întocmai cuvintele personajului, cu linie de dialog.", "n": [0, 1]}, {"type": "tf", "q": "În vorbirea indirectă se păstrează linia de dialog.", "answer": false, "why": "Linia de dialog se elimină.", "n": [2]}, {"type": "tf", "q": "Verbele de la persoana I sau a II-a trec la persoana a III-a în vorbirea indirectă.", "answer": true, "why": "Așa cere regula transformării.", "n": [2]}, {"type": "fill", "q": "Verbele de la modul imperativ trec, în vorbirea indirectă, la modul ____.", "answers": ["conjunctiv"], "why": "Imperativ -> conjunctiv.", "n": [2]}, {"type": "fill", "q": "Substantivul în cazul vocativ trece la acuzativ sau ____.", "answers": ["dativ"], "why": "Vocativ -> acuzativ sau dativ.", "n": [2]}, {"type": "match", "q": "Potrivește elementul din vorbirea directă cu transformarea.", "pairs": [["linia de dialog", "se elimină"], ["imperativ", "trece la conjunctiv"], ["vocativ", "trece la acuzativ sau dativ"], ["persoana I/a II-a", "trece la persoana a III-a"]], "n": [2]}, {"type": "classify", "q": "Încadrează cuvintele de legătură și elementele.", "categories": ["Cuvânt de legătură după verbul de declarație", "Se elimină la transformare"], "items": [{"t": "că", "c": 0}, {"t": "dacă", "c": 0}, {"t": "linia de dialog", "c": 1}, {"t": "ca să", "c": 0}, {"t": "exclamațiile", "c": 1}], "n": [2]}, {"type": "mcq", "q": "Care cuvânt de legătură se folosește după un verb de declarație pentru o întrebare totală (da/nu)?", "options": ["dacă", "că", "ca să", "care"], "answer": 0, "why": "„Bunica îl întreabă pe Goe dacă este acolo.”", "n": [2]}]}]}]};
